window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0171", [{"word":"compassion","ipa_uk":"/kəmˈpæʃn/","ipa_us":"/kəmˈpæʃn/","definition_zh":"同情；怜悯（对他人苦难的感同身受）；慈悲（宗教伦理中对一切众生的普世悲悯）；体恤（制度与专业照护中的关怀）","definition_en":"a strong feeling of sympathy for someone who is suffering, together with a wish to relieve that suffering","core_image":"一个人蹲在受伤者身旁，把手停在伤口上方，自己的眉头也跟着皱起，疼痛仿佛在两个人身上同时发生","scene":"医院的走廊里，一位家属刚收到坏消息，护士没有急着递上表格，而是先坐下来握住对方的手。Her compassion showed in the way she sat down beside the family instead of handing them a form.","sceneCN":"这里 compassion 指「见到他人受苦而心生不忍的同情」（第 1 个义项：因他人受苦而生的带痛感的同情）；句意为她的同情体现在她坐下来陪在家属身边，而不是直接递表格。可辨识物件：走廊长椅、握在一起的手、未递出的表格、病区门牌。","pos":[{"tag":"n.","zh":"同情；怜悯；慈悲；体恤（不可数）"}],"collocations":[{"phrase":"show compassion","zh":"表现出同情"},{"phrase":"feel compassion for","zh":"对……感到怜悯"},{"phrase":"out of compassion","zh":"出于同情"},{"phrase":"deep compassion","zh":"深切的悲悯"},{"phrase":"with compassion","zh":"带着体恤地"},{"phrase":"compassion fatigue","zh":"同情疲劳（长期照护者的情感耗竭）"}],"forms":[{"label":"复数（少见，指一次次的怜悯之情）","form":"compassions"},{"label":"形容词","form":"compassionate"},{"label":"副词","form":"compassionately"},{"label":"名词（有同情心这一性质，少用）","form":"compassionateness"}],"derivatives":[{"word":"compassionate","pos":"adj.","zh":"有同情心的；出于体恤的"},{"word":"compassionately","pos":"adv.","zh":"同情地；体恤地"},{"word":"compassionless","pos":"adj.","zh":"毫无同情的；冷酷的"},{"word":"compassionateness","pos":"n.","zh":"富于同情的性质"},{"word":"self-compassion","pos":"n.","zh":"自我悲悯（心理学用语）"}],"senses":[{"no":"01","title":"Sorrow felt for another's suffering","titleCN":"为他人受苦而心痛","definition":"a painful feeling of sympathy caused by another person's suffering","definitionCN":"因他人受苦而生出的、带着痛感的同情","example":"She looked at the injured dog with compassion rather than fear.","exampleCN":"她看着受伤的狗，心里是怜悯而不是害怕。","why":"The Latin verb behind the word means to suffer, and the prefix adds with, so the feeling is literally suffering alongside someone.","whyCN":"这个词背后的拉丁动词意为「受苦」，前缀又添上「共同」，所以这份感情字面上就是陪着别人一起受苦。"},{"no":"02","title":"The urge to relieve the pain","titleCN":"想要解除对方痛苦的冲动","definition":"the impulse to act so that the suffering person is helped or comforted","definitionCN":"想要采取行动，使受苦的人得到帮助或安慰的冲动","example":"His compassion turned into action within minutes: blankets, water and a phone call.","exampleCN":"几分钟之内，他的同情就变成了行动：毯子、热水和一通电话。","why":"Feeling another's pain naturally points outward, so the word often names the push that follows the feeling.","whyCN":"感受到别人的痛，自然会朝外指，因此这个词常指随感受而来的那股推力。"},{"no":"03","title":"Mercy shown to a wrongdoer","titleCN":"对犯错者的宽宥","definition":"lenient treatment of someone who has done wrong, given because their situation is understood rather than because the rule requires it","definitionCN":"因理解对方的处境而从轻处置犯错者，并非规则本身要求从轻","example":"The judge showed compassion and reduced the sentence by two years.","exampleCN":"法官动了怜悯，把刑期减了两年。","why":"Older legal and religious usage extended the idea of suffering alongside to the wrongdoer whose circumstances are pitied.","whyCN":"较早的法律与宗教用法把「一同受苦」延伸到犯错者身上，因为人们怜悯他的处境。"},{"no":"04","title":"Universal mercy in religious ethics","titleCN":"宗教伦理中的普世慈悲","definition":"in Buddhism and in Christian teaching, the unconditional wish that all living beings be free from suffering","definitionCN":"在佛教与基督教教义中，愿一切众生脱离苦难的无条件心愿","example":"The monks practise compassion towards every living creature, not only towards people.","exampleCN":"僧侣对一切生灵修习慈悲，而不只是对人。","why":"Religious teaching widened the feeling from one sufferer to all beings and made it a duty rather than a mood.","whyCN":"宗教教义把这份情感从某一个受苦者扩展到一切众生，并把它从一时心绪变成一种义务。"},{"no":"05","title":"Compassion as a clinical skill","titleCN":"作为专业能力的共情照护","definition":"in medicine and nursing, the trained ability to notice distress and respond to it humanely","definitionCN":"在医疗与护理中，经训练获得的察觉痛苦并予以温情回应的能力","example":"The programme treats compassion as a clinical skill that can be taught and assessed.","exampleCN":"该培养方案把共情照护当作可以教授、可以考核的临床能力。","why":"Modern care work redefined the feeling as a competence, because good intentions alone do not comfort a patient.","whyCN":"现代照护工作把这份情感重新定义为一种能力，因为只有好意并不能真正安慰病人。"},{"no":"06","title":"Compassion turned towards oneself","titleCN":"转向自己的悲悯","definition":"in psychology, kindness and understanding directed at one's own failure or pain instead of harsh self-criticism","definitionCN":"心理学中指以善意与理解对待自己的失败或痛苦，而非严厉自责","example":"Self-compassion helped her recover after the failed exam.","exampleCN":"自我悲悯帮她在考试失利后恢复过来。","why":"Psychology moved the same gesture inward: the sufferer and the one who responds are the same person.","whyCN":"心理学把同一个动作转向内：受苦的人与作出回应的人是同一个。"},{"no":"07","title":"Compassion written into policy","titleCN":"写入制度的体恤","definition":"a principle in public policy that decisions should weigh the hardship they create for people","definitionCN":"公共政策中的一项原则：决策须衡量它给人们造成的困苦","example":"Compassion in housing policy means rehousing families before winter rather than after.","exampleCN":"住房政策里的体恤，意味着在入冬前而不是入冬后才安置这些家庭。","why":"Once a society agrees that suffering matters, the feeling becomes a standard for decisions rather than a private emotion.","whyCN":"一旦社会认定疾苦值得重视，这份情感就成了决策的标准，而不只是私人情绪。"},{"no":"08","title":"A quality that can be cultivated","titleCN":"可以修习培养的品格","definition":"a disposition of the heart that religious and contemplative traditions hold can be strengthened by practice","definitionCN":"宗教与修心传统认为可通过练习增强的心性倾向","example":"Teachers spoke of compassion as something to be cultivated, not something one either has or lacks.","exampleCN":"老师们说同情是可以培养的，而不是有或没有的天生之物。","why":"The last sense generalises all the others: what began as a reaction is treated as a habit that grows.","whyCN":"最后一个义项把前面全部一般化：起初只是一种反应，后来被当作可以生长起来的习惯。"}],"etymology":{"intro":{"en":"Compassion comes from Latin compassio 'fellow-feeling, pity', built on compati 'to suffer with', which joins com- 'together' to pati 'to suffer, endure'. The religious sense came first in English.","cn":"compassion 来自拉丁 compassio「同感、怜悯」，其源是 compati「一同受苦」，由 com-「共同」加 pati「受苦、忍受」构成。英语中最早出现的是宗教义。"},"items":[{"era":"LATIN PATI","en":"The deponent verb pati meant 'to suffer, endure, undergo'. Its participle passus lies behind passion and passive. The pre-Latin origin of pati is reconstructed, never recorded.","cn":"这个异态动词意为「受苦、忍受、经历」。其分词形式是 passion 与 passive 的来源。pati 在拉丁语之前的来源属重构形式，并无记录。"},{"era":"LATIN COMPATI","en":"Com- 'with, together' plus pati produced compati, 'to suffer with another person, to feel pity for them'.","cn":"com-「共同」加 pati 构成 compati，意为「与另一个人一同受苦、为其感到怜悯」。"},{"era":"LATIN COMPASSIO","en":"The noun compassio named fellow-feeling and pity; the separate noun passio named suffering itself, and the two were often used side by side in Christian writing.","cn":"名词 compassio 表示同感与怜悯；另一个名词 passio 表示受苦本身，两者在基督教文献中常并置使用。"},{"era":"OLD FRENCH","en":"Compassion reached English through Old French, where it kept the religious colouring of shared suffering.","cn":"这个词经古法语进入英语，在古法语中仍带着「共同受苦」的宗教色彩。"},{"era":"ENGLISH 14TH CENTURY","en":"English records the word in the fourteenth century, at first for the sorrow of one Christian for another's pain; the everyday and clinical senses are much later.","cn":"英语文献在十四世纪记录此词，最初指基督徒为他人之苦而悲伤；日常义与临床义都晚得多。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date and deeper origin): the earliest English citation cannot be fixed to a single year, and no agreed Indo-European shape exists for the root of pati, so any form offered for it is a reconstruction.","cn":"来源不确定（首见年代与更深词源）：最早的英语书证无法确定到某一年；pati 的词根也没有公认的印欧形式，凡为其给出的形式均属重构形式。"}]},"similar":{"note":{"en":"Group one holds words built on the Latin suffering root and one Greek twin that is constantly mistaken for a relative; group two holds the near neighbours that share the feeling but differ in what they do with it.","cn":"第一组是同出拉丁「受苦」词根的几个词，以及一个常被误认同族的希腊语近亲；第二组是情感相近、但对待方式不同的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"passion","ipa":"/ˈpæʃn/","tag":"same root","definition":"Built on the Latin participle for having suffered; it names a strong emotion, or in Christian writing the suffering of Christ, and says nothing about helping anyone.","definitionCN":"由拉丁语中表示「已受苦」的分词构成；它指强烈情感，在基督教文献中指基督受难，并不含帮助他人之意。"},{"word":"patient","ipa":"/ˈpeɪʃnt/","tag":"same root","definition":"From the present participle of the same verb, 'the one who endures'; it names the person who bears an illness, not the person who feels for them.","definitionCN":"来自同一个动词的现在分词，意为「忍受着的人」；它指承受病痛的人，而不是为其动情的人。"},{"word":"passive","ipa":"/ˈpæsɪv/","tag":"same root","definition":"Also from the suffered participle; it describes receiving without acting, which is the opposite direction of movement from compassion.","definitionCN":"同样来自「已受苦」的分词；它描述承受而不行动，与 compassion 朝外伸手的方向正好相反。"},{"word":"sympathy","ipa":"/ˈsɪmpəθi/","tag":"different root","definition":"Greek pathos 'suffering' with syn- 'with': the same picture built from Greek stock, so the two words are near twins that share no root.","definitionCN":"希腊语 pathos「受苦」加 syn-「共同」构成：同一个图景却由希腊语的词素搭成，因此两词是近亲却不同源。"}]},{"heading":"NEAR MEANING","entries":[{"word":"pity","ipa":"/ˈpɪti/","tag":"sorrow at a distance","definition":"Sorrow for someone's misfortune, often with a hint of distance or condescension; compassion adds the wish to help and implies respect.","definitionCN":"对他人不幸的悲伤，常带一点距离感或居高临下；compassion 则多了帮助的意愿，并含有尊重。"},{"word":"empathy","ipa":"/ˈempəθi/","tag":"feeling with","definition":"The capacity to sense what another person feels; it can stay neutral and is sometimes used to manipulate, while compassion carries concern.","definitionCN":"感受他人情绪的能力；它可以保持中性，有时还被用来操纵他人，而 compassion 带有切实的关切。"},{"word":"mercy","ipa":"/ˈmɜːsi/","tag":"sparing from punishment","definition":"The act of holding back a punishment one has the power to inflict; it is the legal and religious face of compassion.","definitionCN":"本有能力施加惩罚却选择不加；它是 compassion 在法律与宗教中的面孔。"},{"word":"kindness","ipa":"/ˈkaɪndnəs/","tag":"general warmth","definition":"A warm and generous way of behaving; kindness can be shown without anyone being in pain.","definitionCN":"温和慷慨的待人方式；即使没有人正在受苦，也可以表现善意。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Latin morphemes, the real word family, the real fixed phrases, and the Greek near twin that is not a relative.","cn":"正常联想：真实的拉丁语素、真实的同族词、真实的固定搭配，以及那个并非同族的希腊语近亲。"},"normal":[{"en":"The Latin root means to suffer and the prefix means together, so compassion is suffering together with someone.","cn":"拉丁词根意为「受苦」，前缀意为「共同」，所以同情就是与某人一起受苦。"},{"en":"The family runs compassion, compassionate, compassionately, compassionless and self-compassion.","cn":"同族词包括 compassion、compassionate、compassionately、compassionless 与 self-compassion。"},{"en":"Fixed phrases mark the usual frame: show compassion, feel compassion for, out of compassion, with compassion.","cn":"固定搭配标出常用框架：表现出同情、对某人感到怜悯、出于同情、带着体恤地。"},{"en":"The Greek word sympathy describes the same picture from another stock, which is why the two look related but are not.","cn":"希腊语的 sympathy 用另一套词源描述同一个图景，因此两词看着像亲戚其实不是。"},{"en":"Care professions treat it as trainable: compassion training and compassion fatigue are working terms in hospitals.","cn":"照护行业把它视为可训练的：共情训练与同情疲劳在医院里都是正式说法。"}],"abstract":[{"en":"Picture two people sharing one ear, so that the pain heard by one is also heard by the other.","cn":"想象两个人共用一只耳朵，一个人听见的疼，另一个人也听见。"},{"en":"Picture a hand reaching out not to take anything but to lie under the place where someone is about to fall.","cn":"想象一只手伸出去不是为了拿东西，而是垫在别人将要摔倒的地方。"},{"en":"Picture a lamp lit not for the one who holds it but for the person who cannot see the step.","cn":"想象一盏灯不是为持灯者点的，而是为看不清台阶的人点的。"}]},"examples":[{"en":"The villagers treated the stranded climbers with compassion, opening their homes for three nights.","cn":"村民们对受困的登山者十分体恤，敞开家门收留了三夜。"},{"en":"Nurses are trained to combine technical skill with compassion.","cn":"护士受训时被要求把技术能力与体恤结合起来。"},{"en":"He acted out of compassion, not because anyone had asked him to.","cn":"他出手是出于同情，并不是因为有人要求他这么做。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「共同 + 受苦」——和对方一起受苦，就是同情；把这份心伸出去，就是怜悯与体恤","word":"compassion"},"root":"拉丁 compassio「同感、怜悯」← compati「一同受苦」= com-（共同）+ pati「受苦、忍受」；pati 的更深来源不确定，印欧形式属重构。英语 compassion。","sensesIntro":{"en":"Eight senses follow one movement: a person feels another's pain as if it were partly their own, and that feeling then turns into help, into leniency, into religious duty, into a clinical skill, into self-directed kindness, into policy and finally into a habit.","cn":"八个义项沿着同一个动作展开：一个人把他人的痛当成自己的一部分来感受，这份感受随后变成援手、变成宽宥、变成宗教义务、变成临床能力、变成对自己的善意、变成政策，最后变成习惯。"},"semanticMap":{"core":{"en":"CORE IMAGE: one person's pain registering inside another person's body.","cn":"核心意象：一个人的痛，在另一个人的身上也被感受到。"},"chain":["SEE THE PAIN","SUFFER ALONGSIDE","REACH OUT TO HELP","SPARE THE FALLEN","MERCY FOR ALL BEINGS","TAUGHT AND PRACTISED"],"branches":[{"senses":"01 · 02","en":"SEEING AND STAYING: the feeling and the impulse to act are one movement seen at two moments.","cn":"看见与停留：感受与出手的冲动，是同一个动作在两个时刻的样子。"},{"senses":"03","en":"THE FALLEN: when the sufferer has also done wrong, pity becomes leniency.","cn":"失足者：当受苦的人也犯了错，怜悯就变成从轻处置。"},{"senses":"04","en":"ALL BEINGS: religious teaching removes the limit of who counts as a neighbour.","cn":"一切众生：宗教教义取消了「谁算邻人」的界限。"},{"senses":"05 · 08","en":"A TRAINED HEART: the feeling is redefined as a competence and as a habit that grows with practice.","cn":"被训练的心：这份情感被重新定义为一种能力，以及随练习生长的习惯。"},{"senses":"06 · 07","en":"INWARD AND OUTWARD: the same gesture turns towards oneself in psychology and towards society in policy.","cn":"向内与向外：同一个动作，在心理学里转向自己，在政策里转向社会。"}]},"affixes":{"intro":{"en":"Compassion is a Latin noun whose prefix, root and suffix all recur in English, so the family can be read morpheme by morpheme.","cn":"compassion 是一个拉丁名词，其前缀、词根与后缀都在英语中反复出现，因此整个词族可以按语素逐个读出。"},"latinIntro":{"en":"Latin pati gives passion, passive and patient; com- adds togetherness, and the noun ending marks a state of feeling.","cn":"拉丁 pati 衍生出 passion、passive 与 patient；com- 添上「共同」，名词词尾则表示一种情感状态。"},"items":[{"word":"pati","structure":"pati (Latin deponent verb, 'to suffer, endure')","meaning":"to suffer; to endure","meaningCN":"受苦；忍受","example":"The root supplies the pain at the centre of the word.","exampleCN":"这个词根提供了词义中心的那份痛。"},{"word":"com-","structure":"com- (Latin prefix, 'with, together')","meaning":"with; together","meaningCN":"共同；一起","example":"The prefix makes the suffering shared rather than private.","exampleCN":"这个前缀让受苦成为共享的，而不是私人的。"},{"word":"compassio","structure":"com- + pati + noun ending (state)","meaning":"fellow-feeling; pity","meaningCN":"同感；怜悯","example":"The Latin noun named the state of feeling with another.","exampleCN":"这个拉丁名词指与他人共感的状态。"},{"word":"compassion","structure":"compassio through Old French","meaning":"sympathy for suffering","meaningCN":"对苦难的同情","example":"Her compassion showed in the way she sat down beside the family.","exampleCN":"她的同情体现在她坐下来陪在家属身边。"},{"word":"compassionate","structure":"compassion + -ate (having the quality)","meaning":"having or showing compassion","meaningCN":"有同情心的；表现出体恤的","example":"The ward was run by a compassionate senior nurse.","exampleCN":"这个病区由一位有同情心的资深护士管理。"},{"word":"compassionately","structure":"compassionate + -ly (in that manner)","meaning":"in a way that shows compassion","meaningCN":"以体恤的方式","example":"She answered the complaint compassionately.","exampleCN":"她体恤地回应了这起投诉。"},{"word":"compassionless","structure":"compassion + -less (without)","meaning":"showing no compassion","meaningCN":"毫无同情的","example":"A compassionless rule treats every case as identical.","exampleCN":"毫无体恤的规则把每个个案都当成一样。"},{"word":"self-compassion","structure":"self- (oneself) + compassion","meaning":"compassion directed at oneself","meaningCN":"指向自己的悲悯","example":"Self-compassion is taught alongside resilience.","exampleCN":"自我悲悯与心理韧性一起被教授。"}],"latinEntries":[{"word":"pati","structure":"pati, passus sum (verb, deponent, third conjugation)","meaning":"to suffer, endure","meaningCN":"受苦；忍受"},{"word":"compassio","structure":"compassio, compassionis (f., third declension)","meaning":"fellow-feeling, pity","meaningCN":"同感；怜悯"},{"word":"passio","structure":"passio, passionis (f., third declension)","meaning":"suffering","meaningCN":"受苦；受难"}],"derivatives":[{"word":"compassionate","pos":"adj.","zh":"有同情心的"},{"word":"compassionately","pos":"adv.","zh":"体恤地"},{"word":"compassionless","pos":"adj.","zh":"毫无同情的"},{"word":"compassionateness","pos":"n.","zh":"富于同情的性质"},{"word":"self-compassion","pos":"n.","zh":"自我悲悯"}]}},{"word":"compassionate","ipa_uk":"/kəmˈpæʃənət/","ipa_us":"/kəmˈpæʃənət/","definition_zh":"有同情心的；出于怜悯的；温和体恤的；（假期、宽免等）因家庭急难而特许的","definition_en":"feeling or showing sympathy for people who are suffering, and wishing to help them","core_image":"一位医生查房时先坐在床沿，问的不是指标而是病人昨夜睡得怎样，手里的病历一直合着","scene":"重症病房里，医生把病历夹合上放到一边，先问病人昨晚疼得能不能睡着。The compassionate doctor sat on the edge of the bed and asked about the night before any question about test results.","sceneCN":"这里 compassionate 形容「对他人疾苦敏锐并愿意体恤的」（第 1 个义项：对他人苦难敏感而温情的）；句意为这位有同情心的医生坐在床沿，先问昨夜的情况，再谈检查结果。可辨识物件：合上的病历夹、病床床沿、监护仪、夜灯。","pos":[{"tag":"adj.","zh":"有同情心的；出于怜悯的；体恤的"}],"collocations":[{"phrase":"compassionate leave","zh":"因家庭急难而准予的特别假"},{"phrase":"compassionate grounds","zh":"基于人道理由的（申请）依据"},{"phrase":"compassionate release","zh":"怜悯性释放（因重病或丧亲而提前释放）"},{"phrase":"compassionate care","zh":"有温度的照护"},{"phrase":"a compassionate response","zh":"体恤的回应"},{"phrase":"compassionate conservatism","zh":"温和保守主义（政治用语）"}],"forms":[{"label":"比较级","form":"more compassionate"},{"label":"最高级","form":"most compassionate"},{"label":"副词","form":"compassionately"},{"label":"名词（本词所指的性质）","form":"compassionateness"},{"label":"名词（同情本身）","form":"compassion"}],"derivatives":[{"word":"compassion","pos":"n.","zh":"同情；怜悯；慈悲"},{"word":"compassionately","pos":"adv.","zh":"同情地；体恤地"},{"word":"compassionateness","pos":"n.","zh":"富于同情的性质"},{"word":"uncompassionate","pos":"adj.","zh":"缺乏同情心的（少见）"}],"senses":[{"no":"01","title":"Sensitive to other people's pain","titleCN":"对他人苦难敏感的","definition":"describing a person who notices other people's suffering and feels for them","definitionCN":"形容一个人能察觉他人的痛苦并为之动情","example":"The compassionate doctor sat on the edge of the bed and asked about the night.","exampleCN":"这位有同情心的医生坐在床沿，先问昨夜的情况。","why":"The adjective simply carries the noun's feeling into description: the person is full of shared suffering.","whyCN":"形容词只是把名词里的那份情感带进描述：这个人心中满是与人共担的苦。"},{"no":"02","title":"Driven by pity","titleCN":"由怜悯驱动的","definition":"describing an action taken because someone's suffering has been noticed","definitionCN":"形容因察觉到他人受苦而采取的行动","example":"A compassionate refusal is better than a careless yes.","exampleCN":"出于怜悯的拒绝，胜过轻率的答应。","why":"When the word moves from the person to the act, it marks the motive behind the act.","whyCN":"当这个词从人移到行为上，它标出的是行为背后的动机。"},{"no":"03","title":"Gentle in manner","titleCN":"语气与做法温和体贴的","definition":"describing words or handling that avoid adding humiliation to an already painful situation","definitionCN":"形容言辞或处理方式不再给本就痛苦的处境添上羞辱","example":"She gave the news in a compassionate voice, without any blame in it.","exampleCN":"她用体恤的语气告知消息，话里没有一丝责备。","why":"Compassion is not only felt but delivered; the manner of delivery can wound or spare, so the word describes tone as well.","whyCN":"同情不只要被感受到，还要被传达出来；传达方式可以伤人也可以护人，所以这个词也形容语气。"},{"no":"04","title":"Granted for a family emergency","titleCN":"因家庭急难而准予的","definition":"describing leave or absence allowed because of a death, illness or crisis in the family","definitionCN":"形容因家人去世、重病或突发变故而被批准的假期","example":"He was given three days of compassionate leave after the funeral.","exampleCN":"葬礼之后，他获准三天急难假。","why":"Workplace rules borrowed the word for the one situation in which an employer is expected to put a person before a schedule.","whyCN":"职场规章借用了这个词，专指雇主被期待把人排在日程之前的那种情形。"},{"no":"05","title":"Allowed on humane grounds","titleCN":"基于人道理由获准的","definition":"describing a release, transfer or exception granted because of severe personal hardship","definitionCN":"形容因个人处境极为艰难而获准的释放、转院或例外","example":"Prisoners nearing death may apply for compassionate release.","exampleCN":"临近死亡的囚犯可以申请人道释放。","why":"Law keeps a narrow door for cases where strict application would be cruel, and the word names that door.","whyCN":"法律为严格适用会显得残忍的情形留了一道窄门，这个词就是那道门的名字。"},{"no":"06","title":"Care that includes feeling","titleCN":"带有温度的照护","definition":"describing treatment that attends to distress as well as to the clinical task","definitionCN":"形容在完成医疗任务之外也照顾到痛苦的照护","example":"Compassionate care begins with asking what the patient is most afraid of.","exampleCN":"有温度的照护，从问病人最害怕什么开始。","why":"Care work made the adjective a standard of quality, not merely a compliment.","whyCN":"照护行业把这个形容词变成了质量标准，而不只是一句称赞。"},{"no":"07","title":"Merciful in religious language","titleCN":"宗教语境中慈悲为怀的","definition":"in religious writing, describing a mercy that extends to all beings without condition","definitionCN":"在宗教文献中，形容无条件施及一切众生的慈悲","example":"The tradition describes a compassionate presence that turns towards every creature.","exampleCN":"这一传统描述一种转向一切生灵的慈悲临在。","why":"The oldest use of the family is religious, and the adjective still carries that wide, unconditional reach.","whyCN":"这个词族最古老的用法是宗教性的，形容词也仍带着那种无边的、无条件的覆盖。"},{"no":"08","title":"Designed with hardship in mind","titleCN":"制度设计上顾及疾苦的","definition":"describing a policy or institution built to soften the hardship it inevitably causes","definitionCN":"形容某项政策或制度在设计中设法减轻它必然造成的困苦","example":"A compassionate policy explains the decision in plain language and offers an appeal.","exampleCN":"体恤的政策用平实的语言解释决定，并提供申诉渠道。","why":"The word's final reach is structural: once compassion is expected of institutions, rules themselves are called compassionate.","whyCN":"这个词最后延伸到结构层面：一旦人们期待机构有同情心，规则本身也会被称作体恤的。"}],"etymology":{"intro":{"en":"Compassionate is the adjective formed from compassion with the Latin suffix -ate, 'having the quality of'. The noun and the adjective entered English within the same medieval period.","cn":"compassionate 是由 compassion 加拉丁后缀 -ate「具有……性质的」构成的形容词。名词与形容词都在中世纪进入英语。"},"items":[{"era":"LATIN PATI","en":"Pati 'to suffer, endure' is the root; its participle passus also gives passion and passive. The deeper origin of pati is a reconstruction.","cn":"词根 pati 意为「受苦、忍受」；其分词是 passion 与 passive 的来源。pati 的更深来源属重构。"},{"era":"LATIN COMPATI","en":"Com- 'together' plus pati formed compati, 'to suffer with', the verb behind the whole family.","cn":"com-「共同」加 pati 构成 compati「一同受苦」，这是整个词族背后的动词。"},{"era":"LATIN COMPASSIO","en":"The noun compassio named the state of shared feeling; English took the noun first and then built the adjective on it.","cn":"名词 compassio 指共感的状态；英语先借入名词，再据它造出形容词。"},{"era":"SUFFIX -ATE","en":"The ending -ate comes from Latin -atus, marking a person or thing that possesses the quality named by the stem.","cn":"词尾 -ate 来自拉丁 -atus，表示人或事物具有词干所指的性质。"},{"era":"ENGLISH 16TH CENTURY","en":"The adjective appears in English in the sixteenth century, first in religious prose and later in ordinary description of people and acts.","cn":"这个形容词在十六世纪出现于英语，最早见于宗教散文，后来才用于日常对人、对事的描述。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date): the earliest English citation of the adjective is not precisely dated, and the pre-Latin root of pati has no agreed form, so any Indo-European shape for it is a reconstruction.","cn":"来源不确定（首见年代）：这个形容词最早的英语书证没有确切年代；pati 在拉丁语之前的词根也没有公认形式，凡给出的印欧形式均属重构。"}]},"similar":{"note":{"en":"Group one holds adjectives that sit beside this one in the same Latin family or in the same sentence; group two holds adjectives with a similar warmth but a different scope.","cn":"第一组是同出这一拉丁词族、或在同一句里并列出现在的形容词；第二组是暖意相近但覆盖面不同的形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"passionate","ipa":"/ˈpæʃənət/","tag":"same root, other heat","definition":"From the same suffering participle but describing intense enthusiasm or love, not tenderness towards pain.","definitionCN":"同出「受苦」分词，却形容炽烈的热情或爱，而非对痛苦的温柔。"},{"word":"compassion","ipa":"/kəmˈpæʃn/","tag":"the noun behind it","definition":"The noun names the feeling; the adjective names the person or act that has it. The pair is a regular noun-adjective set, not two separate ideas.","definitionCN":"名词指这份情感，形容词指具有这份情感的人或行为。两者是常规的名词—形容词配对，并非两个不同概念。"},{"word":"patient","ipa":"/ˈpeɪʃnt/","tag":"same root, opposite role","definition":"From the present participle of the same verb, 'enduring'; a patient bears pain while a compassionate person responds to it.","definitionCN":"同出该动词的现在分词，意为「忍受着」；病人承受痛苦，而有同情心的人回应痛苦。"},{"word":"compatible","ipa":"/kəmˈpætəbl/","tag":"different root","definition":"Built on the Latin verb for suffering as well but in the sense of enduring together; its modern meaning is 'able to work together', which has lost the pain entirely.","definitionCN":"同样建于表示「受苦」的拉丁动词，原义为「能一同承受」；现代义为「能相容并用」，痛感已完全消失。"}]},{"heading":"NEAR MEANING","entries":[{"word":"caring","ipa":"/ˈkeərɪŋ/","tag":"looking after","definition":"Attentive to another's practical needs; it can be shown by good service alone, without any reflection on suffering.","definitionCN":"留意他人实际需要；仅靠周到的服务就能体现，不必对痛苦有所体察。"},{"word":"sympathetic","ipa":"/ˌsɪmpəˈθetɪk/","tag":"feeling with","definition":"Quick to feel for another's trouble and to express that feeling; it stops at the feeling, where compassionate goes on to help.","definitionCN":"容易为他人的困难动情并表达出来；它止于情感，而 compassionate 会继续走向援手。"},{"word":"humane","ipa":"/hjuːˈmeɪn/","tag":"not cruel","definition":"Treating people or animals in a way that avoids unnecessary suffering; it is a minimum standard, while compassionate is a warmth beyond the minimum.","definitionCN":"以不造成不必要痛苦的方式对待人或动物；它是最低标准，而 compassionate 是超出最低标准的热度。"},{"word":"tender","ipa":"/ˈtendə/","tag":"gentle handling","definition":"Gentle and careful in touch or speech; it describes the manner only, not the motive of noticing another's pain.","definitionCN":"在触碰或言语上轻柔小心；它只描述方式，不含察觉他人痛苦的动机。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Latin root, the real noun behind the adjective, the real workplace phrases and the real relatives.","cn":"正常联想：真实的拉丁词根、形容词背后真实的名词、真实的职场说法与真实的同族词。"},"normal":[{"en":"The noun compassion means suffering together; the adjective simply says that a person or act has that quality.","cn":"名词 compassion 意为「一同受苦」，形容词只是说明某人或某行为具备这种性质。"},{"en":"The ending -ate marks possession of a quality, the same ending that turns fortune into fortunate.","cn":"词尾 -ate 表示「具有某种性质」，与把「运气」变成「幸运的」用的是同一个词尾。"},{"en":"Workplace phrases pin the word down: compassionate leave, compassionate grounds, compassionate release.","cn":"职场说法把这个词固定下来：急难假、人道理由、怜悯性释放。"},{"en":"Hospitals use it as a quality standard: compassionate care is assessed alongside technical competence.","cn":"医院把它当作质量标准：有温度的照护与技术能力一起被考核。"},{"en":"The contrast to hold in mind is passionate, from the same root but about heat rather than tenderness.","cn":"要记住的对照是 passionate，同出一个词根，但说的是炽烈而非温柔。"}],"abstract":[{"en":"Picture a hand that slows down before it touches a bruise.","cn":"想象一只手在碰到淤青之前先放慢了速度。"},{"en":"Picture a door held open a few extra seconds for someone carrying too much.","cn":"想象一扇门为提着太多东西的人多开了几秒。"},{"en":"Picture a voice that lowers itself when the news is bad.","cn":"想象一个声音在坏消息面前自觉放低。"}]},"examples":[{"en":"The university granted her compassionate leave for the funeral.","cn":"学校批准她因葬礼申请的急难假。"},{"en":"A compassionate manager asks what happened before asking when the work will be done.","cn":"体恤的管理者先问发生了什么，再问工作何时完成。"},{"en":"The report recommends compassionate release for prisoners with terminal illness.","cn":"报告建议对绝症囚犯实行人道释放。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「共同 + 受苦 + 具有这种性质」——心里装着别人的痛，言行就自然温和体恤","word":"compassionate"},"root":"拉丁 compassio「同感、怜悯」+ 后缀 -ate（具有……性质的）；compassio 出自 compati「一同受苦」= com-（共同）+ pati（受苦）。深层词根不确定，印欧形式属重构。","sensesIntro":{"en":"Eight senses all describe the same quality applied to different things: first a person, then an act, then a tone, then a leave, a legal exception, a style of care, a religious mercy, and finally a policy.","cn":"八个义项描述的是同一种性质落在不同对象上：先落在人身上，再落到行为、语气、假期、法律例外、照护风格、宗教慈悲，最后落到政策上。"},"semanticMap":{"core":{"en":"CORE IMAGE: a hand that slows down before it reaches a place that hurts.","cn":"核心意象：一只手在伸向疼痛之处前先放慢了速度。"},"chain":["NOTICE THE PAIN","FEEL IT","SPEAK GENTLY","GIVE TIME OFF","SOFTEN THE RULE","BUILD IT INTO SYSTEMS"],"branches":[{"senses":"01 · 02","en":"PERSON AND MOTIVE: the one who notices, and the act that follows from noticing.","cn":"人与动机：先是察觉的人，再是由察觉引出的行为。"},{"senses":"03","en":"DELIVERY: the same feeling shows in how the words are said.","cn":"传达：同一份情感体现在话怎么说出口。"},{"senses":"04 · 05","en":"TIME AND EXEMPTION: employers give days, the law opens a narrow door.","cn":"时间与例外：雇主给出几天假，法律开出一道窄门。"},{"senses":"06 · 07","en":"CARE AND MERCY: a clinical standard on one side, an unconditional religious reach on the other.","cn":"照护与慈悲：一边是临床标准，一边是无条件的宗教覆盖。"},{"senses":"08","en":"STRUCTURE: the quality moves from people into the design of rules.","cn":"结构：这种性质从人身上移入规则的设计。"}]},"affixes":{"intro":{"en":"Compassionate is built from a Latin noun plus the suffix -ate, and both parts recur in many English words.","cn":"compassionate 由一个拉丁名词加后缀 -ate 构成，两部分都在大量英语词中反复出现。"},"latinIntro":{"en":"The stem carries shared suffering; -ate marks possession of a quality, as in fortunate and passionate.","cn":"词干带着「共同受苦」的意思；-ate 表示具有某种性质，如 fortunate 与 passionate 中的用法。"},"items":[{"word":"com-","structure":"com- (Latin prefix, 'with, together')","meaning":"with; together","meaningCN":"共同；一起","example":"The prefix makes the feeling shared.","exampleCN":"这个前缀让情感成为共享的。"},{"word":"pati","structure":"pati (Latin deponent verb, 'to suffer')","meaning":"to suffer; to endure","meaningCN":"受苦；忍受","example":"The root supplies the pain.","exampleCN":"词根提供那份痛。"},{"word":"compassio","structure":"com- + pati + noun ending","meaning":"pity; fellow-feeling","meaningCN":"怜悯；同感","example":"The noun underlies the adjective.","exampleCN":"这个名词是形容词的基础。"},{"word":"-ate","structure":"-ate (Latin -atus, 'having the quality of')","meaning":"possessing a quality","meaningCN":"具有某种性质","example":"The suffix turns a noun into a description.","exampleCN":"这个后缀把名词变成描述。"},{"word":"compassionate","structure":"compassion + -ate","meaning":"showing compassion","meaningCN":"表现出同情的","example":"The compassionate doctor sat on the edge of the bed.","exampleCN":"这位有同情心的医生坐在床沿。"},{"word":"compassionately","structure":"compassionate + -ly","meaning":"in a compassionate way","meaningCN":"以体恤的方式","example":"She refused compassionately.","exampleCN":"她体恤地拒绝了。"},{"word":"compassionateness","structure":"compassionate + -ness","meaning":"the quality of being compassionate","meaningCN":"富有同情的性质","example":"The ward was known for its compassionateness.","exampleCN":"这个病区以体恤著称。"},{"word":"uncompassionate","structure":"un- (not) + compassionate","meaning":"without compassion","meaningCN":"缺乏同情心的","example":"An uncompassionate reply closed the conversation.","exampleCN":"一句冷漠的回应终止了对话。"}],"latinEntries":[{"word":"pati","structure":"pati, passus sum (verb, deponent, third conjugation)","meaning":"to suffer, endure","meaningCN":"受苦；忍受"},{"word":"compassio","structure":"compassio, compassionis (f., third declension)","meaning":"pity, fellow-feeling","meaningCN":"怜悯；同感"},{"word":"compassivus","structure":"compassivus, -a, -um (adjective, late Latin)","meaning":"full of pity","meaningCN":"满怀怜悯的"}],"derivatives":[{"word":"compassion","pos":"n.","zh":"同情；怜悯"},{"word":"compassionately","pos":"adv.","zh":"体恤地"},{"word":"compassionateness","pos":"n.","zh":"富于同情的性质"},{"word":"uncompassionate","pos":"adj.","zh":"缺乏同情心的"}]}},{"word":"trust","ipa_uk":"/trʌst/","ipa_us":"/trʌst/","definition_zh":"信任；信赖；信托（法律上的财产代管安排）；托付；托拉斯（联合垄断组织）；信靠","definition_en":"the belief that someone or something is honest, reliable and will not let you down","core_image":"一个人把家里的钥匙交到邻居手里，自己拎着行李出门，没有回头看一眼门锁","scene":"出差前，楼上独居的老人把备用钥匙交给楼下邻居，只说了一句「花帮我浇一下」就走了。She gave him the spare key without a receipt, because trust was the only document involved.","sceneCN":"这里 trust 指「对他人可靠与善意的信赖」（第 1 个义项：相信某人不会辜负托付）；句意为她把备用钥匙交给他，没有任何收据，因为其中唯一的凭据就是信任。可辨识物件：备用钥匙、行李箱、楼道门、浇花的水壶。","pos":[{"tag":"n.","zh":"信任；信赖；信托；托拉斯"},{"tag":"v.","zh":"信任；相信；托付；指望"}],"collocations":[{"phrase":"build trust","zh":"建立信任"},{"phrase":"place trust in","zh":"把信任寄托于"},{"phrase":"a breach of trust","zh":"背信；辜负信任"},{"phrase":"trust someone with something","zh":"把某物托付给某人"},{"phrase":"in trust","zh":"以信托方式（代管）"},{"phrase":"take something on trust","zh":"未经核实便相信某事"},{"phrase":"a position of trust","zh":"受信任的职位"}],"forms":[{"label":"三单（he/she/it）","form":"trusts"},{"label":"过去式","form":"trusted"},{"label":"过去分词","form":"trusted"},{"label":"现在分词","form":"trusting"},{"label":"复数（名词）","form":"trusts"},{"label":"形容词（轻信的）","form":"trusting"},{"label":"形容词（可信赖的）","form":"trustworthy"},{"label":"名词（受托人）","form":"trustee"}],"derivatives":[{"word":"trusting","pos":"adj.","zh":"信任他人的；轻信的"},{"word":"trustworthy","pos":"adj.","zh":"值得信赖的"},{"word":"trustee","pos":"n.","zh":"受托人；理事"},{"word":"trusteeship","pos":"n.","zh":"托管；受托管理"},{"word":"distrust","pos":"n./v.","zh":"不信任；怀疑"},{"word":"mistrust","pos":"n./v.","zh":"猜疑；不信任"}],"senses":[{"no":"01","title":"Belief that someone will not let you down","titleCN":"相信某人不会辜负","definition":"the belief that a person is honest, sincere and reliable","definitionCN":"相信一个人诚实、真诚并且可靠","example":"She gave him the spare key without a receipt, because trust was the only document involved.","exampleCN":"她把备用钥匙交给他，没有收据，因为其中唯一的凭据就是信任。","why":"The word came into English from a Norse term for help and confidence, so its core is the feeling that someone will stand by you.","whyCN":"这个词从北欧语中表示「援助、信心」的说法进入英语，核心就是觉得有人会站在你这边。"},{"no":"02","title":"A legal arrangement for holding property","titleCN":"法律上的信托安排","definition":"an arrangement in which one party holds and manages property for the benefit of another","definitionCN":"一方为另一方的利益持有并管理财产的安排","example":"The house was held in trust for the two children until they turned eighteen.","exampleCN":"这栋房子以信托方式为两个孩子持有，直到他们满十八岁。","why":"English law turned the everyday confidence into a formal device: someone is trusted with property that is not their own.","whyCN":"英国法把日常的信赖变成一种正式装置：某人被信赖地持有并不属于他的财产。"},{"no":"03","title":"A monopolistic combine","titleCN":"托拉斯（联合垄断组织）","definition":"a group of companies joined under one board to control a market","definitionCN":"由同一董事会联合控制市场的一批公司","example":"The railway trust fixed freight prices across three states.","exampleCN":"这家铁路托拉斯统一了三个州的运费。","why":"American business gave the legal word a second, harder life: shareholders entrusted their stock to a single board, and the combine took the name.","whyCN":"美国商界给这个法律词添了第二个更硬的用法：股东把股票交给一个董事会托管，这个联合体就沿用了这个名字。"},{"no":"04","title":"Entrust something to someone","titleCN":"把某物托付给某人","definition":"to give someone something valuable, expecting them to use or guard it properly","definitionCN":"把贵重之物交给某人，期待他妥善使用或保管","example":"I would trust her with my savings before I trusted the bank.","exampleCN":"比起银行，我更愿意把积蓄托付给她。","why":"The verb reverses the noun: instead of feeling confidence, you hand something over on the strength of it.","whyCN":"动词把名词的关系翻了过来：不是生出信心，而是凭着这份信心把东西交出去。"},{"no":"05","title":"Accept a statement as true","titleCN":"相信某个说法为真","definition":"to believe that a report, promise or piece of information is true without demanding proof","definitionCN":"在未要求证据的情况下相信某个说法、承诺或消息为真","example":"You will have to trust me when I say the file was never opened.","exampleCN":"我说这份文件从未被打开过，你只能相信我。","why":"Confidence in a person extends easily to confidence in what that person says.","whyCN":"对人的信心很容易延伸到对他所说之话的信心。"},{"no":"06","title":"Count on something to happen","titleCN":"指望某事发生","definition":"to rely on an event or a process turning out as expected","definitionCN":"依赖某个事件或过程如预期那样发展","example":"Farmers trust the rains to come before the middle of the month.","exampleCN":"农民指望雨在月中之前到来。","why":"When the object is no longer a person, trust becomes expectation resting on experience rather than on character.","whyCN":"当对象不再是人，信任就变成基于经验而非品格的期待。"},{"no":"07","title":"A post that carries confidence","titleCN":"受信任的职位与责任","definition":"a job or role that gives access to money, secrets or power, and so requires confidence in the holder","definitionCN":"可接触到金钱、机密或权力的职位，因此需要对任职者的信心","example":"Anyone in a position of trust must declare outside interests.","exampleCN":"任何身处受信职位的人都必须申报外部利益。","why":"Institutions name the role after the feeling it demands, so the phrase describes an office rather than an emotion.","whyCN":"机构用这份情感来命名职位，于是这个说法描述的是一项职务，而不是一种情绪。"},{"no":"08","title":"Reliance on a higher power","titleCN":"对神意的信靠","definition":"in religious language, confident reliance on God or providence rather than on one's own control","definitionCN":"在宗教语境中，依靠神或天意而非自己的掌控","example":"The hymn asks the congregation to trust in providence during the harvest.","exampleCN":"这首赞美诗请会众在收获时节信靠天意。","why":"The oldest layer of the word is confidence in help that comes from outside oneself, and religious language kept it alive.","whyCN":"这个词最古老的一层，是对来自自身之外的援助的信心，宗教语言把它保留了下来。"}],"etymology":{"intro":{"en":"Trust comes from Old Norse traust 'help, protection, confidence', not from Old English. It is generally thought to be related to the Germanic adjective for faithful, the source of true, though the two reached English by different routes.","cn":"trust 来自古诺尔斯语 traust「援助、保护、信心」，并非英语本族词。一般认为它与日耳曼语中表示「忠实」的形容词相关，也就是 true 的来源，但两者进入英语的路径不同。"},"items":[{"era":"OLD NORSE TRAUST","en":"Traust meant help, protection and the confidence that help will come. Norse settlement brought the word into northern English speech.","cn":"traust 意为援助、保护，以及相信援助会到来的信心。诺尔斯人的定居把这个词带进了英格兰北部的语言。"},{"era":"PROTO-GERMANIC FORM","en":"The noun goes back to a reconstructed Germanic form for comfort and support; the form is a reconstruction, not a recorded word.","cn":"这个名词上溯到一个表示「安慰与支撑」的日耳曼语形式，该形式属重构，并非有记录的词。"},{"era":"KIN TO TRUE","en":"It is generally thought to share a root with the Germanic word for faithful, which gave English true; the shared root is widely accepted but the exact development of each branch is not settled.","cn":"一般认为它与日耳曼语中表示「忠实」的词同源，后者衍生出英语的 true；同源关系被广泛接受，但各分支的具体演变并无定论。"},{"era":"ENGLISH 13TH CENTURY","en":"English records the noun in the thirteenth century; the verb follows, first meaning to have confidence in a person.","cn":"英语在十三世纪记录了这个名词，动词随后出现，最初指对人怀有信心。"},{"era":"LEGAL AND BUSINESS SENSE","en":"From the fifteenth century English law used the word for property held for another's benefit; American business added the combine sense in the nineteenth century.","cn":"从十五世纪起，英国法用这个词指为他人利益持有的财产；美国商界在十九世纪又添上了垄断联合体的义项。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin and first date): the pre-Germanic source of traust is not established, and the earliest English citation cannot be dated to a single year, so any older form proposed for it is a reconstruction.","cn":"来源不确定（更深词源与首见年代）：traust 在日耳曼语之前的来源没有得到证明，最早的英语书证也无法确定到某一年，凡为其提出的更早形式均属重构。"}]},"similar":{"note":{"en":"Group one holds words that share the confidence root or look almost identical; group two holds nouns and verbs for related varieties of reliance.","cn":"第一组是与「信心」同根、或形貌几乎相同的词；第二组是表示各类依赖关系的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"true","ipa":"/truː/","tag":"generally thought related","definition":"From the Germanic adjective for faithful; the kinship with trust is widely accepted, but true describes fact or fidelity rather than confidence in someone.","definitionCN":"来自日耳曼语中表示「忠实」的形容词；与 trust 的同源关系被广泛接受，但 true 描述事实或忠贞，而非对人的信心。"},{"word":"truce","ipa":"/truːs/","tag":"different root","definition":"From a Germanic word for a promise or covenant of peace; it sounds like trust and even means a pledged peace, yet it comes from a different noun.","definitionCN":"来自日耳曼语中表示「和平承诺、契约」的词；它听起来像 trust，也确实指承诺停战，但出自另一个名词。"},{"word":"tryst","ipa":"/trɪst/","tag":"different root","definition":"From an Old French word for an appointed station, later a meeting place for lovers; the resemblance to trust is accidental.","definitionCN":"来自古法语中表示「约定地点」的词，后指恋人幽会之处；与 trust 的相似只是巧合。"},{"word":"entrust","ipa":"/ɪnˈtrʌst/","tag":"same root, prefix changed","definition":"The same noun with a prefix meaning 'in': to put something into someone's keeping, so the confidence is expressed as an act of handing over.","definitionCN":"同一个名词加上表示「进入」的前缀：把东西交到某人手里保管，信心因此表现为交付的动作。"}]},{"heading":"NEAR MEANING","entries":[{"word":"confidence","ipa":"/ˈkɒnfɪdəns/","tag":"firm belief","definition":"A strong belief in someone's ability or in a good outcome; it can rest on evidence, while trust usually involves risk and goodwill.","definitionCN":"对某人能力或好结果的坚定相信；它可以建立在证据上，而 trust 通常含风险与善意。"},{"word":"faith","ipa":"/feɪθ/","tag":"belief without proof","definition":"Belief that does not require evidence, often religious; trust can be rebuilt by experience, faith is not expected to need any.","definitionCN":"不要求证据的相信，常指宗教信仰；信任可凭经验重建，而信仰本就不以经验为据。"},{"word":"reliance","ipa":"/rɪˈlaɪəns/","tag":"dependence","definition":"The state of depending on someone or something for support; it stresses need rather than the moral expectation that trust carries.","definitionCN":"依靠某人或某物获得支持的状态；它强调需要，而 trust 带有道德上的期待。"},{"word":"credence","ipa":"/ˈkriːdns/","tag":"acceptance as true","definition":"Acceptance of a statement as true, often in formal writing; it names the intellectual step that trust takes emotionally.","definitionCN":"接受某说法为真，多用于正式文体；它指信任在情感层面所走的那个理智步骤。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Norse source, the real word family, the real legal phrases and the real business sense.","cn":"正常联想：真实的诺尔斯语来源、真实的同族词、真实的法律说法与真实的商业义。"},"normal":[{"en":"The Norse source meant help and confidence at once, so trust is the belief that help will come.","cn":"诺尔斯语来源同时表示「援助」与「信心」，所以信任就是相信援助会来。"},{"en":"The family runs trust, trusting, trustworthy, trustee, trusteeship, distrust and mistrust.","cn":"同族词包括 trust、trusting、trustworthy、trustee、trusteeship、distrust 与 mistrust。"},{"en":"Fixed phrases show the two halves: build trust and place trust in someone for the feeling, trust someone with something for the handover.","cn":"固定搭配显出两半：建立信任、把信任寄托于某人是情感一面；把某物托付给某人是交付一面。"},{"en":"Law turns the feeling into property: in trust, a breach of trust, a position of trust.","cn":"法律把这份情感变成财产关系：以信托方式、背信、受信职位。"},{"en":"The same noun built entrust with a prefix, and distrust with a negative one.","cn":"同一个名词加上前缀构成 entrust，加上否定前缀构成 distrust。"}],"abstract":[{"en":"Picture a bridge with no railings that people still walk across every morning.","cn":"想象一座没有栏杆的桥，人们每天早上照样走过去。"},{"en":"Picture a handover made in a corridor with no witness and no paper.","cn":"想象一次在没有见证人、也没有纸的走廊里完成的交付。"},{"en":"Picture a rope tied at one end only, held because both sides pull evenly.","cn":"想象一根只系住一端的绳子，能拉住是因为两边都均匀使力。"}]},"examples":[{"en":"Trust is slower to build than to lose.","cn":"信任建立得慢，失去得快。"},{"en":"The land was held in trust for the village.","cn":"这片土地为全村以信托方式持有。"},{"en":"I trust her judgement more than my own.","cn":"我信她的判断胜过信自己的。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「揣在手里的东西交出去」——把要紧之物交给别人而心不慌，就是信任","word":"trust"},"root":"古诺尔斯语 traust「援助、保护、信心」← 日耳曼语重构形式，意为「安慰、支撑」；一般认为与表示「忠实」的词同源，该词衍生出 true。更深来源不确定。","sensesIntro":{"en":"Eight senses start from one feeling, confidence that someone will stand by you, and follow it into law, into business, into the act of handing something over, into belief in a statement, into expectation of events, into an office, and finally into religion.","cn":"八个义项从一种情感出发——相信有人会站在你这边——再依次走进法律、商业、交付的动作、对说法的采信、对事件的预期、一项职务，最后走进宗教。"},"semanticMap":{"core":{"en":"CORE IMAGE: a key handed over with no receipt and no witness.","cn":"核心意象：一把交出时没有收据、也没有见证人的钥匙。"},"chain":["FEEL SAFE","HAND IT OVER","HOLD IT FOR ANOTHER","COMBINE THE OWNERS","BELIEVE THE WORDS","WAIT FOR THE RAIN"],"branches":[{"senses":"01 · 04","en":"FEELING AND HANDOVER: confidence becomes visible only when something is actually passed across.","cn":"情感与交付：信心只有在真有东西递过去时才看得见。"},{"senses":"02 · 07","en":"OFFICE AND PROPERTY: law names both the arrangement and the post that requires it.","cn":"职务与财产：法律既命名了这套安排，也命名了需要它的职位。"},{"senses":"03","en":"COMBINE: shareholders pool their stock under one board and the combine takes the word.","cn":"联合：股东把股票汇到一个董事会下，这个联合体就用了这个词。"},{"senses":"05 · 06","en":"WORDS AND WEATHER: once the object is not a person, trust becomes belief or expectation.","cn":"言语与天气：对象一旦不是人，信任就变成采信或预期。"},{"senses":"08","en":"HIGHER HELP: the oldest layer, confidence in help from outside oneself.","cn":"更高的援助：最古老的一层，相信援助来自自身之外。"}]},"affixes":{"intro":{"en":"Trust is a bare Norse noun with no Latin prefix or suffix, but it carries a large English family built by prefixes and endings.","cn":"trust 是一个不带拉丁前缀后缀的诺尔斯语名词，但它带出一大批靠前缀与词尾构成的英语同族词。"},"latinIntro":{"en":"The word itself has no Latin parts; the family grows by English prefixes such as en- and dis- and by endings such as -ing, -worthy and -ee.","cn":"这个词本身没有拉丁成分；词族靠英语前缀（如 en-、dis-）与词尾（如 -ing、-worthy、-ee）生长。"},"items":[{"word":"trust","structure":"traust (Old Norse noun, 'help, confidence')","meaning":"confidence in someone","meaningCN":"对人的信心","example":"The noun is the base of the whole family.","exampleCN":"这个名词是整个词族的基础。"},{"word":"trusting","structure":"trust + -ing (forming an adjective)","meaning":"ready to trust others","meaningCN":"容易信任他人的","example":"A trusting child hands over the note at once.","exampleCN":"一个信任他人的孩子立刻就把纸条交了出去。"},{"word":"trustworthy","structure":"trust + worthy (deserving of)","meaning":"deserving confidence","meaningCN":"值得信赖的","example":"Only a trustworthy witness could settle the case.","exampleCN":"只有可信的证人才能让这案子定下来。"},{"word":"trustee","structure":"trust + -ee (one who receives)","meaning":"a person who holds property for another","meaningCN":"为他人持有财产的人","example":"The trustee signed for the fund each quarter.","exampleCN":"受托人每季度为这笔基金签字。"},{"word":"entrust","structure":"en- (in) + trust","meaning":"to put into someone's keeping","meaningCN":"把某物交给某人保管","example":"They entrust the keys to the night porter.","exampleCN":"他们把钥匙交给夜间门房保管。"},{"word":"distrust","structure":"dis- (apart, not) + trust","meaning":"to withhold confidence","meaningCN":"不给予信任","example":"Voters distrust any promise made in the last week.","exampleCN":"选民不信任最后一周作出的任何承诺。"},{"word":"mistrust","structure":"mis- (wrongly) + trust","meaning":"to suspect without good grounds","meaningCN":"无充分根据地猜疑","example":"He mistrusts anyone who arrives early.","exampleCN":"他对任何早到的人都心存猜疑。"},{"word":"trusteeship","structure":"trustee + -ship (state or office)","meaning":"the office of holding property for others","meaningCN":"受托管理的职位或状态","example":"The trusteeship passed to the eldest daughter.","exampleCN":"受托管理之责传给了长女。"}],"latinEntries":[],"derivatives":[{"word":"trusting","pos":"adj.","zh":"轻信的；信任他人的"},{"word":"trustworthy","pos":"adj.","zh":"值得信赖的"},{"word":"trustee","pos":"n.","zh":"受托人"},{"word":"trusteeship","pos":"n.","zh":"受托管理"},{"word":"distrust","pos":"n./v.","zh":"不信任"}]}},{"word":"trustworthy","ipa_uk":"/ˈtrʌstwɜːði/","ipa_us":"/ˈtrʌstwɜːrði/","definition_zh":"值得信赖的；可靠的；忠实可靠的；（数据、证据、来源）可信的","definition_en":"able to be relied on as honest, accurate and unlikely to fail or betray a confidence","core_image":"一把用了十年的旧锁，备用钥匙一直放在邻居家的抽屉里，主人从未想过要换锁","scene":"老城区的楼道里，一把备用钥匙在邻居家抽屉里放了十年，主人一次也没换过锁。A trustworthy neighbour kept the spare key for a decade and was never once asked to explain anything.","sceneCN":"这里 trustworthy 形容「可以把事情托付给他而无需设防的」（第 1 个义项：为人可靠、不辜负托付）；句意为一位值得信赖的邻居替他保管备用钥匙十年，从未被要求作任何解释。可辨识物件：旧锁、抽屉、备用钥匙、楼道信箱。","pos":[{"tag":"adj.","zh":"值得信赖的；可靠的；可信的"}],"collocations":[{"phrase":"a trustworthy source","zh":"可信的消息来源"},{"phrase":"trustworthy data","zh":"可靠的数据"},{"phrase":"a trustworthy person","zh":"值得信赖的人"},{"phrase":"trustworthy evidence","zh":"可信的证据"},{"phrase":"a trustworthy brand","zh":"值得信赖的品牌"},{"phrase":"appear trustworthy","zh":"显得可信"}],"forms":[{"label":"比较级","form":"more trustworthy"},{"label":"最高级","form":"most trustworthy"},{"label":"名词（可信赖的性质）","form":"trustworthiness"},{"label":"副词（少见）","form":"trustworthily"},{"label":"反义形容词","form":"untrustworthy"}],"derivatives":[{"word":"trustworthiness","pos":"n.","zh":"可信赖性；可靠性"},{"word":"trustworthily","pos":"adv.","zh":"可靠地（少见）"},{"word":"untrustworthy","pos":"adj.","zh":"不可信赖的"},{"word":"trust","pos":"n./v.","zh":"信任；托付"}],"senses":[{"no":"01","title":"Safe to rely on as a person","titleCN":"为人可靠，可托付","definition":"describing a person whose honesty and steadiness make it safe to give them responsibility","definitionCN":"形容一个人诚实稳重，可以把责任交给他而不必设防","example":"A trustworthy neighbour kept the spare key for a decade.","exampleCN":"一位值得信赖的邻居替他保管备用钥匙十年。","why":"The word joins confidence with the idea of being worth something, so a trustworthy person is one whose word has value.","whyCN":"这个词把「信心」与「值得」连在一起，因此可靠之人的话是有分量的。"},{"no":"02","title":"Accurate and honest information","titleCN":"消息与数据可信","definition":"describing reports, figures or accounts that can be used without fear of error or concealment","definitionCN":"形容报告、数字或陈述可以放心采用，不必担心出错或隐瞒","example":"The agency publishes trustworthy figures on every quarter.","exampleCN":"该机构每季度公布可信的数字。","why":"Once confidence moves from a person to what a person produces, the word judges accuracy rather than character.","whyCN":"当信心从人移到人做出的东西上，这个词评判的就不是品格而是准确度。"},{"no":"03","title":"Fit to be used as evidence","titleCN":"可作依据的证据","definition":"describing research, records or testimony solid enough for decisions to rest on","definitionCN":"形容研究、记录或证词足够扎实，可以据此作决定","example":"Only trustworthy evidence entered the final report.","exampleCN":"只有可信的证据进入了最终报告。","why":"Courts and journals need a word that separates what may be relied on from what merely sounds convincing.","whyCN":"法院与期刊需要一个词，把可以依靠的东西与只是听起来有理的东西分开。"},{"no":"04","title":"A dependable institution or brand","titleCN":"稳健可信的机构与品牌","definition":"describing an organisation that keeps its promises over time and handles money or data responsibly","definitionCN":"形容长期守信、负责管理金钱或数据的组织","example":"Customers stay with a trustworthy bank even when rivals offer better rates.","exampleCN":"即使对手利率更优，客户仍愿意留在可信的银行。","why":"Institutions are judged the way people are: by whether their promises hold when it would be easier to break them.","whyCN":"评判机构与评判人一样：看它在更容易毁诺的时候是否仍然守信。"},{"no":"05","title":"A system that does not fail","titleCN":"稳定不出错的系统","definition":"in engineering, describing a component or process whose behaviour can be predicted and counted on","definitionCN":"在工程中指元件或流程的表现可预测、可依赖","example":"Engineers prefer trustworthy components over clever ones.","exampleCN":"工程师偏向可靠的部件，而不是聪明的部件。","why":"Engineering borrowed the moral word because a machine that breaks a promise is simply one that fails.","whyCN":"工程学借用了这个道德词，因为一台违背承诺的机器，就是一台出故障的机器。"},{"no":"06","title":"Loyal and unlikely to betray","titleCN":"忠实不背叛的","definition":"describing someone who will not sell a confidence or change sides for advantage","definitionCN":"形容一个人不会出卖秘密，也不会为利益改换立场","example":"He proved trustworthy under pressure and named no names.","exampleCN":"他在压力之下证明了忠实，没有供出任何人的名字。","why":"The oldest layer of confidence is about help in hard times, and betrayal is what the word measures.","whyCN":"信心最古老的一层关乎难关中的援助，而这个词衡量的正是会不会背叛。"},{"no":"07","title":"A judgement one can act on","titleCN":"可以据以行动的判断","definition":"describing an estimate, method or result reliable enough to base a decision on","definitionCN":"形容估计、方法或结果足够可靠，可以据此作决定","example":"Their cost estimate proved trustworthy to within two percent.","exampleCN":"他们的成本估算误差在百分之二以内，证明是可靠的。","why":"The word extends to anything whose output can be used without a second check.","whyCN":"这个词也延伸到任何不必复核就能采用的产出。"},{"no":"08","title":"Faithful to a duty","titleCN":"忠于职守的受托者","definition":"describing someone who handles another's interests with care and without seeking private gain","definitionCN":"形容一个人谨慎处理他人利益，不谋私利","example":"A trustworthy trustee keeps records that anyone can inspect.","exampleCN":"值得信赖的受托人会保留任何人都能查阅的记录。","why":"In law the word describes the core duty of a person who holds power for someone else.","whyCN":"在法律中，这个词描述替他人掌权者最核心的义务。"}],"etymology":{"intro":{"en":"Trustworthy is an English compound: trust, borrowed from Old Norse, joined to worthy, which descends from the Old English word for value. Both halves are native or Norse, with no Latin stem.","cn":"trustworthy 是一个英语复合词：从古诺尔斯语借入的 trust，加上源自古英语「价值」一词的 worthy。两部分都属本族或诺尔斯语来源，不含拉丁词干。"},"items":[{"era":"OLD NORSE TRAUST","en":"Traust meant help, protection and confidence; Norse settlers carried it into English, where it kept the sense of reliance on someone.","cn":"traust 意为援助、保护与信心；诺尔斯定居者把它带进英语，保留了「依靠某人」的意思。"},{"era":"OLD ENGLISH WEORTH","en":"The Old English noun for value or price is the base of worthy; the same idea survives in the modern noun worth.","cn":"古英语中表示「价值、价钱」的名词是 worthy 的基础；同一意思保留在现代名词 worth 中。"},{"era":"SUFFIX -Y","en":"The ending -y here means 'having the quality of', so worthy describes something that has value and therefore deserves regard.","cn":"这里的词尾表示「具有……性质」，因此 worthy 描述某物有价值、因而值得看重。"},{"era":"COMPOUND 17TH TO 18TH CENTURY","en":"The two parts were joined in the seventeenth or eighteenth century to name a person or thing whose confidence has been earned; the earliest printed uses are not precisely dated.","cn":"两部分在十七至十八世纪之间合成，用来指信心已经赢得的人或物；最早的印刷用例没有确切年代。"},{"era":"MODERN TECHNICAL USE","en":"In the twentieth century the word spread from people to data, sources and systems, especially in journalism, statistics and engineering.","cn":"到二十世纪，这个词从人扩展到数据、来源与系统，尤其在新闻、统计与工程领域。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date): no exact year can be assigned to the first recorded use of the compound, and the pre-Germanic origin of the Norse noun is not established, so any older form proposed for it is a reconstruction.","cn":"来源不确定（首见年代）：无法为这个词组最早的记录指定确切年份；那个诺尔斯语名词在日耳曼语之前的来源也未得到证明，凡为其提出的更早形式均属重构。"}]},"similar":{"note":{"en":"Group one holds words that share a half of this compound or sound nearly the same; group two holds adjectives of reliability with a different basis for confidence.","cn":"第一组是与此词共享一半构成、或读音极近的词；第二组是同样表示可靠、但信心依据不同的形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"trusting","ipa":"/ˈtrʌstɪŋ/","tag":"same base, opposite direction","definition":"Built on the same noun but describing the one who gives confidence easily; it can suggest naivety, where trustworthy describes the one who deserves it.","definitionCN":"同出一个名词，却形容轻易给出信心的人；它可能带天真之意，而 trustworthy 形容值得这份信心的人。"},{"word":"trustful","ipa":"/ˈtrʌstfl/","tag":"same base, rarer twin","definition":"A rarer synonym of trusting, describing a person disposed to trust; it says nothing about whether others can trust them back.","definitionCN":"trusting 的较罕见同义词，形容人有信任他人的倾向；它不涉及别人能否反过来信任他。"},{"word":"untrustworthy","ipa":"/ˌʌnˈtrʌstwɜːði/","tag":"negated form","definition":"The direct negation: it charges a person or source with being unsafe to rely on, without naming the kind of failure.","definitionCN":"直接否定形式：指某人或某来源不可依靠，但不说明是哪一类失误。"},{"word":"worth","ipa":"/wɜːθ/","tag":"one half of the compound","definition":"The noun of value that underlies the second half; worth measures what something is valued at, not whether it can be relied on.","definitionCN":"构成后半部分、表示价值的名词；它衡量某物值多少，而不判断它是否可靠。"}]},{"heading":"NEAR MEANING","entries":[{"word":"reliable","ipa":"/rɪˈlaɪəbl/","tag":"consistent performance","definition":"Can be counted on to do the same thing well every time; it stresses consistency rather than honesty.","definitionCN":"可以指望每次都把同一件事做好；它强调一贯稳定，而不强调诚实。"},{"word":"dependable","ipa":"/dɪˈpendəbl/","tag":"will not let you down","definition":"Describes someone or something that can be depended on in a practical pinch; warmer and less formal than trustworthy.","definitionCN":"形容在紧要关头靠得住的人或物；比 trustworthy 更亲切、更口语。"},{"word":"credible","ipa":"/ˈkredəbl/","tag":"believable","definition":"Deserving to be believed, often of a witness, account or source; credibility can be staged, while trustworthiness must be earned over time.","definitionCN":"值得相信，多用于证人、陈述或来源；可信度可以营造，而值得信赖须靠时间赢得。"},{"word":"honest","ipa":"/ˈɒnɪst/","tag":"truthful","definition":"Disposed to tell the truth and not to cheat; honesty is one ingredient of being trustworthy, not the whole of it.","definitionCN":"倾向于说真话、不欺骗；诚实是值得信赖的一个成分，而非全部。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the two real halves of the compound, the real phrases it appears in, and the real relatives built on the same base.","cn":"正常联想：这个词真实的两个构成部分、它常出现的真实搭配，以及同基词根衍生出的真实同族词。"},"normal":[{"en":"The compound is confidence plus worth: a person whose word has value is a person you can rely on.","cn":"这个词组是「信心」加「价值」：话有分量的人，就是可以依靠的人。"},{"en":"The family runs trust, trusting, trustful, trustworthy, trustworthiness, untrustworthy and trustee.","cn":"同族词包括 trust、trusting、trustful、trustworthy、trustworthiness、untrustworthy 与 trustee。"},{"en":"Fixed phrases show where it is applied: a trustworthy source, trustworthy data, trustworthy evidence, a trustworthy brand.","cn":"固定搭配显明它的用场：可信的来源、可靠的数据、可信的证据、值得信赖的品牌。"},{"en":"Its direct opposite is untrustworthy, one of the few negations in this family that is fully standard.","cn":"它的直接反义是不可信赖，这是这个词族里少数完全通用的否定形式之一。"},{"en":"Engineering uses it for parts that behave as promised, which shows the word measures promise-keeping in any form.","cn":"工程领域用它形容表现如所承诺的部件，可见这个词衡量的始终是「守信」。"}],"abstract":[{"en":"Picture a lock that has never been changed because nobody ever needed to.","cn":"想象一把从未换过的锁，因为从来没有人觉得需要换。"},{"en":"Picture a signature that is accepted without a stamp or a witness.","cn":"想象一个不需要盖章、也不需要见证人的签名。"},{"en":"Picture a scale that has weighed the same sack for years and never once argued.","cn":"想象一杆秤，多年来称的都是同一袋东西，从没出过一次偏差。"}]},"examples":[{"en":"Journalists need trustworthy sources before they publish a name.","cn":"记者在公布姓名之前需要可信的消息来源。"},{"en":"The committee found him trustworthy and renewed his access to the archive.","cn":"委员会认定他值得信赖，重新给了他查阅档案的权限。"},{"en":"Trustworthy measurements matter more than elegant theories.","cn":"可靠的测量比漂亮的理论更重要。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「信任 + 值得」——值得别人把信心交给你，就是可靠","word":"trustworthy"},"root":"古诺尔斯语 traust「援助、信心」+ 古英语 weorþ「价值」+ 词尾 -y（具有……性质的）。两部分均为本族或诺尔斯语来源，不含拉丁词干；诺尔斯语名词的更深来源不确定。","sensesIntro":{"en":"Eight senses take one judgement, that confidence has been earned, and apply it to a person, to information, to evidence, to an institution, to a machine, to loyalty under pressure, to a judgement, and to a duty.","cn":"八个义项拿着同一个判断——这份信心是被挣来的——依次用于人、消息、证据、机构、机器、压力下的忠诚、判断，最后用于职责。"},"semanticMap":{"core":{"en":"CORE IMAGE: a key left in a neighbour's drawer for years, with no lock ever changed.","cn":"核心意象：一把在邻居抽屉里放了多年的钥匙，锁始终没有换过。"},"chain":["KEEP THE KEY","TELL THE TRUTH","CHECK THE NUMBER","KEEP THE PROMISE","DO NOT FAIL","HOLD THE OFFICE"],"branches":[{"senses":"01 · 06","en":"PERSON AND PRESSURE: a reliable person is one who stays reliable when betrayal would pay.","cn":"人与压力：可靠的人，是在背叛有利可图时仍然可靠的人。"},{"senses":"02 · 03","en":"WORDS AND EVIDENCE: from what a person says to what a record proves.","cn":"言语与证据：从一个人说的话，到一份记录能证明的事。"},{"senses":"04","en":"INSTITUTION: a promise kept across years, when breaking it would have been easier.","cn":"机构：在更容易毁诺的时候，仍然把承诺守了多年。"},{"senses":"05 · 07","en":"MACHINE AND METHOD: engineering and statistics ask only whether the output can be counted on.","cn":"机器与方法：工程与统计只问产出能否被依赖。"},{"senses":"08","en":"FIDUCIARY DUTY: the legal core, where power is held for someone else.","cn":"受托义务：法律上的核心，权力是为别人而掌。"}]},"affixes":{"intro":{"en":"Trustworthy is a native compound, so its parts are English words rather than Latin morphemes; the endings -y and -ness still behave like suffixes.","cn":"trustworthy 是本族复合词，其组成部分是英语词而非拉丁语素；词尾 -y 与 -ness 仍起后缀作用。"},"latinIntro":{"en":"There is no Latin element in this word. Its second half goes back to an Old English noun for value, and the family grows by ordinary English endings.","cn":"这个词不含拉丁成分。它的后半部分上溯到古英语中表示「价值」的名词，词族靠普通英语词尾生长。"},"items":[{"word":"trust","structure":"traust (Old Norse noun, 'help, confidence')","meaning":"confidence in someone","meaningCN":"对人的信心","example":"The first half names the confidence being earned.","exampleCN":"前半部分指出被赢得的这份信心。"},{"word":"worth","structure":"weorþ (Old English noun, 'value, price')","meaning":"value","meaningCN":"价值","example":"The second half supplies the idea of value.","exampleCN":"后半部分提供「价值」这一概念。"},{"word":"-y","structure":"-y (adjective ending, 'having the quality of')","meaning":"having the quality of","meaningCN":"具有某种性质","example":"The ending turns value into a description.","exampleCN":"这个词尾把「价值」变成一种描述。"},{"word":"worthy","structure":"worth + -y","meaning":"deserving regard; having value","meaningCN":"值得看重；有价值","example":"A worthy claim is one that deserves to be heard.","exampleCN":"值得的主张，就是该被听取的主张。"},{"word":"trustworthy","structure":"trust + worthy","meaning":"deserving confidence","meaningCN":"值得信赖","example":"A trustworthy neighbour kept the spare key for a decade.","exampleCN":"一位值得信赖的邻居替他保管备用钥匙十年。"},{"word":"trustworthiness","structure":"trustworthy + -ness (state)","meaning":"the state of deserving confidence","meaningCN":"值得信赖的状态","example":"Auditors test the trustworthiness of the records.","exampleCN":"审计人员检验这些记录的可信程度。"},{"word":"untrustworthy","structure":"un- (not) + trustworthy","meaning":"not deserving confidence","meaningCN":"不值得信赖的","example":"An untrustworthy witness ruins a strong case.","exampleCN":"一个不可信的证人会毁掉一桩有力的案子。"},{"word":"trustworthily","structure":"trustworthy + -ly (in that manner)","meaning":"in a reliable manner","meaningCN":"以可靠的方式","example":"The fund was trustworthily administered for thirty years.","exampleCN":"这笔基金被可靠地管理了三十年。"}],"latinEntries":[],"derivatives":[{"word":"trustworthiness","pos":"n.","zh":"可信赖性"},{"word":"untrustworthy","pos":"adj.","zh":"不可信赖的"},{"word":"trustworthily","pos":"adv.","zh":"可靠地"},{"word":"trust","pos":"n./v.","zh":"信任"},{"word":"worthy","pos":"adj.","zh":"值得的；有价值的"}]}},{"word":"distrust","ipa_uk":"/dɪsˈtrʌst/","ipa_us":"/dɪsˈtrʌst/","definition_zh":"不信任；怀疑；猜疑；（对制度、技术的）不信任","definition_en":"a feeling that someone or something cannot be relied on, and a readiness to suspect them","core_image":"一个人接过合同，先翻到小字那一页，手指停在签名栏上方迟迟没有落笔","scene":"签约室里，他把合同翻到小字那一页，逐行读完才肯拿起笔。His distrust of the offer showed in the way he read every footnote before touching the pen.","sceneCN":"这里 distrust 指「对某人或某事不放心、随时准备怀疑」（第 1 个义项：对他人可靠性的不信任）；句意为他对这份报价的不信任，体现在他碰笔之前把小字逐条读完。可辨识物件：合同、小字条款、签字栏、未拧开的笔。","pos":[{"tag":"n.","zh":"不信任；怀疑；猜疑（不可数）"},{"tag":"v.","zh":"不信任；怀疑"}],"collocations":[{"phrase":"distrust of authority","zh":"对权威的不信任"},{"phrase":"mutual distrust","zh":"彼此猜疑"},{"phrase":"growing distrust","zh":"日益加深的不信任"},{"phrase":"distrust the motives","zh":"怀疑动机"},{"phrase":"a climate of distrust","zh":"猜疑的氛围"},{"phrase":"distrust in institutions","zh":"对机构的不信任"}],"forms":[{"label":"三单（he/she/it）","form":"distrusts"},{"label":"过去式","form":"distrusted"},{"label":"过去分词","form":"distrusted"},{"label":"现在分词","form":"distrusting"},{"label":"复数（名词，少见）","form":"distrusts"},{"label":"形容词","form":"distrustful"},{"label":"副词","form":"distrustfully"}],"derivatives":[{"word":"distrustful","pos":"adj.","zh":"不信任的；猜疑的"},{"word":"distrustfully","pos":"adv.","zh":"猜疑地"},{"word":"distrustfulness","pos":"n.","zh":"多疑的性格"},{"word":"trust","pos":"n./v.","zh":"信任"},{"word":"mistrust","pos":"n./v.","zh":"猜疑（更强调无根据）"}],"senses":[{"no":"01","title":"A refusal to rely on someone","titleCN":"不肯把事交托给某人","definition":"the feeling that a person cannot be relied on, so their promises are not counted as secure","definitionCN":"觉得某个人不可依靠，因此不把他的承诺当作稳妥","example":"His distrust of the offer showed in the way he read every footnote.","exampleCN":"他对这份报价的不信任，体现在他把每条小字都读了。","why":"The prefix reverses confidence, so distrust is trust with the assurance removed rather than plain hatred.","whyCN":"前缀把信心翻了过来，因此不信任是被抽掉了把握的信任，而不是单纯的厌恶。"},{"no":"02","title":"Doubt about a statement","titleCN":"怀疑某个说法不真","definition":"the belief that a report, promise or explanation is probably untrue or incomplete","definitionCN":"认为某项报告、承诺或解释很可能不真或不完整","example":"She distrusted the official explanation from the first sentence.","exampleCN":"官方解释从第一句起她就不信。","why":"Confidence in words is the easiest part of trust to withdraw, since a statement can be checked.","whyCN":"对言语的信心是信任中最容易撤回的部分，因为一句话可以被核对。"},{"no":"03","title":"Suspicion about motives","titleCN":"对动机的戒备","definition":"a readiness to read hidden self-interest into another person's kindness or offer","definitionCN":"倾向于把他人的善意或提议解读为藏着私利","example":"Years of broken deals left him distrusting every friendly call.","exampleCN":"多年被毁的生意让他对每一通友善的电话都心存戒备。","why":"Once a person is distrusted, even generosity is read as a move in a game.","whyCN":"一旦不信任一个人，连慷慨也会被读成棋局里的一步。"},{"no":"04","title":"Widespread doubt about institutions","titleCN":"对机构与制度的普遍不信任","definition":"a public mood in which courts, banks, media or government are assumed to serve themselves","definitionCN":"一种社会情绪：人们假定法院、银行、媒体或政府都在为自己打算","example":"Distrust of the courts kept the settlement from being accepted.","exampleCN":"对法院的不信任使这项和解无法被接受。","why":"When the feeling is shared by a whole society, it stops being personal and becomes a political fact.","whyCN":"当整个社会共有这种感受，它就不再是私人的，而成了政治事实。"},{"no":"05","title":"A habit of suspecting everyone","titleCN":"对谁都多疑的性格","definition":"a settled disposition to expect betrayal, even where no evidence points to it","definitionCN":"一种稳定的性格倾向：即使没有证据，也预期会被背叛","example":"His distrust was a habit rather than a judgement.","exampleCN":"他的多疑是一种习惯，而不是一次判断。","why":"Repeated experience turns the reaction into a temperament, and the word can name that temperament.","whyCN":"反复的经历会把反应变成性情，这个词也能指这种性情。"},{"no":"06","title":"Doubt directed at oneself","titleCN":"对自己的不信任","definition":"a lack of confidence in one's own judgement, memory or ability","definitionCN":"对自己的判断、记忆或能力缺乏信心","example":"Self-distrust made her rewrite the same paragraph four times.","exampleCN":"自我怀疑让她把同一段话改了四遍。","why":"The prefix does not care who the object is, so the feeling can be turned inward.","whyCN":"前缀并不在意对象是谁，因此这份感受也可以转向自己。"},{"no":"07","title":"Refusing something out of suspicion","titleCN":"因怀疑而不接受","definition":"to reject an offer, a tool or a method because its reliability is doubted","definitionCN":"因怀疑其可靠性而拒绝某项提议、工具或方法","example":"Many readers distrust anything written by an anonymous account.","exampleCN":"许多读者对匿名账号写的东西一概不信。","why":"As a verb the word can act on objects as well as people, and then it means to withhold acceptance.","whyCN":"作动词时，这个词既能用于人也能用于物，这时意思是不予接受。"},{"no":"08","title":"Suspicion between groups","titleCN":"群体之间的互不信任","definition":"a two-way suspicion in which each side expects the other to act in bad faith","definitionCN":"双向的猜疑：每一方都预期对方会恶意行事","example":"Mutual distrust between the two villages outlasted the dispute itself.","exampleCN":"两个村子之间的互不信任，比争端本身持续得更久。","why":"The final sense makes the feeling symmetrical: nobody is merely the object of it any more.","whyCN":"最后一个义项让这份感受对称起来：没有人只是它的对象。"}],"etymology":{"intro":{"en":"Distrust is trust with a negative prefix. The prefix came into English through Old French from Latin dis- 'apart', and the noun itself is the Norse loan traust.","cn":"distrust 是加上否定前缀的 trust。前缀经古法语来自拉丁 dis-「分开」，名词本身则是借自诺尔斯语的 traust。"},"items":[{"era":"LATIN DIS-","en":"Latin dis- meant 'apart, in different directions', and in compounds it commonly reversed or undid the base word.","cn":"拉丁 dis- 意为「分开、朝不同方向」，在复合词中常把基词的意思反转或取消。"},{"era":"OLD FRENCH DES-","en":"Old French softened the prefix to des-, and English borrowed both the prefix and many of its words in the medieval period.","cn":"古法语把这个前缀弱化为 des-，英语在中世纪既借入了前缀，也借入了大量带此前缀的词。"},{"era":"OLD NORSE TRAUST","en":"The base noun meant help and confidence; joined to the negative prefix, it named the withdrawal of that confidence.","cn":"基词意为援助与信心；接上否定前缀后，它指把这份信心收回。"},{"era":"ENGLISH 16TH CENTURY","en":"Both the noun and the verb are recorded in the sixteenth century, at first in religious and political argument about whom one may believe.","cn":"名词与动词都在十六世纪见于记录，最早出现在关于「可以相信谁」的宗教与政治论辩中。"},{"era":"MODERN PUBLIC MOOD","en":"From the nineteenth century the word was increasingly used of institutions and classes rather than individuals, and that public sense is now the commonest.","cn":"从十九世纪起，这个词越来越多用于机构与阶层而非个人，这一公共义如今最常见。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date): the earliest citation of the prefixed form cannot be fixed to a year, and the pre-Germanic origin of the Norse noun remains unsettled, so any older form given for it is a reconstruction.","cn":"来源不确定（首见年代）：加前缀的形式最早的书证无法确定到某一年；那个诺尔斯语名词在日耳曼语之前的来源亦无定论，凡为其给出的更早形式均属重构。"}]},"similar":{"note":{"en":"Group one holds words built with the same negative prefix or the same base; group two holds near synonyms that differ in how much evidence the suspicion rests on.","cn":"第一组是用同一个否定前缀、或同一个基词构成的词；第二组是近义说法，区别在于怀疑是否有凭据。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"mistrust","ipa":"/ˌmɪsˈtrʌst/","tag":"different prefix","definition":"Built with a prefix meaning 'wrongly': suspicion that may be mistaken or unfair, where distrust is the more neutral withdrawal of confidence.","definitionCN":"用意为「错误地」的前缀构成：指可能弄错或不公平的猜疑，而 distrust 更中性，只是收回信心。"},{"word":"distrustful","ipa":"/dɪsˈtrʌstfl/","tag":"adjective form","definition":"The adjective built on this noun; it describes a person who habitually withholds confidence.","definitionCN":"由这个名词构成的形容词；它形容习惯性不轻易给出信心的人。"},{"word":"distrust","ipa":"/dɪsˈtrʌst/","tag":"noun and verb","definition":"The same spelling serves both word classes, so the noun names the feeling and the verb names the act of withholding belief.","definitionCN":"同一拼写兼作名词与动词，因此名词指这份感受，动词指不予相信的动作。"},{"word":"disturb","ipa":"/dɪˈstɜːb/","tag":"different root","definition":"Shares the negative prefix but comes from a Latin verb for unsettling; its subject is calm or order, not confidence.","definitionCN":"共享否定前缀，却来自表示「搅乱」的拉丁动词；它扰动的是平静或秩序，不是信心。"}]},{"heading":"NEAR MEANING","entries":[{"word":"suspicion","ipa":"/səˈspɪʃn/","tag":"a specific hunch","definition":"A belief that something is wrong or hidden, usually about one particular matter; distrust is the broader state behind such hunches.","definitionCN":"认为某事有错或有隐情的具体直觉，通常针对某一件特定的事；distrust 是这些直觉背后的整体状态。"},{"word":"doubt","ipa":"/daʊt/","tag":"uncertainty","definition":"Uncertainty about whether something is true; doubt can be neutral or academic, while distrust carries a judgement about character or intention.","definitionCN":"对某事是否属实的不确定；怀疑可以是中性的或学术性的，而 distrust 含对品格或意图的判断。"},{"word":"scepticism","ipa":"/ˈskeptɪsɪzəm/","tag":"method, not feeling","definition":"A disciplined habit of demanding evidence before accepting a claim; it is a method, whereas distrust is an emotional stance.","definitionCN":"在采信某个说法前坚持要求证据的严谨习惯；它是一种方法，而 distrust 是一种情感立场。"},{"word":"paranoia","ipa":"/ˌpærəˈnɔɪə/","tag":"clinical extreme","definition":"Suspicion with no basis in reality, often a medical condition; distrust may be entirely justified by experience.","definitionCN":"毫无现实依据的猜疑，常属医学状况；distrust 则可能完全由经历证明有理。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real negative prefix, the real base noun, the real public phrases and the real adjective built on it.","cn":"正常联想：真实的否定前缀、真实的基词名词、真实的公共说法，以及由它构成的真实形容词。"},"normal":[{"en":"The prefix means apart, so distrust is confidence pushed away rather than never offered.","cn":"前缀意为「分开」，因此不信任是被推开的信心，而不是从未给出的信心。"},{"en":"The family runs distrust, distrustful, distrustfully, distrustfulness, and the unprefixed trust.","cn":"同族词包括 distrust、distrustful、distrustfully、distrustfulness，以及去掉前缀的 trust。"},{"en":"Public phrases show the modern weight: distrust of authority, distrust in institutions, a climate of distrust.","cn":"公共说法显出现代分量：对权威的不信任、对机构的不信任、猜疑的氛围。"},{"en":"The prefixed verb and noun share one spelling, so the feeling and the act look the same on paper.","cn":"加前缀的动词与名词拼写相同，因此这份感受与这个动作在纸上长得一样。"},{"en":"Its near neighbour mistrust uses a prefix of wrongness, which is why it sounds more accusatory.","cn":"近邻 mistrust 用的是表示「错误」的前缀，所以听起来更像指责。"}],"abstract":[{"en":"Picture a hand reaching for a doorknob and then stopping halfway.","cn":"想象一只手伸向门把，伸到一半又停住。"},{"en":"Picture a receipt kept in a drawer for years in case it is ever needed as proof.","cn":"想象一张收据在抽屉里存了多年，只为哪天需要拿它作证。"},{"en":"Picture two people walking side by side but each counting the other's steps.","cn":"想象两个人并肩走，却各自数着对方的步子。"}]},"examples":[{"en":"Distrust of the official figures grew after the second revision.","cn":"第二次修订之后，人们对官方数字的不信任加深了。"},{"en":"She distrusted any offer that arrived with a deadline attached.","cn":"凡附有期限的提议，她都不信。"},{"en":"The two communities lived in mutual distrust for a generation.","cn":"两个社区互不信任地过了一代人。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「不 + 信任」——把已经想交出去的心又收回来，就是猜疑","word":"distrust"},"root":"拉丁前缀 dis-「分开」经古法语 des- 进入英语 + 古诺尔斯语 traust「援助、信心」。否定前缀把信心推开，构成 distrust；诺尔斯语名词的更深来源不确定。","sensesIntro":{"en":"Eight senses take one movement, the withdrawal of confidence, and follow it through a person, a statement, a motive, an institution, a temperament, the self, an object, and finally a whole relationship between groups.","cn":"八个义项围绕同一个动作——把信心收回——依次走过人、说法、动机、机构、性情、自己、物件，最后走到群体之间的关系。"},"semanticMap":{"core":{"en":"CORE IMAGE: a pen that stops above the signature line.","cn":"核心意象：一支停在签名栏上方不落下的笔。"},"chain":["HOLD BACK","CHECK THE WORDS","READ THE MOTIVE","DOUBT THE OFFICE","DOUBT EVERYONE","DOUBT ONESELF"],"branches":[{"senses":"01 · 02","en":"PERSON AND STATEMENT: first the one who might fail you, then the words they use.","cn":"人与说法：先可能是辜负你的人，再是他说出的话。"},{"senses":"03","en":"MOTIVE: kindness itself is reread as strategy.","cn":"动机：连善意也被重新读成策略。"},{"senses":"04 · 08","en":"COLLECTIVE DOUBT: institutions, and then whole groups, stop believing each other.","cn":"集体的怀疑：先是机构，随后是整个群体互不相信。"},{"senses":"05","en":"TEMPERAMENT: repeated suspicion hardens into character.","cn":"性情：反复的猜疑硬化成性格。"},{"senses":"06 · 07","en":"INWARD AND REFUSED: the same feeling can face oneself or turn something down.","cn":"向内与拒绝：同一份感受可以朝向自己，也可以用来拒绝某物。"}]},"affixes":{"intro":{"en":"Distrust is a prefixed noun and verb: a Latin-derived negative prefix laid over a Norse noun.","cn":"distrust 是带前缀的名词兼动词：一个源自拉丁的否定前缀加在一个诺尔斯语名词上。"},"latinIntro":{"en":"The prefix began in Latin as a word for apart and reached English through French; the base noun came from Norse, so the word mixes two borrowing routes.","cn":"这个前缀源自拉丁语中表示「分开」的词，经法语进入英语；基词名词来自诺尔斯语，因此这个词混用了两条借词路径。"},"items":[{"word":"dis-","structure":"dis- (Latin prefix, 'apart, asunder')","meaning":"apart; not","meaningCN":"分开；否定","example":"The prefix reverses the confidence of the base.","exampleCN":"这个前缀把基词的信心反转。"},{"word":"trust","structure":"traust (Old Norse noun, 'help, confidence')","meaning":"confidence in someone","meaningCN":"对人的信心","example":"The base names what is withdrawn.","exampleCN":"基词指出被收回的是什么。"},{"word":"distrust","structure":"dis- + trust","meaning":"withheld confidence","meaningCN":"收回的信心；不信任","example":"His distrust of the offer showed in the way he read every footnote.","exampleCN":"他对这份报价的不信任，体现在他把每条小字都读了。"},{"word":"distrustful","structure":"distrust + -ful (full of)","meaning":"full of suspicion","meaningCN":"满怀猜疑的","example":"A distrustful reader checks every claim twice.","exampleCN":"多疑的读者会把每个说法核对两遍。"},{"word":"distrustfully","structure":"distrustful + -ly","meaning":"in a suspicious manner","meaningCN":"猜疑地","example":"He glanced distrustfully at the sealed envelope.","exampleCN":"他猜疑地瞥了一眼那封封好的信。"},{"word":"distrustfulness","structure":"distrustful + -ness (state)","meaning":"the state of being suspicious","meaningCN":"多疑的状态","example":"Her distrustfulness was mistaken for rudeness.","exampleCN":"她的多疑被误认为无礼。"},{"word":"mistrust","structure":"mis- (wrongly) + trust","meaning":"suspicion that may be unjust","meaningCN":"可能不公的猜疑","example":"He mistrusts praise more than criticism.","exampleCN":"他对赞扬比对批评更不放心。"},{"word":"trusting","structure":"trust + -ing (adjective)","meaning":"ready to give confidence","meaningCN":"容易给出信心的","example":"A trusting buyer asks fewer questions.","exampleCN":"信任他人的买家问得更少。"}],"latinEntries":[{"word":"dis-","structure":"dis- (Latin prefix, 'apart, in different directions')","meaning":"apart; asunder","meaningCN":"分开；散开"},{"word":"distrustus","structure":"distrustus, -a, -um (adjective, medieval Latin)","meaning":"distrusted, suspected","meaningCN":"不被信任的；被怀疑的"},{"word":"diffidere","structure":"diffidere, diffisus sum (verb, third conjugation)","meaning":"to distrust, despair of","meaningCN":"不信任；对……失去信心"}],"derivatives":[{"word":"distrustful","pos":"adj.","zh":"多疑的"},{"word":"distrustfully","pos":"adv.","zh":"猜疑地"},{"word":"distrustfulness","pos":"n.","zh":"多疑"},{"word":"mistrust","pos":"n./v.","zh":"猜疑"},{"word":"trust","pos":"n./v.","zh":"信任"}]}},{"word":"loyalty","ipa_uk":"/ˈlɔɪəlti/","ipa_us":"/ˈlɔɪəlti/","definition_zh":"忠诚；忠心；效忠；（对品牌、球队等的）忠实；专一","definition_en":"the quality of being faithful to a person, group or cause, and of not abandoning it in hard times","core_image":"一枚旧徽章别在内侧衣襟上，从不示人，也从不取下","scene":"球队降级那年，看台上仍有一批人穿着旧球衣来，季票一张也没退。Their loyalty survived the season in which the club lost every home match.","sceneCN":"这里 loyalty 指「对某个群体的忠心，不因处境变坏而撤离」（第 1 个义项：对人与群体的忠诚）；句意为他们的忠诚熬过了球队主场全败的那个赛季。可辨识物件：旧球衣、季票、空荡的看台、记分牌。","pos":[{"tag":"n.","zh":"忠诚；忠心；效忠；忠实；专一"}],"collocations":[{"phrase":"brand loyalty","zh":"品牌忠诚度"},{"phrase":"customer loyalty","zh":"客户忠诚度"},{"phrase":"loyalty to the crown","zh":"对王室的效忠"},{"phrase":"a loyalty programme","zh":"会员忠诚计划"},{"phrase":"swear loyalty","zh":"宣誓效忠"},{"phrase":"divided loyalties","zh":"两头为难的效忠关系"},{"phrase":"out of loyalty","zh":"出于忠诚"}],"forms":[{"label":"复数","form":"loyalties"},{"label":"形容词","form":"loyal"},{"label":"副词","form":"loyally"},{"label":"名词（忠诚者，古旧）","form":"loyalist"}],"derivatives":[{"word":"loyal","pos":"adj.","zh":"忠诚的；忠实的"},{"word":"loyally","pos":"adv.","zh":"忠诚地"},{"word":"loyalist","pos":"n.","zh":"效忠者；忠实拥护者"},{"word":"disloyal","pos":"adj.","zh":"不忠的"},{"word":"disloyalty","pos":"n.","zh":"不忠"}],"senses":[{"no":"01","title":"Faithfulness to a person or group","titleCN":"对人与群体的忠心","definition":"steady faithfulness to the people one belongs with, kept even when leaving would be easier","definitionCN":"对自己所属之人保持稳定的忠心，即使离开更容易也不离开","example":"Their loyalty survived the season in which the club lost every home match.","exampleCN":"他们的忠诚熬过了球队主场全败的那个赛季。","why":"The word began in feudal law as the faithfulness a sworn man owed his lord, so its heart is staying when one could go.","whyCN":"这个词最初是封建法律中宣誓者对领主的忠贞，核心就是「本可以走却留下」。"},{"no":"02","title":"Allegiance to a state or crown","titleCN":"对国家或君主的效忠","definition":"the formal allegiance a citizen or subject owes to a state, flag or monarch","definitionCN":"公民或臣民对国家、旗帜或君主承担的正式效忠","example":"New citizens swear loyalty to the constitution, not to a person.","exampleCN":"新公民宣誓效忠的是宪法，而不是某个人。","why":"Feudal faithfulness was taken over by the modern state and attached to an institution rather than a lord.","whyCN":"封建的忠贞被现代国家接手，系在制度上而不是系在领主身上。"},{"no":"03","title":"Sticking with an organisation or team","titleCN":"对组织、球队的忠实追随","definition":"the attachment of a member or supporter who keeps supporting a body through poor results","definitionCN":"成员或支持者的归属感：即使成绩不佳也继续支持某个团体","example":"Season-ticket holders showed a loyalty that no relegation could shake.","exampleCN":"季票持有者表现出一种降级也摇不动的忠诚。","why":"Modern membership moved the old sworn bond into clubs, schools and companies, where nobody has sworn anything.","whyCN":"现代的成员身份把古老的宣誓纽带移进俱乐部、学校与公司，而在那里并没有人宣过誓。"},{"no":"04","title":"Fidelity to an idea","titleCN":"对理念的坚守","definition":"attachment to a principle or cause that survives changes in fashion and cost","definitionCN":"对某项原则或事业的坚持，不因风气与代价的改变而放弃","example":"Her loyalty to the reform outlasted three leaders who had promised it.","exampleCN":"她对改革的支持比三位承诺改革的人任期都长。","why":"Once the object of faithfulness is no longer a person, loyalty becomes consistency of principle.","whyCN":"当忠贞的对象不再是某个人，忠诚就变成原则上的前后一致。"},{"no":"05","title":"Repeated buying from one brand","titleCN":"对某一品牌的消费忠实","definition":"in business, a customer's habit of returning to the same brand or shop instead of switching","definitionCN":"商业中指顾客习惯性回到同一品牌或店铺而不转投他家","example":"The airline measured loyalty by how often passengers chose it over a cheaper rival.","exampleCN":"这家航空公司用乘客在多选更便宜的对手时仍选它的频率来衡量忠诚度。","why":"Marketing borrowed a moral word for a statistical habit, which is why loyalty programmes can be bought.","whyCN":"营销借用一个道德词来描述统计习惯，所以「忠诚计划」是可以买的。"},{"no":"06","title":"Faithfulness in a close relationship","titleCN":"亲密关系中的专一","definition":"the promise of exclusivity and steadiness between partners","definitionCN":"伴侣之间专一而稳定的承诺","example":"He treated loyalty as a daily practice rather than a single promise.","exampleCN":"他把专一当成每天要做的事，而不是一次性的承诺。","why":"The oldest personal sense narrows here to the intimacy of a couple, where faithfulness is tested privately.","whyCN":"最古老的对人之义在这里收窄到伴侣的亲密关系，忠贞在私下受到检验。"},{"no":"07","title":"Doing one's duty faithfully","titleCN":"忠于职守","definition":"the reliable performance of a role, especially when nobody is watching or rewarding it","definitionCN":"可靠地履行职责，尤其在无人监督或奖赏时","example":"The night guard's loyalty was never noticed until the flood came.","exampleCN":"直到洪水来临，人们才注意到夜班守卫的忠于职守。","why":"From faithfulness to persons, the word extends to faithfulness to a task and to those the task protects.","whyCN":"从对人的忠贞，这个词延伸到对任务的忠实，以及对任务所护之人的忠实。"},{"no":"08","title":"Competing allegiances","titleCN":"多重而相互冲突的效忠","definition":"in the plural, the several claims on a person's faithfulness that may pull in different directions","definitionCN":"复数形式指一个人所背负的多种效忠要求，它们可能指向不同方向","example":"Divided loyalties made the minister's decision impossible to defend.","exampleCN":"两头为难的效忠让这位部长的决定无法自辩。","why":"A person can belong to a family, a firm and a country at once, and the plural names the conflict rather than the virtue.","whyCN":"一个人同时属于家庭、公司与国家，复数形式指的是这种冲突，而不是美德本身。"}],"etymology":{"intro":{"en":"Loyalty comes from Old French loialté, from Latin legalis 'of the law', from lex 'law'. English legal is the same Latin word borrowed later and directly, so loyal and legal are doublets.","cn":"loyalty 来自古法语 loialté，源头是拉丁 legalis「法律的」，再上溯为 lex「法律」。英语的 legal 是同一个拉丁词后来直接借入的形式，因此 loyal 与 legal 是同一词根的两次借入。"},"items":[{"era":"LATIN LEX","en":"Lex meant law or statute. Its origin is uncertain; a link with the verb legere 'to gather, read' is generally mentioned but not proven, so it is a hypothesis rather than a settled derivation.","cn":"lex 意为法律、法令。其来源不确定；常有人把它与动词 legere「收集、读」联系起来，但这只是假说，并非已证实的派生。"},{"era":"LATIN LEGALIS","en":"Legalis meant 'belonging to the law'. In medieval usage it also described someone who keeps the law, and so someone who is faithful to an oath.","cn":"legalis 意为「属于法律的」。在中世纪用法中，它也形容守法的人，进而形容忠于誓言的人。"},{"era":"OLD FRENCH LOIAL","en":"Old French turned legalis into loial, where the sense had already shifted from lawful to faithful, especially faithful to a lord.","cn":"古法语把 legalis 变成 loial，词义已从「合法的」转为「忠实的」，尤其指对领主忠实。"},{"era":"OLD FRENCH LOIALTE","en":"The abstract noun loialte named that faithfulness, and English took it in the fourteenth century for the bond between a sworn man and his lord.","cn":"抽象名词 loialte 指这种忠贞，英语在十四世纪借入，用于宣誓者与领主之间的纽带。"},{"era":"DOUBLET WITH LEGAL","en":"English later borrowed legalis again, directly and unchanged in meaning, producing legal. Loyal and legal therefore look different and mean different things while sharing one Latin source.","cn":"英语后来又直接借入 legalis，词义未变，产生了 legal。因此 loyal 与 legal 形貌与含义都不同，却共享同一个拉丁来源。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin): the root of lex has no agreed explanation; the connection with the verb for gathering or reading is a common suggestion, not an established fact, and any Indo-European form offered for it is a reconstruction.","cn":"来源不确定（更深词源）：lex 的词根没有公认解释；与表示「收集、读」的动词之间的关联只是一种常见推测，并非既定事实，凡为其给出的印欧形式均属重构。"}]},"similar":{"note":{"en":"Group one holds words that share the Latin law root but arrived by a different route; group two holds near synonyms that differ in what the faithfulness is owed to.","cn":"第一组是同出拉丁「法律」词根、但走了另一条路径的词；第二组是近义说法，区别在于忠诚所指向的对象。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"loyal","ipa":"/ˈlɔɪəl/","tag":"adjective form","definition":"The adjective built on the same stem; loyalty is the quality, loyal the description of a person or act that has it.","definitionCN":"由同一词干构成的形容词；loyalty 是这种品质，loyal 则形容具备它的人或行为。"},{"word":"legal","ipa":"/ˈliːɡl/","tag":"same root, direct borrowing","definition":"The same Latin source borrowed later and directly: it concerns what the law permits, not what faithfulness requires.","definitionCN":"同一拉丁来源后来被直接借入：它关乎法律允许什么，而不关乎忠贞要求什么。"},{"word":"legislation","ipa":"/ˌleɡɪsˈleɪʃn/","tag":"same root, other branch","definition":"Built on the same law noun with a verb for carrying: it names the making of statutes and has nothing to do with devotion.","definitionCN":"同一法律名词加上表示「携带」的动词构成：它指制定法令，与忠贞无关。"},{"word":"loyalist","ipa":"/ˈlɔɪəlɪst/","tag":"person suffix","definition":"The person noun built on loyal; it usually names someone who stays with a government or cause when others leave.","definitionCN":"由 loyal 构成的人物名词；通常指在别人离开时仍留在某政府或事业一边的人。"}]},{"heading":"NEAR MEANING","entries":[{"word":"faithfulness","ipa":"/ˈfeɪθflnəs/","tag":"kept promises","definition":"The keeping of promises and vows, often in marriage or religion; loyalty adds the idea of belonging to a group.","definitionCN":"信守承诺与誓言，多用于婚姻或宗教；loyalty 更强调归属于某个群体。"},{"word":"allegiance","ipa":"/əˈliːdʒəns/","tag":"formal and political","definition":"Formal obligation of loyalty to a state or sovereign; it is public and sworn, while loyalty can be private and unspoken.","definitionCN":"对国家或君主的正式效忠义务；它是公开的、宣誓的，而 loyalty 可以是私下且不言明的。"},{"word":"fidelity","ipa":"/fɪˈdeləti/","tag":"exactness and devotion","definition":"Faithfulness in a relationship, or exactness in copying; it stresses precision as much as devotion.","definitionCN":"关系中的忠贞，或复制时的精确；它既强调 devotion，也强调准确。"},{"word":"devotion","ipa":"/dɪˈvəʊʃn/","tag":"warm attachment","definition":"Deep affection and dedication to a person or activity; it is warmer than loyalty and less concerned with obligation.","definitionCN":"对某人或某活动的深厚感情与投入；它比 loyalty 更温暖，也更不涉及义务。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real law root, the real doublet legal, the real commercial phrases and the real adjective family.","cn":"正常联想：真实的「法律」词根、真实的双借词 legal、真实的商业说法，以及真实的形容词词族。"},"normal":[{"en":"The root is the Latin word for law, so loyalty began as the faithfulness a sworn man owed under law.","cn":"词根是拉丁语中表示「法律」的词，所以忠诚最初是宣誓者在法律之下所欠的忠贞。"},{"en":"Legal is the same source borrowed a second time, which is why one word is about faithfulness and the other about permission.","cn":"legal 是同一来源的第二次借入，因此一个词关乎忠贞，另一个关乎许可。"},{"en":"Business phrases mark the modern sense: brand loyalty, customer loyalty, a loyalty programme.","cn":"商业说法标出现代义：品牌忠诚度、客户忠诚度、会员忠诚计划。"},{"en":"The family runs loyalty, loyal, loyally, loyalist, disloyal and disloyalty.","cn":"同族词包括 loyalty、loyal、loyally、loyalist、disloyal 与 disloyalty。"},{"en":"The plural loyalties names conflicting claims, as in divided loyalties, rather than more of the same virtue.","cn":"复数形式指的是相互冲突的多重效忠，也就是「两头为难」，而不是同一种美德变得更多。"}],"abstract":[{"en":"Picture a badge worn inside the lapel where nobody can see it.","cn":"想象一枚徽章别在内侧衣襟上，谁也看不见。"},{"en":"Picture a seat kept empty for years in case someone returns.","cn":"想象一个空了许多年的座位，只为等某个人回来。"},{"en":"Picture a road walked in the same direction after every other walker has turned back.","cn":"想象在其他人都折返之后，仍朝同一方向走下去的一条路。"}]},"examples":[{"en":"The company rewards loyalty with early access rather than cash.","cn":"公司用优先购买权而不是现金来回报忠诚。"},{"en":"His loyalty to the department outlasted four directors.","cn":"他对这个部门的忠诚比四任主管都长久。"},{"en":"Divided loyalties kept her from speaking at the hearing.","cn":"两头为难的效忠让她在听证会上无法开口。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「法律之下的守约」——受人以托、守约不弃，就是忠诚","word":"loyalty"},"root":"古法语 loialté ← 拉丁 legalis「法律的」← lex「法律」。英语 legal 是同一拉丁词后来的直接借入，故 loyal 与 legal 同源而异貌。lex 的更深词源不确定，与「收集、读」的关联仅为假说。","sensesIntro":{"en":"Eight senses begin with a sworn faithfulness to a person, then widen to a state, a team, an idea, a brand, a partner, a duty, and finally to the conflicts that arise when several of these claims meet in one life.","cn":"八个义项从对某个人的宣誓忠贞开始，再依次扩展到国家、团队、理念、品牌、伴侣、职责，最后落在多重效忠同时压到一个人身上时的冲突。"},"semanticMap":{"core":{"en":"CORE IMAGE: a badge worn on the inside of a lapel, never shown and never removed.","cn":"核心意象：一枚别在内侧衣襟上的徽章，从不示人，也从不取下。"},"chain":["SWEAR TO A PERSON","SERVE THE CROWN","STAY WITH THE TEAM","KEEP THE CAUSE","BUY THE SAME BRAND","SPLIT BETWEEN TWO"],"branches":[{"senses":"01 · 06","en":"PERSONAL BOND: from a sworn man to a partner, faithfulness is tested in private.","cn":"个人纽带：从宣誓者到伴侣，忠贞都在私下受到检验。"},{"senses":"02","en":"THE STATE: the old bond is transferred to a constitution or a crown.","cn":"国家：古老的纽带被移交给宪法或王冠。"},{"senses":"03 · 05","en":"BELONGING AND BUYING: clubs and brands inherit the language of allegiance.","cn":"归属与购买：俱乐部与品牌继承了效忠的语言。"},{"senses":"04 · 07","en":"CAUSE AND DUTY: when no person is involved, loyalty becomes consistency and reliability.","cn":"事业与职责：当对象不是人，忠诚就变成前后一致与可靠。"},{"senses":"08","en":"THE SPLIT: the plural turns the virtue into a dilemma.","cn":"分裂：复数形式把这份美德变成两难。"}]},"affixes":{"intro":{"en":"Loyalty is a French abstract noun on a Latin law root, with a suffix that turns an adjective into a quality.","cn":"loyalty 是一个建在拉丁「法律」词根上的法语抽象名词，其词尾把形容词变成一种品质。"},"latinIntro":{"en":"Latin lex supplies the stem, legalis supplies the adjective, and the French ending marks the abstract quality; the same stem also built legal and legislation.","cn":"拉丁 lex 提供词干，legalis 提供形容词，法语的词尾标出抽象品质；同一词干还造出了 legal 与 legislation。"},"items":[{"word":"lex","structure":"lex, legis (Latin noun, 'law')","meaning":"law; statute","meaningCN":"法律；法令","example":"The root names the law under which an oath is sworn.","exampleCN":"这个词根指誓言所依凭的法律。"},{"word":"legalis","structure":"lex + -alis (relating to)","meaning":"of the law","meaningCN":"属于法律的","example":"The adjective shifted from lawful to faithful.","exampleCN":"这个形容词从「合法的」转为「忠实的」。"},{"word":"loial","structure":"legalis through Old French","meaning":"faithful to a lord","meaningCN":"对领主忠实的","example":"A loial man kept his oath to his lord.","exampleCN":"忠实的人会守住对领主的誓言。"},{"word":"loyalty","structure":"loial + -té (abstract quality)","meaning":"faithfulness","meaningCN":"忠贞；忠诚","example":"Their loyalty survived the season in which the club lost every home match.","exampleCN":"他们的忠诚熬过了球队主场全败的那个赛季。"},{"word":"loyal","structure":"loial, borrowed into English","meaning":"faithful","meaningCN":"忠诚的","example":"A loyal reader renews before the deadline.","exampleCN":"忠实的读者会在截止前续订。"},{"word":"loyally","structure":"loyal + -ly","meaning":"in a faithful manner","meaningCN":"忠诚地","example":"He served loyally for thirty years.","exampleCN":"他忠诚地服务了三十年。"},{"word":"loyalist","structure":"loyal + -ist (person)","meaning":"one who stays faithful","meaningCN":"效忠者","example":"The loyalists refused to leave the building.","exampleCN":"效忠者拒绝离开那栋楼。"},{"word":"disloyalty","structure":"dis- (not) + loyalty","meaning":"betrayal of faithfulness","meaningCN":"不忠；背信","example":"The court treated silence as disloyalty.","exampleCN":"法庭把沉默当作不忠。"}],"latinEntries":[{"word":"lex","structure":"lex, legis (f., third declension)","meaning":"law, statute","meaningCN":"法律；法令"},{"word":"legalis","structure":"legalis, -e (adjective, third declension)","meaning":"of the law, lawful","meaningCN":"法律的；合法的"},{"word":"legalitas","structure":"legalitas, legalitatis (f., third declension)","meaning":"lawfulness","meaningCN":"合法性"}],"derivatives":[{"word":"loyal","pos":"adj.","zh":"忠诚的"},{"word":"loyally","pos":"adv.","zh":"忠诚地"},{"word":"loyalist","pos":"n.","zh":"效忠者"},{"word":"disloyal","pos":"adj.","zh":"不忠的"},{"word":"disloyalty","pos":"n.","zh":"不忠"}]}},{"word":"loyal","ipa_uk":"/ˈlɔɪəl/","ipa_us":"/ˈlɔɪəl/","definition_zh":"忠诚的；忠实的（对人、团体或事业）；忠贞的（对伴侣与誓言）；效忠的（对君主或国家）；长期支持的（顾客与读者）；矢志不渝的（对原则）；制度内批评而仍忠于整体的","definition_en":"faithful to a person, group, cause or duty, and unwilling to abandon it even when doing so would be easier or more profitable","core_image":"老街照相馆的冲洗师，在师父去世、店面几经转手之后，仍每天早晨开门，把褪色的招牌擦一遍，再把师父的合影摆回柜台原位","scene":"老街上的照相馆换过三任房东，冲洗师仍每天早晨拉起卷帘门，把褪色的招牌擦干净，再把师父留下的合影摆回柜台原位。He stayed loyal to the little studio long after its founder had died and the building had changed hands.","sceneCN":"这里 loyal 形容「对某个人或某个地方长期不离不弃的忠诚」（第 1 个义项：对某人在困境中仍不背弃）；句意为创办人去世、楼宇数次转手之后，他仍守着这间小照相馆。可辨识物件：褪色的招牌、师父的合影相框、清晨拉起的卷帘门、挂在腰间的旧钥匙。","pos":[{"tag":"adj.","zh":"忠诚的；忠实的；忠贞的；效忠的；矢志不渝的"}],"collocations":[{"phrase":"a loyal friend","zh":"忠实的朋友"},{"phrase":"a loyal customer","zh":"忠实的顾客"},{"phrase":"loyal to sb/sth","zh":"忠于某人或某事"},{"phrase":"remain loyal","zh":"保持忠诚"},{"phrase":"a loyal supporter","zh":"忠实的支持者"},{"phrase":"a loyal following","zh":"忠实的追随者群体"}],"forms":[{"label":"比较级","form":"more loyal"},{"label":"最高级","form":"most loyal"},{"label":"副词","form":"loyally"},{"label":"名词（忠诚这一性质）","form":"loyalty"},{"label":"反义形容词","form":"disloyal"},{"label":"反义名词","form":"disloyalty"}],"derivatives":[{"word":"loyalty","pos":"n.","zh":"忠诚；忠心；效忠"},{"word":"loyally","pos":"adv.","zh":"忠诚地；忠实地"},{"word":"loyalist","pos":"n.","zh":"效忠者；忠实拥护者"},{"word":"disloyal","pos":"adj.","zh":"不忠的；背弃的"},{"word":"disloyalty","pos":"n.","zh":"不忠；背弃"}],"senses":[{"no":"01","title":"Faithful to a person","titleCN":"对一个人不离不弃","definition":"staying attached to a friend, partner or leader and refusing to abandon them when loyalty becomes costly","definitionCN":"对朋友、伴侣或领导者保持依恋，即使忠诚要付出代价也不离弃","example":"She stayed loyal to her first coach after a richer club offered her a place.","exampleCN":"更有钱的俱乐部给了她一个位置之后，她仍忠于最初的教练。","why":"The Latin source described someone who keeps the law, and keeping faith with a person grew out of that legal idea of standing by an obligation.","whyCN":"拉丁来源形容守法的人，而「对人守信」正是从「守着一项义务」这一法律观念里长出来的。"},{"no":"02","title":"Faithful to a group or cause","titleCN":"对团体或事业忠实","definition":"giving steady support to a team, party, school or cause over many years","definitionCN":"多年间稳定地支持某个球队、党派、学校或事业","example":"He has been loyal to the same football club since he was six.","exampleCN":"他从六岁起就忠于同一家足球俱乐部。","why":"The sworn bond to a lord widened into any body one chooses to belong to.","whyCN":"对领主宣誓的纽带，扩展成了对任何自己选择归属的团体的纽带。"},{"no":"03","title":"True to a promise or duty","titleCN":"忠于誓言与职责","definition":"keeping the terms of an oath, a vow or a post even when no one is watching","definitionCN":"即使无人监督，也遵守誓言、婚誓或职位的条款","example":"The nurse was loyal to her oath and never repeated what she had seen in the ward.","exampleCN":"那名护士忠于自己的誓词，从未把病房里看到的事说出去。","why":"Medieval usage applied the lawful man to anyone who kept his word, which is the bridge from law to faithfulness.","whyCN":"中世纪用法把这个「守法之人」用在任何守信者身上，这正是从法律通往忠贞的桥。"},{"no":"04","title":"A customer who keeps coming back","titleCN":"长期回头的顾客","definition":"in business, describing a customer or reader who returns to the same shop, paper or brand year after year","definitionCN":"商业用语，形容年复一年回到同一家店、同一份报纸或同一个品牌的顾客或读者","example":"The bookshop has a small but loyal readership that has outlasted three owners.","exampleCN":"这家书店的读者不多却忠实，熬过了三任店主。","why":"Modern trade borrowed the moral word to measure attachment that survives better offers.","whyCN":"现代商业借用了这个道德词，用来衡量那种在更优条件面前仍然留存的依恋。"},{"no":"05","title":"Holding to a principle","titleCN":"守住一条原则","definition":"remaining faithful to a belief, habit or memory that one has inherited or chosen","definitionCN":"对自己继承或选定的信念、习惯或记忆保持忠实","example":"He remained loyal to the principles his father had taught him, even when they cost him a promotion.","exampleCN":"他始终忠于父亲教给他的原则，即便这些原则让他失去了升职机会。","why":"Once faithfulness needs no second person, it attaches to ideas, and the word describes consistency of belief.","whyCN":"当忠贞不再需要另一个对象时，它就附着在观念上，这个词便描述信念的一贯。"},{"no":"06","title":"Faithful in love","titleCN":"爱情中的忠贞","definition":"remaining true to a partner and refusing the attentions of others","definitionCN":"对伴侣保持忠实，拒绝他人的示好","example":"They promised to remain loyal to each other through two years of living in different countries.","exampleCN":"他们答应在分居两国的两年里彼此忠贞。","why":"The oldest personal sense comes from courtly writing, where faithfulness was proved by distance and temptation.","whyCN":"最古老的个人义项来自宫廷文学，那里的忠贞要靠距离与诱惑来证明。"},{"no":"07","title":"Sworn to a sovereign or state","titleCN":"对君主或国家的效忠","definition":"in political and military usage, staying on the side of a crown, government or flag during conflict","definitionCN":"政治与军事用语，指冲突中仍站在王室、政府或旗帜一边","example":"The regiment stayed loyal to the crown even after half the capital had changed sides.","exampleCN":"即便半个首都都已倒向另一方，这个团仍效忠王室。","why":"This is the feudal core of the word: a sworn man bound to a lord by oath rather than by opinion.","whyCN":"这是这个词的封建内核：宣誓者靠誓言而非主张绑定于领主。"},{"no":"08","title":"Loyal opposition","titleCN":"制度内忠诚的反对","definition":"in parliamentary language, describing criticism offered from inside the system by those who do not wish to overthrow it","definitionCN":"议会用语，指体制内部提出批评、却不希望推翻体制的人所做的批评","example":"A loyal opposition attacks the minister's policy without attacking the state itself.","exampleCN":"忠诚的反对派抨击部长的政策，却不攻击国家本身。","why":"The word can even cover sharp criticism, which shows that loyalty is owed to the whole rather than to a person's wishes.","whyCN":"这个词甚至能涵盖尖锐批评，可见忠诚所向是整体，而不是某人的意愿。"}],"etymology":{"intro":{"en":"Loyal comes from Old French loial, from Latin legalis 'of the law', from lex 'law'. English legal is the same Latin word borrowed directly and much later, so loyal and legal are doublets: one source, two arrivals.","cn":"loyal 来自古法语 loial，源头是拉丁 legalis「法律的」，再上溯为 lex「法律」。同一个拉丁词后来又被直接借入英语，成为表示「法律的」的那个形容词，因此本词与它属同一来源的两次借入。"},"items":[{"era":"LATIN LEX","en":"Lex meant law or statute. Source uncertain: no agreed origin exists, and a link with legere 'to gather, read' is a hypothesis rather than a settled derivation.","cn":"lex 意为法律、法令。来源不确定：没有公认的起源；一般认为它与 legere「收集、读」有关，但这只是假说，不是已证实的派生。"},{"era":"LATIN LEGALIS","en":"Legalis meant 'belonging to the law'. Medieval usage also applied it to a person who keeps the law, and from there to one who keeps faith.","cn":"legalis 意为「属于法律的」。中世纪用法也用它形容守法的人，进而形容守信的人。"},{"era":"OLD FRENCH LOIAL","en":"Old French changed legalis into loial, and the sense moved from lawful to faithful, above all faithful to a lord.","cn":"古法语把 legalis 变成 loial，词义也从「合法的」转为「忠实的」，尤其指对领主忠实。"},{"era":"LATE MIDDLE ENGLISH","en":"English borrowed the adjective around the fifteenth century for the bond between a sworn follower and his lord; the exact first date is not settled, and the modern senses spread outward from that bond.","cn":"英语大约在十五世纪借入这个形容词，用于宣誓的追随者与领主之间的纽带；确切首见年代并无定论，现代各个义项都是从那一条纽带向外扩展的。"},{"era":"DOUBLET LEGAL","en":"Legalis was borrowed a second time, directly and with its meaning intact, giving English legal; the two words now share a source but not a sense.","cn":"legalis 后来又被直接借入一次，词义保持原样，成为表示「法律的」的那个英语形容词；这两个词如今共享来源，却不共享词义。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin and first date): the root of lex has no agreed explanation, the legere connection remains a suggestion, and any Indo-European form proposed for it is a reconstruction.","cn":"来源不确定（更深词源与首见年代）：lex 的词根没有公认解释；与 legere 的关联仍只是推测；凡为其提出的印欧形式均属重构形式。"}]},"similar":{"note":{"en":"Group one holds words from the same Latin law noun, including the doublet that arrived by the direct route, plus one look-alike from an unrelated royal stem; group two holds adjectives of attachment that differ in basis and warmth.","cn":"第一组是同出拉丁「法律」名词的词，包括沿直接借入路线到达的那个双重借入词，以及一个词形相近却出自无关「王室」词干的词；第二组是表示依恋的形容词，区别在于依据与温度。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"legal","ipa":"/ˈliːɡl/","tag":"same root, direct borrowing","definition":"The same Latin word borrowed directly and later: it asks what the law permits, while the adjective under study asks whom one will not abandon.","definitionCN":"同一个拉丁词后来被直接借入：它问法律允许什么，而本词问的是不肯背弃谁。"},{"word":"loyalty","ipa":"/ˈlɔɪəlti/","tag":"same stem, noun","definition":"The noun built on the same stem: it names the quality that a faithful person or act shows.","definitionCN":"由同一词干构成的名词：它命名的是忠实的人或行为所显现的品质。"},{"word":"royal","ipa":"/ˈrɔɪəl/","tag":"look-alike, different root","definition":"It looks close and even rhymes, but it comes from Latin regalis, from rex 'king', so it shares no root with this word.","definitionCN":"它词形相近甚至押韵，但来自拉丁 regalis，源于 rex「国王」，与本词不同源。"},{"word":"legislation","ipa":"/ˌledʒɪsˈleɪʃn/","tag":"same law root, other branch","definition":"Built on the same law noun with a verb for carrying: it names the making of statutes and has nothing to do with devotion.","definitionCN":"同一法律名词加上表示「携带」的动词构成：它指制定法令，与忠贞无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"faithful","ipa":"/ˈfeɪθfl/","tag":"kept promises","definition":"Keeps promises and vows, especially in marriage or religion; this word adds the idea of belonging to a group or cause.","definitionCN":"信守承诺与誓言，多用于婚姻或宗教；本词则多出「归属于某个团体或事业」之意。"},{"word":"devoted","ipa":"/dɪˈvəʊtɪd/","tag":"warm dedication","definition":"Gives deep affection and time to a person or activity; it is warmer than the word under study and less about obligation.","definitionCN":"对某人或某活动付出深厚感情与时间；它比本词更温暖，也更少涉及义务。"},{"word":"steadfast","ipa":"/ˈstedfɑːst/","tag":"unmoved under pressure","definition":"Holds a position without wavering, often through danger or criticism; it stresses firmness rather than attachment.","definitionCN":"不动摇地守住立场，常在危险或批评之中；它强调坚定，而非依恋。"},{"word":"constant","ipa":"/ˈkɒnstənt/","tag":"unchanging over time","definition":"Stays the same across years and moods; it describes steadiness of behaviour, not the bond that produces it.","definitionCN":"多年间、在各种情绪下都保持不变；它描述行为的一贯，而不描述产生这种一贯的纽带。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real law root and its doublet, the real family built on the stem, the real fixed phrases, and the political phrase that stretches the sense furthest.","cn":"正常联想：真实的「法律」词根及其双重借入词、由同一词干长出的真实同族词、真实固定搭配，以及把这个词义拉得最远的政治说法。"},"normal":[{"en":"The root is the Latin word for law, and the earliest sense was the lawful man, so the adjective began as a legal description.","cn":"词根是拉丁语中表示「法律」的词，最早的意思就是守法之人，所以这个形容词起初是一种法律描述。"},{"en":"The same Latin source entered English twice: once through Old French as this word, later directly as the adjective for what the law permits.","cn":"同一个拉丁来源两次进入英语：一次经古法语成为本词，后来又一次直接成为表示「法律许可」的形容词。"},{"en":"The family runs the noun for the quality, the adverb, the person noun, and both negative forms.","cn":"同族词包括表示这种品质的名词、副词、表示效忠者的人物名词，以及两个否定形式。"},{"en":"Fixed phrases show the usual objects: a loyal friend, a loyal customer, a loyal supporter, and the frame loyal to someone.","cn":"固定搭配显示它常接的对象：忠实的朋友、忠实的顾客、忠实的支持者，以及「忠于某人」的框架。"},{"en":"The phrase loyal opposition shows that loyalty can survive open disagreement, because it is owed to the whole.","cn":"「制度内忠诚的反对」这一说法表明，忠诚可以容纳公开分歧，因为它所向的是整体。"}],"abstract":[{"en":"Picture a name carved inside a doorframe, where only the owner ever sees it.","cn":"想象门框内侧刻着一个名字，只有屋主自己看得见。"},{"en":"Picture a key that opens a shop nobody else bothers to open any more.","cn":"想象一把钥匙，打开一间别人都不再来开的店。"},{"en":"Picture a flag still flying over a post that the map has already forgotten.","cn":"想象一面旗仍飘在地图已经遗忘的哨所上。"}]},"examples":[{"en":"The village remained loyal to its old doctor and refused to replace him with a younger one.","cn":"村民始终忠于那位老医生，不肯换一位更年轻的来替代他。"},{"en":"A loyal customer is worth more than a clever advertisement.","cn":"一位忠实的顾客，比一则聪明的广告更有价值。"},{"en":"She was loyal to the promise she had made, though no one would ever have known.","cn":"她信守自己许下的承诺，尽管这件事永远不会有人知道。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「老友」——把你当老朋友的人，风雨里也不会走开","word":"loyal"},"root":"古法语 loial ← 拉丁 legalis「法律的」← lex「法律」；lex 更深来源不确定，与 legere「收集、读」的关联仅为假说；本词与表示「法律的」的那个英语形容词，是同一拉丁词的两次借入，即双重借入。","sensesIntro":{"en":"Eight senses follow one movement: a bond is chosen and then repeatedly honoured, towards a person, a group, an oath, a shop, a principle, a partner, a state, and finally towards a whole that one may criticise.","cn":"八个义项沿着同一个动作展开：先选定一条纽带，然后一次次守住它——对人、对团体、对誓言、对一家店、对原则、对伴侣、对国家，最后是对一个可以批评的整体。"},"semanticMap":{"core":{"en":"CORE IMAGE: a man still opening a shop whose founder is long dead and whose sign has faded.","cn":"核心意象：创办人早已去世、招牌已经褪色，那个人仍然每天来开门。"},"chain":["STAND BY A PERSON","STAY WITH THE GROUP","KEEP THE OATH","CHOOSE THE SAME SHOP","HOLD TO A PRINCIPLE","CRITICISE AND STILL BELONG"],"branches":[{"senses":"01 · 06","en":"TWO PEOPLE: friendship and romance are the same promise kept across time and distance.","cn":"两个人：友情与爱情，是同一条跨过时间与距离而被守住的承诺。"},{"senses":"02 · 07","en":"A BODY ONE BELONGS TO: a club, a party or a crown can claim the same sworn attachment.","cn":"一个自己归属的集体：俱乐部、党派或王室，都能要求同一种宣誓般的归属。"},{"senses":"03 · 05","en":"AN OBLIGATION: an oath and a principle both bind without anyone watching.","cn":"一项义务：誓言与原则都在无人注视时依然约束人。"},{"senses":"04","en":"REPEATED CHOICE: trade measures loyalty by the customer who still returns.","cn":"重复的选择：商业用「顾客是否仍然回来」来衡量忠诚。"},{"senses":"08","en":"LOYALTY THAT CRITICISES: belonging to the whole can survive disagreement with its government.","cn":"会批评的忠诚：归属于整体，可以容纳与其政府之间的分歧。"}]},"affixes":{"intro":{"en":"This adjective came from Old French, built on the Latin law noun; the whole family can be read through that noun and its endings.","cn":"这个形容词来自古法语，建立在拉丁「法律」名词之上；整个词族都可以顺着这个名词及其词尾读出来。"},"latinIntro":{"en":"Latin lex supplies the noun, legalis turns it into an adjective of belonging, and Old French reshaped that adjective before English borrowed it.","cn":"拉丁 lex 提供名词，legalis 把它变成表示「属于」的形容词，古法语又对这个形容词做了改造，之后英语才借入。"},"items":[{"word":"lex","structure":"lex, legis (Latin noun, third declension)","meaning":"law; statute","meaningCN":"法律；法令","example":"The root names the law that the faithful man was first said to keep.","exampleCN":"这个词根点出那个守法之人最初所守的法律。"},{"word":"legalis","structure":"legalis, -e (Latin adjective from lex)","meaning":"of the law; lawful","meaningCN":"法律的；合法的","example":"The adjective turned the noun into a description of a person.","exampleCN":"这个形容词把名词变成了对人的描述。"},{"word":"loial","structure":"loial (Old French adjective from legalis)","meaning":"faithful; loyal","meaningCN":"忠实的；忠诚的","example":"Old French shifted the sense from lawful to faithful before English took the word.","exampleCN":"古法语把词义从「合法的」转为「忠实的」，之后英语才借入。"},{"word":"loyal","structure":"loyal (English adjective from Old French)","meaning":"faithful to a person or cause","meaningCN":"对人、对事业忠诚的","example":"He stayed loyal to the little studio long after its founder had died.","exampleCN":"创办人去世很久之后，他仍忠于那间小照相馆。"},{"word":"loyalty","structure":"loyal + -ty (noun of state)","meaning":"the state of being faithful","meaningCN":"忠诚的状态","example":"The club rewarded forty years of loyalty with a single chair.","exampleCN":"俱乐部用一把椅子回报了四十年的忠诚。"},{"word":"loyally","structure":"loyal + -ly (in that manner)","meaning":"in a faithful manner","meaningCN":"以忠诚的方式","example":"He served loyally through three changes of owner.","exampleCN":"他忠实地服务，经历了三次换主。"},{"word":"loyalist","structure":"loyal + -ist (person)","meaning":"one who stays faithful to a government or cause","meaningCN":"效忠者；忠实拥护者","example":"The loyalists refused to leave the town when the government fell.","exampleCN":"政府倒台时，效忠者拒绝离开这座城。"},{"word":"disloyal","structure":"dis- (not) + loyal","meaning":"not faithful","meaningCN":"不忠的","example":"A disloyal ally is more dangerous than an open enemy.","exampleCN":"不忠的盟友比公开的敌人更危险。"}],"latinEntries":[{"word":"lex","structure":"lex, legis (f., third declension)","meaning":"law, statute","meaningCN":"法律；法令"},{"word":"legalis","structure":"legalis, -e (adjective)","meaning":"of the law, lawful","meaningCN":"法律的；合法的"},{"word":"legalitas","structure":"legalitas, -atis (f., third declension)","meaning":"lawfulness","meaningCN":"合法性；守法"}],"derivatives":[{"word":"loyalty","pos":"n.","zh":"忠诚；忠心"},{"word":"loyally","pos":"adv.","zh":"忠诚地"},{"word":"loyalist","pos":"n.","zh":"效忠者；忠实拥护者"},{"word":"disloyal","pos":"adj.","zh":"不忠的"},{"word":"disloyalty","pos":"n.","zh":"不忠"}]}},{"word":"commitment","ipa_uk":"/kəˈmɪtmənt/","ipa_us":"/kəˈmɪtmənt/","definition_zh":"承诺；许诺（可数）；投入；献身（不可数）；义务；须承担的债务；委托；交托；资金承诺；（军队）投入；（法律）交付羁押","definition_en":"a promise or pledge that binds the person who makes it, together with the dedication of time, energy or resources to something one has chosen","core_image":"木匠把一枚刻着自己名字的楔子打进新房的房梁，说只要房子还立着，这块木头就不会被取出来","scene":"村口那座石桥修好时，出钱的人在桥墩里嵌了一块刻着名字的青石；后来桥被洪水冲坏两次，他每次都回来出钱重修，也没让人撬走那块石头。His commitment to the village never appeared on a plaque, yet he returned to rebuild the bridge after every flood.","sceneCN":"这里 commitment 指「愿意长期承担、不轻易撤回的承诺与投入」（第 1 个义项：以许诺把自己绑定在某人或某事上）；句意为出资者虽未把名字刻在显眼处，却每次洪灾后都回来重修石桥。可辨识物件：嵌在桥墩里的青石、洪水留下的水痕、修桥的账本、桥头被冲歪的木栏。","pos":[{"tag":"n.","zh":"承诺；投入；献身；义务；委托；资金投入"}],"collocations":[{"phrase":"make a commitment","zh":"作出承诺"},{"phrase":"a firm commitment","zh":"明确的承诺"},{"phrase":"a long-term commitment","zh":"长期承诺"},{"phrase":"commitment to sth","zh":"对某事的投入与承诺"},{"phrase":"financial commitments","zh":"财务上须承担的义务"},{"phrase":"honour a commitment","zh":"履行承诺"}],"forms":[{"label":"复数","form":"commitments"},{"label":"动词原形","form":"commit"},{"label":"动词第三人称单数","form":"commits"},{"label":"动词过去式","form":"committed"},{"label":"动词过去分词","form":"committed"},{"label":"动词现在分词（双写 t）","form":"committing"}],"derivatives":[{"word":"commit","pos":"v.","zh":"承诺；投入；交托；犯下"},{"word":"committed","pos":"adj.","zh":"尽心投入的；已犯下的"},{"word":"committal","pos":"n.","zh":"交付羁押；下葬仪式"},{"word":"committee","pos":"n.","zh":"委员会（受托的一群人）"},{"word":"noncommittal","pos":"adj.","zh":"不表态的；含糊其辞的"}],"senses":[{"no":"01","title":"A promise that binds","titleCN":"把人绑住的承诺","definition":"a firm statement that one will do something, made in a way that others can rely on it","definitionCN":"明确表示自己会做某事，且他人可以据此指望","example":"The company made a commitment to cut its emissions by half before the end of the decade.","exampleCN":"公司承诺在十年之内把排放量减半。","why":"The Latin verb meant to hand something over, and a promise is exactly that: one's future handed to another person.","whyCN":"拉丁动词意为把东西交出去，而承诺正是如此：把自己的未来交到别人手里。"},{"no":"02","title":"Time and energy given to a task","titleCN":"投入时间与精力","definition":"the willingness to spend effort on something over a long period, without counting the hours","definitionCN":"长期愿意为某事付出努力，不计较耗了多少时间","example":"Her commitment to the evening class kept it alive for nine years.","exampleCN":"她为夜校投入的心力，让这所夜校存活了九年。","why":"Once the object is an activity rather than a person, the pledge is measured in hours, and the word becomes devotion.","whyCN":"当对象由人变成一桩活动，承诺就以小时来计算，这个词于是变成投入。"},{"no":"03","title":"An obligation that ties the future","titleCN":"束缚未来的义务","definition":"a duty or debt that limits what one may do later, often named in the plural","definitionCN":"限制日后行动的义务或债务，常用复数","example":"He could not change jobs because of the financial commitments he had taken on.","exampleCN":"由于已经承担的财务义务，他无法换工作。","why":"Anything entrusted creates a counter-duty, and in accounting the word names what is already promised away.","whyCN":"交托出去的任何东西都会带来一项对应义务，在会计里这个词就指已经被许出去的部分。"},{"no":"04","title":"Choosing to stay with a cause","titleCN":"选定一个事业并留在其中","definition":"a settled decision to keep supporting a cause, an institution or a partner through difficulty","definitionCN":"下定决心在困难中持续支持某项事业、某个机构或某位伴侣","example":"The reform only succeeded because a small group showed commitment for a decade.","exampleCN":"改革之所以成功，只因为一小群人十年不撤。","why":"This is the promise seen from inside: the person is not only bound but willingly attached.","whyCN":"这是从内部看的承诺：人不仅被绑住，而且自愿附着其上。"},{"no":"05","title":"Handing a person over to an institution","titleCN":"把人交付给机构","definition":"in law, an order or act by which someone is sent to prison or to a hospital for care","definitionCN":"法律中指把某人送进监狱或送医治疗的命令或行为","example":"The magistrate issued a commitment to a secure ward for assessment.","exampleCN":"治安法官签发了送交封闭病房进行评估的命令。","why":"The oldest meaning of the Latin verb survives here literally: a person is committed, handed over to a keeper.","whyCN":"拉丁动词最古老的意思在这里字面留存：人被交出去，交给看管者。"},{"no":"06","title":"Money already promised away","titleCN":"已经许出去的资金","definition":"in finance and business, funds or resources formally reserved for a purpose and no longer free","definitionCN":"金融与商业中指正式留作某用途、不再自由支配的资金或资源","example":"The foundation reported a capital commitment of two million dollars for the new laboratory.","exampleCN":"基金会公布为新实验室投入了两百万美元的资金承诺。","why":"A promise in business is a sum set aside, so the abstract word turns into a figure on a ledger.","whyCN":"商业中的承诺就是一笔划出来的钱，于是抽象的词变成了账上的一行数字。"},{"no":"07","title":"Forces sent into action","titleCN":"投入战场的部队","definition":"in military writing, the act of sending troops or equipment into a campaign or region","definitionCN":"军事文献中指把部队或装备投入某场战役或某个地区","example":"The government avoided a ground commitment and sent only medical units.","exampleCN":"政府避免投入地面部队，只派出了医疗队。","why":"Sending soldiers is handing over bodies to a place, which is the original gesture in its hardest form.","whyCN":"派出士兵就是把身体交到一个地方，这是那个原初动作最硬的形态。"},{"no":"08","title":"Staying with a choice already made","titleCN":"明知不利仍继续加码","definition":"in psychology and management, the tendency to keep investing in a failing course of action because one has already committed to it","definitionCN":"心理学与管理学中指因为已经投入，明知事情不利仍继续加码的倾向","example":"Escalation of commitment kept the firm pouring money into a product that no one bought.","exampleCN":"承诺升级让这家公司不断往一个没人买的产品里砸钱。","why":"The darker side of the word: a promise already made can trap the one who made it, so commitment becomes a reason to continue rather than a virtue.","whyCN":"这个词较暗的一面：已经作出的承诺会困住作出承诺的人，于是投入变成了继续的理由，而不是美德。"}],"etymology":{"intro":{"en":"Commitment is the noun of commit, from Latin committere 'to join, entrust, hand over', built on com- 'together' and mittere 'to send, let go'. The noun ending -ment comes from Latin -mentum by way of French.","cn":"本词是那个表示「交托、交付」的动词的名词形式，来自拉丁 committere「使结合、交托、交付」，由表示「共同」的拉丁前缀与 mittere「送出、放开」构成。名词词尾来自拉丁语中表示结果的名词词尾，经法语进入英语。"},"items":[{"era":"LATIN MITTERE","en":"Mittere meant 'to send, let go, release'. Its past participle missus lies behind mission and transmit. Source uncertain: the deeper origin of mittere is not settled, so any older form is a reconstruction.","cn":"mittere 意为「送出、放开、释放」。一般认为，其过去分词是表示「派遣」与「传送」的那两个英语词的来源。来源不确定：mittere 的更深来源未定，凡为其给出的更早形式均属重构形式。"},{"era":"LATIN COMMITTERE","en":"Com- 'together' with mittere produced committere, 'to bring together, to entrust, to hand over', and also 'to begin or carry out an act'.","cn":"表示「共同」的拉丁前缀加 mittere 构成 committere，意为「使结合、交托、交付」，另有「开始或实施一桩行为」之义。"},{"era":"LATIN COMMISSUS","en":"The past participle commissus described what had been entrusted or handed over, and the noun commissio named the act itself.","cn":"过去分词 commissus 描述已经被交托或交出的东西，名词 commissio 则指这个动作本身。"},{"era":"SUFFIX -MENTUM","en":"Latin -mentum formed nouns of action and means, as in monumentum; French kept the ending and passed it to English.","cn":"拉丁语中表示动作与手段的名词词尾，可在 monumentum 一词中看到；法语保留了这个词尾，并把它传给英语。"},{"era":"OLD FRENCH COMMETRE","en":"Old French commetre carried the senses of entrusting and of perpetrating an act, and its noun form gave English the word in the fourteenth century.","cn":"古法语 commetre 同时带有「交托」与「实施行为」两义，其名词形式在十四世纪把这个词送进了英语。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date and deeper origin): the earliest English use cannot be pinned to one year, and the origin of mittere itself is not established, so the pre-Latin shape offered for it is a reconstruction.","cn":"来源不确定（首见年代与更深词源）：最早的英语用例无法定到某一年；mittere 本身的来源也未确立，凡为其提出的拉丁语之前的形式均属重构形式。"}]},"similar":{"note":{"en":"Group one holds words built on the same handing-over verb, including one that merely sounds similar but comes from another root; group two holds the near nouns that name a promise, a duty or the effort itself.","cn":"第一组是建立在同一个「交付」动词上的词，其中也包含一个只是读音相近、实际出自另一个词根的词；第二组是相近名词，分别指承诺、义务或投入本身。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"commission","ipa":"/kəˈmɪʃn/","tag":"same root, noun of action","definition":"Built on the same verb with a different noun ending: it names an official task, the body given that task, a percentage paid for a sale, or the carrying out of a crime.","definitionCN":"同一动词配另一个名词词尾构成：它指正式任务、受命的机构、销售提成，也指实施一桩罪行。"},{"word":"committee","ipa":"/kəˈmɪti/","tag":"same root, people entrusted","definition":"The same verb with a suffix meaning the person or body to whom something is entrusted; it names a group, not a pledge.","definitionCN":"同一动词配上表示「受托之人或团体」的词尾；它指一群人，而不是一项承诺。"},{"word":"committal","ipa":"/kəˈmɪtl/","tag":"same root, legal act","definition":"The noun for the act of sending someone to prison or to a hospital, and also for a burial service; it keeps the literal sense of handing over.","definitionCN":"指把人送进监狱或送医的行为，也指下葬仪式；它保留着字面的「交出」之义。"},{"word":"comment","ipa":"/ˈkɒment/","tag":"look-alike, different root","definition":"It sounds and looks close, but it comes from Latin commentum 'a note, a device', from a verb meaning to devise, so it shares no root with this word.","definitionCN":"读音与词形都相近，但来自拉丁 commentum「札记、构想」，其动词意为「设计、构想」，与本词不同源。"}]},{"heading":"NEAR MEANING","entries":[{"word":"pledge","ipa":"/pledʒ/","tag":"formal promise","definition":"A solemn promise, often public and often with something staked on it; this word is wider and can also mean dedication.","definitionCN":"郑重的承诺，常是公开的，且常押上某物作保；本词含义更宽，也可指投入。"},{"word":"dedication","ipa":"/ˌdedɪˈkeɪʃn/","tag":"time given","definition":"The giving of time and energy to a task; it covers the effort but not the promise that may lie behind it.","definitionCN":"把时间与精力给了一桩任务；它涵盖付出，却不涵盖背后可能存在的承诺。"},{"word":"obligation","ipa":"/ˌɒblɪˈɡeɪʃn/","tag":"binding duty","definition":"A duty one is bound to perform, whether or not one chose it; a commitment is usually chosen, while an obligation may be imposed.","definitionCN":"必须履行的义务，不论是否出于自愿；承诺通常是自愿选定的，而义务可能是被强加的。"},{"word":"promise","ipa":"/ˈprɒmɪs/","tag":"given word","definition":"A statement that one will do something; commitment adds the weight of a lasting bond and of resources actually given.","definitionCN":"表示自己会做某事的说法；本词则多了长期纽带的重量，以及真正付出的资源。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real send root and its prefixes, the real family of the verb, the real fixed phrases, and the two faces of promising and perpetrating.","cn":"正常联想：真实的「送出」词根及其前缀、这个动词真实的同族词、真实固定搭配，以及「许诺」与「实施」这两张面孔。"},"normal":[{"en":"The Latin verb is com- 'together' plus mittere 'to send': to commit is to send a part of oneself somewhere and leave it there.","cn":"拉丁动词由「共同」加「送出」构成：作出投入，就是把自己的一部分送出去并留在那里。"},{"en":"The same verb gives mission, admit, submit, transmit and permit, each with a different prefix but the same sending root.","cn":"同一个动词还衍生出表示「派遣、接纳、呈交、传送、准许」的一组词，前缀各不相同，词根都是「送出」。"},{"en":"The noun ending comes from Latin -mentum through French and marks the result or means of an action.","cn":"名词词尾经法语来自拉丁语中表示结果的名词词尾，标记一个动作的结果或手段。"},{"en":"Fixed phrases show the two faces: make a commitment, honour a commitment, and financial commitments.","cn":"固定搭配显示它的两张面孔：作出承诺、履行承诺，以及财务上的承担。"},{"en":"The family runs commit, committed, committal, committee and noncommittal, all from the same handing-over verb.","cn":"同族词包括动词、其分词形容词、表示交付的名词、表示受托群体的名词，以及表示不表态的形容词，全部出自同一个「交付」动词。"}],"abstract":[{"en":"Picture a name cut into a beam that will stay hidden inside the house for a century.","cn":"想象一个名字被刻进房梁，此后一百年都藏在屋子内部。"},{"en":"Picture a hand that writes a sum in a ledger and then cannot take it back.","cn":"想象一只手把一笔钱写进账本，此后就再也拿不回来。"},{"en":"Picture a bridge rebuilt after every flood by the same man who paid for the first one.","cn":"想象同一座桥每次被洪水冲坏都被重修，修桥的还是当初出钱的那一个人。"}]},"examples":[{"en":"The treaty includes a commitment to protect the river for fifty years.","cn":"这项条约包含一项承诺：保护这条河五十年。"},{"en":"She accepted the job because it demanded real commitment, not just talent.","cn":"她接受这份工作，因为它要的是真正的投入，而不只是才华。"},{"en":"Before signing, ask what the commitment will cost you in three years.","cn":"签字之前，先问清楚这项承诺三年后要你付出什么。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「共同 + 送出」——把自己交出去，就有了承诺、投入与承担","word":"commitment"},"root":"拉丁 committere = 表示「共同」的拉丁前缀 + mittere「送出、放开」，原义「交托、托付、使结合」；名词后缀源自拉丁语中表示结果的名词词尾，经法语进入英语。mittere 更深来源不确定。","sensesIntro":{"en":"Eight senses follow one movement: something of one's own is handed over and left in another's keeping, and that gesture becomes a word given, hours spent, a duty carried, a cause served, a person confined, money reserved, troops sent, and finally a trap of one's own making.","cn":"八个义项沿着同一个动作展开：把自己所有的一部分交出去，留在别人手里；这个动作随后变成一句话、一段工时、一项义务、一份事业、一次收押、一笔预留的钱、一支部队，最后变成自己给自己设下的困局。"},"semanticMap":{"core":{"en":"CORE IMAGE: a name carved into a beam and left inside the house for good.","cn":"核心意象：一个名字刻进房梁，从此留在屋子里面不再取出。"},"chain":["GIVE ONE'S WORD","HAND ONESELF OVER","TIE UP THE FUTURE","GIVE TIME AND ENERGY","PLEDGE MONEY OR TROOPS","KEEP GOING ANYWAY"],"branches":[{"senses":"01 · 04","en":"WORD AND ALLEGIANCE: a promise made to a person and a life given to a cause are the same hand-over at different depths.","cn":"言语与归属：对一个人许下的承诺，与献给一项事业的一生，是深浅不同的同一个交付。"},{"senses":"02 · 03","en":"EFFORT AND DUTY: time given freely turns into a weight that limits later choices.","cn":"付出与义务：自愿给出的时间，会变成限制日后选择的重量。"},{"senses":"05","en":"THE LAW'S HAND: a person is literally handed over to a keeper.","cn":"法律之手：人被字面意义上交给看管者。"},{"senses":"06 · 07","en":"RESOURCES AND FORCES: money reserved on a ledger and troops sent to a region are the same pledge in different units.","cn":"资源与兵力：账上预留的钱，与派往一地的部队，是同一份承诺的不同单位。"},{"senses":"08","en":"THE TRAP: staying with a failing choice because leaving would admit that the promise was wasted.","cn":"困局：明知选择不利仍不走，因为离开就等于承认当初的承诺白费了。"}]},"affixes":{"intro":{"en":"Commitment is a Latin noun of action built from a prefix, a verb root and a noun suffix, so each layer can be read separately.","cn":"commitment 是一个拉丁动作名词，由前缀、动词词根与名词后缀构成，每一层都可以单独读出。"},"latinIntro":{"en":"The prefix com- adds togetherness, mittere supplies the act of sending, and -mentum marks the result of that act; French reshaped both the verb and the noun before English borrowed them.","cn":"表示「共同」的拉丁前缀添上共同之意，mittere 提供「送出」这一动作，拉丁语中表示结果的名词词尾标记该动作的结果；法语在英语借入之前，对动词与名词都做了改造。"},"items":[{"word":"mittere","structure":"mittere, misi, missum (Latin verb, third conjugation)","meaning":"to send; to let go","meaningCN":"送出；放开","example":"The root supplies the movement of sending something away from oneself.","exampleCN":"这个词根提供「把东西从自己这里送出去」的动作。"},{"word":"com-","structure":"com- (Latin prefix, 'with, together')","meaning":"with; together","meaningCN":"共同；一起","example":"The prefix makes the sending a joining rather than a separation.","exampleCN":"这个前缀让「送出」变成一种结合，而不是分离。"},{"word":"committere","structure":"com- + mittere (Latin verb)","meaning":"to entrust; to hand over; to begin an act","meaningCN":"交托；交付；开始一桩行为","example":"The Latin verb already held both the peaceful and the criminal senses.","exampleCN":"这个拉丁动词已经同时含有平和与犯罪两方面的意思。"},{"word":"-mentum","structure":"-mentum (Latin noun suffix, result or means)","meaning":"result or means of an action","meaningCN":"动作的结果或手段","example":"The suffix turns the act of handing over into a thing that exists.","exampleCN":"这个词尾把「交付」这一动作变成一件存在的事物。"},{"word":"commitment","structure":"commit + -ment (from Latin -mentum through French)","meaning":"a pledge; dedication; an obligation","meaningCN":"承诺；投入；义务","example":"His commitment to the village never appeared on a plaque.","exampleCN":"他对村子的承诺从未刻在牌匾上。"},{"word":"commit","structure":"commit (English verb from Old French commetre)","meaning":"to promise; to entrust; to carry out","meaningCN":"承诺；交托；实施","example":"The council will commit the money before the winter.","exampleCN":"议会将在入冬前把这笔钱拨定。"},{"word":"committed","structure":"commit + -ed (past participle)","meaning":"having been handed over or pledged; dedicated","meaningCN":"已被交托或承诺的；尽心投入的","example":"The funds were committed long before the building was finished.","exampleCN":"这些资金在楼房完工之前很久就已拨定。"},{"word":"committal","structure":"commit + -al (noun of action)","meaning":"the act of handing someone over, especially to prison or a grave","meaningCN":"把人交出的行为，尤指交付羁押或下葬","example":"The committal order was signed by two magistrates.","exampleCN":"交付羁押的命令由两名治安法官签署。"}],"latinEntries":[{"word":"mittere","structure":"mittere, misi, missum (verb, third conjugation)","meaning":"to send, let go","meaningCN":"送出；放开"},{"word":"committere","structure":"committere, commisi, commissum (verb, third conjugation)","meaning":"to entrust, hand over","meaningCN":"交托；交付"},{"word":"commissio","structure":"commissio, -onis (f., third declension)","meaning":"a committing, an entrusting","meaningCN":"交付；交托"}],"derivatives":[{"word":"commit","pos":"v.","zh":"承诺；投入；交托；犯下"},{"word":"committed","pos":"adj.","zh":"尽心投入的；已犯下的"},{"word":"committal","pos":"n.","zh":"交付羁押；下葬仪式"},{"word":"committee","pos":"n.","zh":"委员会"},{"word":"noncommittal","pos":"adj.","zh":"不表态的"}]}},{"word":"committed","ipa_uk":"/kəˈmɪtɪd/","ipa_us":"/kəˈmɪtɪd/","definition_zh":"尽心投入的；坚定的；忠诚的；（关系）承诺相守的；（罪行）已犯下的；（资金、资源）已投入的；已交托的；已交付委员会审议的","definition_en":"giving wholehearted dedication to a person, cause or task; also the past participle of commit, used of crimes carried out, resources pledged and matters handed over","core_image":"深夜的工地，一个人把安全帽上的名字胶带按紧，蹲下去用手抹平最后一小段未干的混凝土","scene":"深夜的工地已经收工，塔吊的灯灭了，只有一个人还蹲在未干的混凝土旁，用抹子把边角一遍遍压平，安全帽上贴着写有自己名字的胶带。She stayed committed to the project long after the visitors and the cameras had gone.","sceneCN":"这里 committed 形容「把心力真正投进去、不半途撤走的」（第 1 个义项：对事业或任务尽心投入）；句意为探访者与摄像机都离开之后，她仍留在工地收尾。可辨识物件：未干的混凝土、抹子、贴着名字胶带的安全帽、已经熄灭的塔吊灯。","pos":[{"tag":"adj.","zh":"尽心投入的；坚定的；忠诚的；已犯下的"},{"tag":"v.","zh":"本词作动词时为其过去式与过去分词：交托；投入；犯下"}],"collocations":[{"phrase":"be committed to","zh":"致力于；忠于"},{"phrase":"deeply committed","zh":"深度投入的"},{"phrase":"a committed teacher","zh":"尽心尽责的教师"},{"phrase":"committed to reform","zh":"决心推行改革"},{"phrase":"committed funding","zh":"已承诺的资金"},{"phrase":"a committed relationship","zh":"承诺相守的关系"}],"forms":[{"label":"动词原形","form":"commit"},{"label":"动词第三人称单数","form":"commits"},{"label":"动词过去式","form":"committed"},{"label":"动词过去分词（双写 t）","form":"committed"},{"label":"动词现在分词（双写 t）","form":"committing"},{"label":"形容词比较级","form":"more committed"},{"label":"形容词最高级","form":"most committed"}],"derivatives":[{"word":"commit","pos":"v.","zh":"承诺；投入；交托；犯下"},{"word":"commitment","pos":"n.","zh":"承诺；投入；义务"},{"word":"committal","pos":"n.","zh":"交付羁押；下葬仪式"},{"word":"committee","pos":"n.","zh":"委员会"},{"word":"uncommitted","pos":"adj.","zh":"未承诺的；未投入的"}],"senses":[{"no":"01","title":"Wholeheartedly dedicated","titleCN":"尽心投入","definition":"giving full effort and attention to a task or cause, and not withdrawing when it becomes hard","definitionCN":"对任务或事业付出全部心力与注意，在变难时也不抽身","example":"She stayed committed to the project after the funding and the visitors had gone.","exampleCN":"资金与访客都离开之后，她仍对这个项目尽心投入。","why":"The past participle of the verb for handing something over describes a person who has handed their effort over and left it there.","whyCN":"那个表示「交出去」的动词的过去分词，形容一个人把心力交出去并留在那里。"},{"no":"02","title":"Firmly on one side","titleCN":"立场坚定地站在一边","definition":"openly and steadily supporting a person, team or policy over a long period","definitionCN":"长期公开而稳定地支持某人、某队或某项政策","example":"He is a committed supporter of the local league, rain or shine.","exampleCN":"无论晴雨，他都是本地联赛坚定的支持者。","why":"Support that lasts turns the participle into an adjective of character, not of one act.","whyCN":"持续的支持使这个分词变成形容品性的形容词，而不是形容一次行动。"},{"no":"03","title":"A relationship with a promise in it","titleCN":"带有承诺的关系","definition":"describing a couple or partnership that has promised to stay together rather than keep other options open","definitionCN":"形容一对伴侣或合作关系已许诺相守，而不是保留其他选择","example":"They described themselves as a committed couple after two years apart.","exampleCN":"分居两年之后，他们说自己是一对承诺相守的伴侣。","why":"The word marks the moment when a private promise becomes a public shape of life.","whyCN":"这个词标记的正是私下承诺变成公开生活形态的那一刻。"},{"no":"04","title":"A crime already carried out","titleCN":"已经犯下的罪行","definition":"used of an offence that has actually been performed, in the passive constructions of the verb","definitionCN":"在动词的被动结构里，指一桩实际已经实施的违法行为","example":"The offence was committed at midnight, when the cameras were switched off.","exampleCN":"这桩罪行是在午夜、摄像机被关掉的时候犯下的。","why":"Latin committere also meant to begin or carry out an act, and that sense settled on crimes and offences.","whyCN":"拉丁 committere 也有「开始、实施」一义，这一义最终固定在罪行与违法行为上。"},{"no":"05","title":"Handed over to someone's care","titleCN":"交托给他人保管","definition":"used of something formally handed over, whether to a person, to writing, to memory or to an institution","definitionCN":"指某物被正式交出去，或交给某人、写成文字、记入记忆，或交由某机构","example":"The records were committed to the archive before the office closed.","exampleCN":"办公室关闭之前，这些记录已被交存档案馆。","why":"This is the literal sense of the Latin verb, still visible in the passive: a thing is committed, given into keeping.","whyCN":"这是拉丁动词的字面义，在被动式里仍然看得见：东西被交出去，交人保存。"},{"no":"06","title":"Funds already pledged","titleCN":"已经投入的资金","definition":"used of money or resources formally set aside for a purpose and no longer available","definitionCN":"指为某用途正式留出、已不能再挪用的资金或资源","example":"By March, most of the budget was already committed to salaries.","exampleCN":"到三月时，大部分预算已经投入到薪水里。","why":"Accounting speaks of committed funds because the money has been handed over in promise, even before it leaves the account.","whyCN":"会计说「已承诺资金」，因为钱在离开账户之前，就已通过承诺交了出去。"},{"no":"07","title":"Sent to a committee for review","titleCN":"交付委员会审议","definition":"in parliamentary procedure, describing a bill or question that has been formally referred to a committee","definitionCN":"在议会程序中，形容法案或动议已被正式交付某个委员会","example":"The bill was committed to a standing committee and did not return that session.","exampleCN":"这项法案被交付常设委员会，那一届会期没有再回到全院。","why":"A committee is literally a body to which a matter is committed, so the procedural phrase keeps the old image of transfer.","whyCN":"委员会字面上就是「受托的群体」，因此这一程序说法保留了古老的转交意象。"},{"no":"08","title":"Already bound by one's own word","titleCN":"已被自己先前的话绑住","definition":"describing someone who cannot easily change course because of a promise or step already taken","definitionCN":"形容某人因先前的承诺或已迈出的一步，难以轻易改道","example":"We are already committed to the October deadline and cannot move it again.","exampleCN":"我们已经对十月的截止日期作过承诺，不能再挪了。","why":"A commitment made in the past acts on the present, which is why the same participle can mean both devoted and trapped.","whyCN":"过去作出的承诺会作用于现在，因此同一个分词既能指「尽心」，也能指「被绑住」。"}],"etymology":{"intro":{"en":"Committed is the past participle of commit, from Latin committere 'to entrust, hand over', built on com- 'together' and mittere 'to send, let go'. The -ed ending is the English past participle marker, and the form later became an adjective in its own right.","cn":"本词是那个表示「交托、交付」的动词的过去分词，来自拉丁 committere「交托、交付」，由表示「共同」的拉丁前缀与 mittere「送出、放开」构成。词尾是英语过去分词的标记，这一形式后来独立成为形容词。"},"items":[{"era":"LATIN MITTERE","en":"Mittere meant 'to send, let go, release', with the past participle missus. Source uncertain: its deeper origin is not settled, so any older form given for it is a reconstruction.","cn":"mittere 意为「送出、放开、释放」，过去分词为 missus。一般认为，这个分词就是本词词干的来源。来源不确定：其更深来源未定，凡为其给出的更早形式均属重构形式。"},{"era":"LATIN COMMITTERE","en":"Com- 'together' with mittere produced committere, 'to entrust, hand over, join', and also 'to begin or carry out an act'.","cn":"表示「共同」的拉丁前缀加 mittere 构成 committere，意为「交托、交付、使结合」，另有「开始或实施一桩行为」之义。"},{"era":"LATIN COMMISSUS","en":"The past participle commissus named what had been entrusted or handed over, and from it came the noun commissio.","cn":"过去分词 commissus 指已被交托或交出的东西，名词 commissio 即由它而来。"},{"era":"OLD FRENCH COMMETRE","en":"Old French commetre kept both the sense of entrusting and the sense of perpetrating, and English borrowed the verb in the fourteenth century.","cn":"古法语 commetre 同时保留「交托」与「实施」两义，英语在十四世纪借入了这个动词。"},{"era":"ENGLISH PAST PARTICIPLE","en":"English formed the participle with -ed; the doubled t of committing and committed follows the rule that a stressed final consonant doubles before a vowel ending.","cn":"英语用规则词尾构成过去分词；本词的现在分词与过去分词都双写 t，遵循的是「重读闭音节末尾辅音在元音词尾前双写」的规则。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin and first date): the origin of mittere is not established, and the earliest use of the participle as a pure adjective cannot be dated to a single year, so any pre-Latin form proposed is a reconstruction.","cn":"来源不确定（更深词源与首见年代）：mittere 的来源尚未确立；这个分词最早在何时被当作纯形容词使用，也无法定到某一年，凡为其提出的拉丁语之前的形式均属重构形式。"}]},"similar":{"note":{"en":"Group one holds nouns from the same handing-over verb, plus one look-alike from a different root; group two holds adjectives of commitment that differ in what has been given and how firmly.","cn":"第一组是同出「交付」动词的名词，另有一个出自其他词根的形近词；第二组是表示投入的形容词，区别在于交出去的是什么、以及有多坚定。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"commitment","ipa":"/kəˈmɪtmənt/","tag":"same root, noun","definition":"The noun built on the same verb: it names the pledge itself, while the participle describes the person who has made it or the thing already handed over.","definitionCN":"建立在同一动词上的名词：它指承诺本身，而分词则形容作出承诺的人或已经被交出去的事物。"},{"word":"commission","ipa":"/kəˈmɪʃn/","tag":"same root, other noun ending","definition":"Built on the same verb with a different ending: it names a task given to someone, the body that holds it, or a share paid for a sale.","definitionCN":"同一动词配不同词尾构成：它指交给某人的任务、承担该任务的机构，或为销售支付的提成。"},{"word":"committal","ipa":"/kəˈmɪtl/","tag":"same root, legal act","definition":"The noun for the act of sending a person to prison or to a hospital, or for a burial; the participle describes the person after that act.","definitionCN":"指把人送进监狱或送医的行为，也指下葬；分词则形容该行为之后的那个人。"},{"word":"commend","ipa":"/kəˈmend/","tag":"look-alike, different root","definition":"It looks like a twin and even begins with com-, but it comes from Latin commendare, built on mandare 'to entrust with a charge', so it is not the same root as this word.","definitionCN":"它看着像同族，甚至同样带有表示「共同」的拉丁前缀，但来自拉丁 commendare，其词根是 mandare「托付职责」，与本词并非同根。"}]},{"heading":"NEAR MEANING","entries":[{"word":"dedicated","ipa":"/ˈdedɪkeɪtɪd/","tag":"effort given","definition":"Gives time and energy to a task, often as a settled habit; the word under study adds the weight of a promise behind that effort.","definitionCN":"把时间与精力给了一桩任务，常已成为固定习惯；本词则在这份付出背后多了一层承诺的重量。"},{"word":"devoted","ipa":"/dɪˈvəʊtɪd/","tag":"affection given","definition":"Driven by affection or reverence towards a person or cause; it is warmer and less formal than the word under study.","definitionCN":"出于对某人或某项事业的感情或敬意而投入；它比本词更温暖，也更不正式。"},{"word":"pledged","ipa":"/pledʒd/","tag":"something staked","definition":"Bound by a formal promise, often with money or honour staked; it stresses the promise rather than the daily effort.","definitionCN":"受正式承诺约束，常押上金钱或名誉；它强调承诺，而不强调日常的付出。"},{"word":"staunch","ipa":"/stɔːntʃ/","tag":"unshakeable support","definition":"Firmly and unshakeably loyal, especially in politics or conflict; it describes the supporter rather than the work done.","definitionCN":"坚定而不动摇地忠诚，尤用于政治或冲突；它形容支持者，而不形容做成的工。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real send root, the real family of the base verb, the spelling rule that doubles the t, and the two faces of the verb.","cn":"正常联想：真实的「送出」词根、基础动词真实的同族词、使 t 双写的拼写规则，以及这个动词的两张面孔。"},"normal":[{"en":"The base verb is com- 'together' plus mittere 'to send', so being committed means having sent one's effort somewhere and leaving it there.","cn":"基础动词由「共同」加「送出」构成，因此尽心投入就是把自己的心力送到某处并留在那里。"},{"en":"The family runs commit, commitment, committal, committee and uncommitted, all built on the same handing-over verb.","cn":"同族词包括动词、名词、表示交付的名词、表示受托群体的名词，以及表示未承诺的形容词，都出自同一个「交付」动词。"},{"en":"The double t is a spelling rule, not an accident: commit, commits, committing, committed.","cn":"双写 t 只是拼写规则，不是偶然：原形、三单、现在分词、过去式与过去分词都守住这一规则。"},{"en":"The verb has two faces, to commit a crime and to commit oneself to a cause, and the participle carries both.","cn":"这个动词有两张面孔：犯下一桩罪，和投身于一项事业；分词同时承载两者。"},{"en":"Fixed phrases mark its uses: be committed to, deeply committed, committed funding, a committed relationship.","cn":"固定搭配标出它的用场：致力于某事、深度投入、已承诺的资金、承诺稳定的关系。"}],"abstract":[{"en":"Picture a hand still smoothing concrete after every light has been switched off.","cn":"想象所有的灯都已关掉之后，还有一只手在把混凝土抹平。"},{"en":"Picture a signature already dry on a page that cannot be torn out.","cn":"想象一个签名已经干在一页撕不下来的纸上。"},{"en":"Picture a road that has been walked so often that turning back would cost more than going on.","cn":"想象一条已经走过太多遍的路，回头比继续走代价更大。"}]},"examples":[{"en":"The most committed volunteers were the ones nobody photographed.","cn":"最尽心投入的那些志愿者，恰恰是没人拍照的人。"},{"en":"The court found that the fraud had been committed over three years.","cn":"法院认定这起欺诈是在三年间实施的。"},{"en":"Half the budget was committed before the first contract was signed.","cn":"第一份合同签署之前，一半预算就已经拨定。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「共同 + 送出」加上已然——已经把自己交出去，就成了尽心投入","word":"committed"},"root":"拉丁 committere = 表示「共同」的拉丁前缀 + mittere「送出、放开」，原义「交托、托付、使结合」；过去分词词尾为英语标记；本词由那个表示「交托」的动词的过去分词转为形容词。mittere 更深来源不确定。","sensesIntro":{"en":"Eight senses follow one form: a participle that first describes effort handed over, then a person who stands on one side, a couple who promise to stay, a crime carried out, a thing given into keeping, money set aside, a bill sent to a committee, and finally someone bound by their own earlier word.","cn":"八个义项围绕同一个形式展开：这个分词先形容交出去的心力，再形容站在一边的人、许诺相守的一对、已经实施的罪行、被交人保存的东西、被划出的钱、被送进委员会的法案，最后形容被自己先前的话绑住的人。"},"semanticMap":{"core":{"en":"CORE IMAGE: a hand still smoothing the last corner of concrete after every machine has stopped.","cn":"核心意象：所有机器都停下之后，还有一只手在把混凝土的最后一角抹平。"},"chain":["GIVE ONE'S WORD","HAND EFFORT OVER","STAND ON ONE SIDE","PROMISE TO STAY","SEND MONEY OR FORCES","BOUND BY THE PAST"],"branches":[{"senses":"01 · 02","en":"EFFORT AND ALLEGIANCE: the same dedication shows as hours spent on a task or as steady support for a side.","cn":"付出与归属：同一份投入，表现为耗在一桩任务上的工时，或表现为稳稳站在一边。"},{"senses":"03 · 08","en":"PROMISE AND BINDING: a couple's promise and a deadline already accepted are the same word seen at the start and later on.","cn":"承诺与束缚：伴侣之间的许诺与已经接受的截止日期，是同一个词在开头与后来两个时刻的样子。"},{"senses":"04","en":"THE DEED: the verb's other face, where what is carried out is a crime.","cn":"行为：这个动词的另一张面孔，被实施的对象是一桩罪行。"},{"senses":"05 · 07","en":"HANDED TO A KEEPER: a record given to an archive and a bill sent to a committee are the same transfer.","cn":"交给看管者：记录交存档案馆，与法案交付委员会，是同一个转交动作。"},{"senses":"06","en":"MONEY ON A LEDGER: the sum is promised away before it is ever spent.","cn":"账上的钱：这笔钱还没花出去，就已通过承诺许给了别人。"}]},"affixes":{"intro":{"en":"This form is a verb base plus a participial ending; the prefix, root and ending can each be read, and the ending is what turned the verb form into an adjective.","cn":"这个形式由动词词干加分词词尾构成；前缀、词根与词尾都能逐层读出，正是词尾把这个动词形式变成了形容词。"},"latinIntro":{"en":"Latin com- adds togetherness and mittere supplies sending; English then added its own participial ending, which is why this word looks Latin in front and English at the end.","cn":"表示「共同」的拉丁前缀添上共同之意，mittere 提供「送出」；英语随后加上自己的分词词尾，因此这个词前半像拉丁语，末尾却是英语。"},"items":[{"word":"mittere","structure":"mittere, misi, missum (Latin verb, third conjugation)","meaning":"to send; to let go","meaningCN":"送出；放开","example":"The root supplies the act of sending something away from oneself.","exampleCN":"这个词根提供「把东西从自己这里送出去」的动作。"},{"word":"com-","structure":"com- (Latin prefix, 'with, together')","meaning":"with; together","meaningCN":"共同；一起","example":"The prefix turns sending into joining.","exampleCN":"这个前缀把「送出」变成了「结合」。"},{"word":"committere","structure":"com- + mittere (Latin verb)","meaning":"to entrust; to hand over; to carry out","meaningCN":"交托；交付；实施","example":"The Latin verb supplies both the trusting and the criminal sense.","exampleCN":"这个拉丁动词同时提供「交托」与「犯罪」两义。"},{"word":"commissus","structure":"committere + -sus (Latin past participle)","meaning":"entrusted; handed over","meaningCN":"已被交托的；已被交付的","example":"The Latin participle already described something given into keeping.","exampleCN":"这个拉丁分词已经用来描述被交人保存的东西。"},{"word":"-ed","structure":"-ed (English past participle ending)","meaning":"having undergone the action","meaningCN":"已经经历该动作","example":"The ending marks the form as completed action rather than present activity.","exampleCN":"这个词尾把该形式标记为已完成的动作，而不是正在进行的动作。"},{"word":"commit","structure":"commit (English verb from Old French commetre)","meaning":"to entrust; to pledge; to carry out","meaningCN":"交托；承诺；实施","example":"The council will commit the money before winter.","exampleCN":"议会将在入冬前把这笔钱拨定。"},{"word":"committed","structure":"commit + -ed (past participle used as an adjective)","meaning":"dedicated; already handed over or carried out","meaningCN":"尽心投入的；已被交付或实施的","example":"She stayed committed to the project long after the cameras had gone.","exampleCN":"摄像机离开很久之后，她仍对这个项目尽心投入。"},{"word":"commitment","structure":"commit + -ment (from Latin -mentum, result of an action)","meaning":"a pledge; dedication","meaningCN":"承诺；投入","example":"The bridge was rebuilt because one man's commitment outlasted two floods.","exampleCN":"这座桥得以重修，是因为一个人的承诺熬过了两场洪水。"}],"latinEntries":[{"word":"mittere","structure":"mittere, misi, missum (verb, third conjugation)","meaning":"to send, let go","meaningCN":"送出；放开"},{"word":"committere","structure":"committere, commisi, commissum (verb, third conjugation)","meaning":"to entrust, hand over","meaningCN":"交托；交付"},{"word":"commissus","structure":"commissus, -a, -um (perfect participle)","meaning":"entrusted, handed over","meaningCN":"已被交托的；已被交付的"}],"derivatives":[{"word":"commit","pos":"v.","zh":"承诺；投入；交托；犯下"},{"word":"commitment","pos":"n.","zh":"承诺；投入；义务"},{"word":"committal","pos":"n.","zh":"交付羁押；下葬仪式"},{"word":"committee","pos":"n.","zh":"委员会"},{"word":"uncommitted","pos":"adj.","zh":"未承诺的；未投入的"}]}},{"word":"responsibility","ipa_uk":"/rɪˌspɒnsəˈbɪləti/","ipa_us":"/rɪˌspɑːnsəˈbɪləti/","definition_zh":"责任（对所作所为必须作出交代的状态）；职责（岗位所要求照管的具体事务）；归责（法律上把行为及其后果算在某人身上）；责任心（认真可靠、不推卸的品格）；财务责任（须为费用、债务或损失付款）；监护照管（对子女、病人等受扶养者的照料义务）；职权范围（某一职位或委员会管辖的事务边界）；对环境与社会的责任（对自身行为更广泛后果的承担）","definition_en":"the state of being the person who must answer for an act, a duty or an outcome, whether it was done, left undone, or caused","core_image":"车间墙上钉着一块值班牌，机器半夜停了，所有人都抬头去找牌子上写着的那个名字","scene":"车间里的机器半夜停了，早班的人进门时谁也不说话，目光一起落在墙上那块值班牌上。The responsibility for the stalled line belonged to whoever had signed the night log.","sceneCN":"这里 responsibility 指「必须为某件事作出交代的那种身份状态」（第 1 个义项：对已发生之事负有交代义务的状态）；句意为这条停摆产线该由夜班日志上签字的人负责。可辨识物件：墙上的值班牌、停转的机器、夜班日志、挂在机台旁的安全帽。","pos":[{"tag":"n.","zh":"责任；职责；责任心；（法律）归责；财务责任；监护照管；职权范围"}],"collocations":[{"phrase":"take responsibility for","zh":"对……承担责任"},{"phrase":"bear responsibility","zh":"负有责任"},{"phrase":"a sense of responsibility","zh":"责任心；责任感"},{"phrase":"delegate responsibility","zh":"下放职责；授权他人负责"},{"phrase":"corporate social responsibility","zh":"企业社会责任"},{"phrase":"responsibility for dependants","zh":"对受扶养者的照管责任"}],"forms":[{"label":"复数","form":"responsibilities"},{"label":"形容词","form":"responsible"},{"label":"副词","form":"responsibly"},{"label":"形容词（不负责任的）","form":"irresponsible"},{"label":"名词（不负责的状态）","form":"irresponsibility"},{"label":"同根名词（回应）","form":"response"}],"derivatives":[{"word":"responsible","pos":"adj.","zh":"有责任的；应负责的；可靠的"},{"word":"responsibly","pos":"adv.","zh":"负责任地"},{"word":"irresponsible","pos":"adj.","zh":"不负责任的"},{"word":"irresponsibility","pos":"n.","zh":"不负责任"},{"word":"responsibleness","pos":"n.","zh":"负责的性质；可信赖（少用）"}],"senses":[{"no":"01","title":"The state of having to answer","titleCN":"必须作出交代的状态","definition":"the state of being the person who must answer for something done, left undone or caused","definitionCN":"对已做之事、未做之事或自己引起的结果必须作出交代的身份状态","example":"She accepted responsibility for the error without looking for a scapegoat.","exampleCN":"她承认这个错误由她负责，没有去找替罪羊。","why":"The noun names a state rather than a thing, and the Latin verb behind it means to answer back, so the state is one of owing an answer.","whyCN":"这个名词指的是一种状态而非一件东西，其背后的拉丁动词意为「回话」，所以这种状态就是欠着一个回答。"},{"no":"02","title":"A duty attached to a post","titleCN":"岗位所带的具体职责","definition":"a particular task or area of work that a person is expected to look after","definitionCN":"某个人被要求照管的一项具体任务或工作范围","example":"Her responsibilities include checking every invoice before payment.","exampleCN":"她的职责包括付款前核对每一张发票。","why":"A post comes with a list, and each item on that list is the same state seen from outside as a task.","whyCN":"一个岗位自带一张清单，清单上的每一项，就是从外部看到的、作为任务的同一种状态。"},{"no":"03","title":"Legal capacity and attribution","titleCN":"法律上的行为能力与归责","definition":"in law, the capacity to bear the consequences of one's acts, or the act of attributing a deed to a person","definitionCN":"在法律上指承担自身行为后果的能力，或把某一行为算到某人头上的归属判断","example":"The court held that the company bore responsibility for the leak.","exampleCN":"法院认定公司对这起泄漏负有责任。","why":"Law must decide who answers, so the abstract state becomes a finding that a judge can pronounce.","whyCN":"法律必须判定由谁来答话，于是这种抽象状态变成法官可以宣判的结论。"},{"no":"04","title":"Conscientiousness as a trait","titleCN":"作为品格的责任心","definition":"the quality of being reliable and conscientious about what one has agreed to do","definitionCN":"对已经答应的事情认真可靠、不推卸的品质","example":"She shows a strong sense of responsibility even in small tasks.","exampleCN":"即使在琐碎任务中，她也表现出很强的责任心。","why":"When the state is admired rather than assigned, it becomes a personal quality rather than a post.","whyCN":"当这种状态被称赞而不是被指派时，它就成为一种个人品质，而不再是一个岗位。"},{"no":"05","title":"Liability that can be priced","titleCN":"可以用钱结算的财务责任","definition":"the duty to pay for costs, debts or damage, as set out in a contract or by law","definitionCN":"按合同或法律规定，须为费用、债务或损失付款的义务","example":"Under the lease the tenant has responsibility for minor repairs.","exampleCN":"按照租约，房客对小型维修负有责任。","why":"Money makes the answer countable: at the end someone must settle the bill.","whyCN":"钱让这个回答变得可以计算：最后总得有人把账结清。"},{"no":"06","title":"Care owed to a dependent","titleCN":"对受扶养者的照管","definition":"the duty of looking after a child, a patient or someone who cannot act alone","definitionCN":"照料子女、病人或无法独自行动者的义务","example":"Parents share responsibility for their children's schooling.","exampleCN":"父母共同承担子女就学的责任。","why":"The word moves from things to people, and the answer owed is paid in daily care rather than money.","whyCN":"这个词从事转到人身上，欠下的回答要以日常照料而不是金钱来偿还。"},{"no":"07","title":"The boundary of an office","titleCN":"职权所能触及的范围","definition":"the range of matters over which a post, department or committee has authority","definitionCN":"某一职位、部门或委员会拥有管辖权的那些事务范围","example":"Budget decisions fall within the responsibility of the finance committee.","exampleCN":"预算决定属于财务委员会的职权范围。","why":"The same noun can mark a line: it shows what is inside a post and what must be passed elsewhere.","whyCN":"同一个名词也可以划出一条线：它表明什么在岗位之内，什么必须交给别处。"},{"no":"08","title":"Answerability for wider effects","titleCN":"对环境与社会的责任","definition":"the extended duty of a person or organisation for the wider effects of its actions on others and on the environment","definitionCN":"个人或组织对其行为给他人与环境造成的更广泛影响所负的延伸义务","example":"The firm published a report on its responsibility for carbon emissions.","exampleCN":"该公司公布了一份关于自身碳排放责任的报告。","why":"The circle of who must answer widens until it includes people who never signed anything.","whyCN":"必须答话者的圈子不断扩大，直到把从未签过任何字的人也包进来。"}],"etymology":{"intro":{"en":"Responsibility is the noun built on responsible, from Latin respondere 'to answer, promise in return', whose past participle responsus produced the adjective; the suffix -ity then named the state.","cn":"这个名词是在形容词形式之上构造的，源头为拉丁 respondere「回答、回诺」，其过去分词 responsus 生出形容词，再由表示状态的词尾把它变成名词。"},"items":[{"era":"LATIN SPONDERE","en":"The verb spondere meant 'to promise solemnly, to pledge'. Its own origin is debated, and any pre-Latin shape offered for it is a reconstruction.","cn":"动词 spondere 意为「郑重许诺、立誓」，其自身来源存在争议，凡为其提出的拉丁语之前的形式都属重构形式。"},{"era":"LATIN RESPONDERE","en":"Re- 'back' plus spondere formed respondere, 'to answer, to promise in return', first used for a formal reply in a legal or religious setting.","cn":"re-「回」加 spondere 构成 respondere，意为「回答、回诺」，最初用于法律或宗教场合的正式作答。"},{"era":"LATIN RESPONSUS","en":"The past participle responsus 'answered' became the base of the late Latin adjective responsabilis, which passed into French.","cn":"过去分词 responsus「已作答的」成为晚期拉丁形容词 responsabilis 的基础，后者又传入法语。"},{"era":"OLD FRENCH RESPONSABLE","en":"Old French used responsable for 'answerable, accountable'; English borrowed this adjective in the sixteenth century.","cn":"古法语用 responsable 表示「应负责的、可被追究的」，英语在十六世纪末借入这个形容词。"},{"era":"FRENCH RESPONSABILITE","en":"The abstract noun is generally said to appear in French in the eighteenth century, after which English formed its own noun with the ending -ity; this dating is a general account, not a settled fact.","cn":"这个抽象名词一般认为出现于十八世纪的法语，此后英语以自身的状态词尾构造了对应名词；这一年代只是一般说法，并非定论。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date and pre-Latin origin): no year can be fixed for the first English use of the noun, and the origin of spondere before Latin is disputed, so no older form is presented here as established.","cn":"来源不确定（首见年代与拉丁语之前的来源）：无法确定这个名词最早英语用例的年份，spondere 在拉丁语之前的来源也有争议，因此这里不把任何更早的形式当作定论。"}]},"similar":{"note":{"en":"Group one holds words from the same Latin verb that look close but answer different questions; group two holds other nouns for what someone must do, where the demand comes from a different source.","cn":"第一组是同出那个拉丁动词、看着相近却回答不同问题的词；第二组是同样指「某人必须做什么」、但要求来自别处的名词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"responsible","ipa":"/rɪˈspɒnsəbl/","tag":"same root","definition":"The adjective made from the same participle; it asks who is to answer, while the noun names the state of answering.","definitionCN":"由同一个分词构成的形容词；它问的是该由谁答话，名词则指答话这一状态本身。"},{"word":"response","ipa":"/rɪˈspɒns/","tag":"same root","definition":"The direct descendant of the Latin noun for an answer; it names the reply itself, not the duty to give one.","definitionCN":"拉丁语中表示「回答」的名词的直接后裔；它指回答本身，而不是作答的义务。"},{"word":"responsive","ipa":"/rɪˈspɒnsɪv/","tag":"same root, different branch","definition":"Also built on the same participle, but it describes reacting quickly to something; it measures speed of reaction, not accountability, and the two meanings split apart in English.","definitionCN":"同样由那个分词构成，却形容对事物反应迅速；它衡量的是反应快慢而非责任归属，两种意思在英语中已经分道。"},{"word":"sponsor","ipa":"/ˈspɒnsə/","tag":"same root","definition":"From spondere 'to promise solemnly'; it names a person who pledges support or money, and shares the root without implying duty for a fault.","definitionCN":"源自 spondere「郑重许诺」；它指承诺给予支持或出资的人，与本词同根，却不含为过错负责之意。"},{"word":"spouse","ipa":"/spaʊs/","tag":"same root","definition":"Also from spondere, through the idea of a pledged promise; it names a marriage partner and has nothing to do with accountability.","definitionCN":"同样出自 spondere，经由「立下承诺」的意思而来；它指婚姻伴侣，与责任归属无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"accountability","ipa":"/əˌkaʊntəˈbɪləti/","tag":"duty to explain","definition":"The obligation to report and explain what one has done, usually to a higher body; responsibility can be held while nobody is asking for a report.","definitionCN":"向上级报告并解释自己所作所为的义务；责任可以在无人要求汇报时依然存在。"},{"word":"duty","ipa":"/ˈdjuːti/","tag":"the content owed","definition":"What a person owes by law, by office or by conscience; duty is the content, while responsibility is the state of the one who must answer for it.","definitionCN":"一个人依法、依职或依良知所欠之事；义务是内容，责任则是必须为它答话者的状态。"},{"word":"liability","ipa":"/ˌlaɪəˈbɪləti/","tag":"legal and financial","definition":"Legal or financial exposure to a claim; it is the narrow, priced end of responsibility.","definitionCN":"在法律或财务上可能被追索的处境；它是责任最窄、最能用钱计算的那一端。"},{"word":"burden","ipa":"/ˈbɜːdn/","tag":"the weight of it","definition":"A load that is hard to carry; it describes the weight of a duty rather than the duty itself.","definitionCN":"难以承受的负荷；它描述义务的分量，而不是义务本身。"},{"word":"blame","ipa":"/bleɪm/","tag":"fault assigned","definition":"The act of holding someone at fault for something bad; responsibility can exist without blame, as when a manager answers for a team's error.","definitionCN":"把某件坏事的过错算到某人头上；责任可以不含责备，例如主管为团队的错误负责。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Latin verb and its prefix, the real word family, and the fixed phrases that show which frame the noun takes.","cn":"正常联想：真实的拉丁动词及其前缀、真实的同族词，以及能显示这个名词常用框架的固定搭配。"},"normal":[{"en":"The Latin verb means to answer back, so responsibility is the state of owing an answer to someone.","cn":"那个拉丁动词意为「回话」，所以责任就是欠着某个人一个回答的状态。"},{"en":"The family runs respond, response, responsible, responsibly, responsibility and irresponsible, all from the same promise-making verb.","cn":"同族词包括 respond、response、responsible、responsibly、responsibility 与 irresponsible，全部出自同一个表示许诺的动词。"},{"en":"Fixed phrases mark the frame: take responsibility for, bear responsibility, a sense of responsibility, delegate responsibility.","cn":"固定搭配标出常用框架：对某事承担责任、负有责任、责任心、下放职责。"},{"en":"The ending -ity turns an adjective into a state, exactly as it does in ability and possibility.","cn":"表示状态的词尾把形容词变成名词，英语中许多抽象名词都这样构造。"},{"en":"The adjective names who answers and the noun names the state of answering, so keeping the two apart prevents most errors.","cn":"形容词指出谁来答话，名词指出答话的状态，把两者分开就能避免大多数错误。"}],"abstract":[{"en":"Picture a name written on a board that everyone reads before asking any question.","cn":"想象一个写在牌子上的名字，所有人在开口问之前都会先看一眼。"},{"en":"Picture a key handed over with a list of every door it opens and a date for its return.","cn":"想象一把钥匙交到手里时，附着一张写明它能开哪些门、何时归还的清单。"},{"en":"Picture a lamp left burning all night because someone promised to be the last to leave.","cn":"想象一盏整夜亮着的灯，因为有人答应过要做最后离开的那个人。"}]},"examples":[{"en":"Nobody doubted his technical skill; what the team questioned was his willingness to take responsibility.","cn":"没人怀疑他的技术能力，团队质疑的是他是否愿意承担责任。"},{"en":"Clear job descriptions keep responsibilities from falling between two desks.","cn":"清晰的岗位说明能让职责不至于掉进两张办公桌之间的缝里。"},{"en":"Shipping the damaged goods was the company's responsibility under the contract.","cn":"按合同，把受损货物运出是公司的责任。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「回话 + 状态」——该由你回话的那件事，就是你的责任；把回话变成日常，就是职责与责任心","word":"responsibility"},"root":"拉丁 respondere「回答、回诺」= re-（回）+ spondere「郑重许诺」；分词 responsus → 晚期拉丁 responsabilis → 古法语 responsable → 英语的形容词形式，再加表示状态的词尾成 responsibility。同根词有 sponsor、spouse、response、correspond。名词首见年代不确定。","sensesIntro":{"en":"Eight senses follow one state, that of owing an answer: it is assigned to a post, pronounced by a court, admired as a trait, priced as a debt, paid as care, bounded as an office, and finally stretched to cover the wider world.","cn":"八个义项沿着同一种状态展开，那就是欠着一个回答：它被派给岗位、被法院宣判、被当作品格称赞、被折算成债务、以照管来偿还、以职权划出边界，最后延伸到更广阔的世界。"},"semanticMap":{"core":{"en":"CORE IMAGE: a name written on a duty board that everyone reads before asking any question.","cn":"核心意象：写在值班牌上的一个名字，所有人在开口问之前都会先看一眼。"},"chain":["OWE AN ANSWER","HOLD A POST","BE CALLED TO ACCOUNT","CARRY IT PERSONALLY","SETTLE THE BILL","GUARD THE WIDER WORLD"],"branches":[{"senses":"01 · 04","en":"INNER AND OUTER: the same state seen from outside as an assigned post and from inside as a personal trait.","cn":"内与外：同一种状态，从外部看是派给岗位的，从内部看是个人品格。"},{"senses":"02 · 07","en":"THE POST AND ITS EDGE: a job comes with tasks, and it also comes with a line where those tasks stop.","cn":"岗位与边界：一份工作带来任务，也带来一条划定任务止处的线。"},{"senses":"03 · 05","en":"COUNTED AND PRONOUNCED: courts and contracts turn the state into findings and bills.","cn":"被宣判与被计算：法院与合同把这种状态变成裁决与账单。"},{"senses":"06","en":"CARE: here the answer is paid in daily looking-after rather than in words or money.","cn":"照管：这里的回答以日常照料来偿还，而不是用言语或金钱。"},{"senses":"08","en":"BEYOND THE SIGNATURE: the circle widens to effects on people who never agreed to anything.","cn":"越过签字：圈子扩大到那些从未同意过任何事的人所受的影响。"}]},"affixes":{"intro":{"en":"Responsibility can be read morpheme by morpheme: a Latin prefix of return, a root of solemn promise, and two endings that turn the pledge into an adjective and then into a state.","cn":"responsibility 可以按语素逐个读出：表示「回」的拉丁前缀、表示郑重许诺的词根，以及两个把承诺先变成形容词、再变成状态的词尾。"},"latinIntro":{"en":"The Latin root spondere also gives sponsor, spouse, response and correspond. The ending -able came to English through French, and -ity was added to name the state.","cn":"拉丁词根 spondere 还给出 sponsor、spouse、response 与 correspond。表示「能被……」的词尾经法语进入英语，表示状态的词尾则用来指称状态。"},"items":[{"word":"respondere","structure":"respondere (Latin verb, 'to answer, promise in return')","meaning":"to answer; to promise in return","meaningCN":"回答；回诺","example":"The verb supplies the act of answering that the whole family names.","exampleCN":"这个动词提供了整个词族所指的「作答」动作。"},{"word":"re-","structure":"re- (Latin prefix, 'back')","meaning":"back; in return","meaningCN":"回；返回","example":"The prefix makes the promise a reply to someone else.","exampleCN":"这个前缀使许诺成为对他人的回应。"},{"word":"spondere","structure":"spondere (Latin verb, 'to promise solemnly')","meaning":"to pledge; to promise solemnly","meaningCN":"郑重许诺；立誓担保","example":"The root carries the weight of a formal pledge.","exampleCN":"这个词根承载着正式许诺的分量。"},{"word":"responsus","structure":"responsus (past participle of respondere)","meaning":"answered","meaningCN":"已作答的","example":"The participle is the base on which the adjective was built.","exampleCN":"这个分词是构造那个形容词的基础。"},{"word":"responsible","structure":"responsus + -abilis (able to be)","meaning":"able to be called to answer","meaningCN":"可以被要求作答的","example":"The officer on duty is responsible for the night shift.","exampleCN":"值班的那名负责人对夜班负责。"},{"word":"responsibility","structure":"responsible + -ity (state, quality)","meaning":"the state of being answerable","meaningCN":"必须作答的状态","example":"The responsibility for the stalled line belonged to the night supervisor.","exampleCN":"停摆产线的责任属于夜班主管。"},{"word":"irresponsible","structure":"ir- (not) + responsible","meaning":"not answerable; careless about consequences","meaningCN":"不负责任的；不顾后果的","example":"Leaving the records unlocked was irresponsible.","exampleCN":"把记录留在未上锁的地方是不负责任的。"},{"word":"responsibleness","structure":"responsible + -ness (state)","meaning":"the quality of being answerable and reliable","meaningCN":"负责可靠的性质","example":"The board praised the responsibleness of the local staff.","exampleCN":"董事会称赞了当地员工的负责可靠。"}],"latinEntries":[{"word":"spondere","structure":"spondere, spopondi, sponsum (verb, second conjugation)","meaning":"to promise solemnly, pledge","meaningCN":"郑重许诺；立誓担保"},{"word":"respondere","structure":"respondere, respondi, responsum (verb, third conjugation)","meaning":"to answer, reply","meaningCN":"回答；回复"},{"word":"responsabilis","structure":"responsabilis, -e (adjective, late Latin)","meaning":"answerable, accountable","meaningCN":"应负责的；可被追究的"}],"derivatives":[{"word":"responsible","pos":"adj.","zh":"有责任的；应负责的；可靠的"},{"word":"responsibly","pos":"adv.","zh":"负责任地"},{"word":"irresponsible","pos":"adj.","zh":"不负责任的"},{"word":"irresponsibility","pos":"n.","zh":"不负责任"},{"word":"responsibleness","pos":"n.","zh":"负责可靠的性质"},{"word":"respond","pos":"v.","zh":"回答；回应（同根）"}]}},{"word":"responsible","ipa_uk":"/rɪˈspɒnsəbl/","ipa_us":"/rɪˈspɑːnsəbl/","definition_zh":"有责任的（对职责或过失须作出交代）；是……的原因的（指造成某一结果）；可靠的（为人做事稳妥可信）；责任重大的（职位涉及重要决定与后果）；向……负责的（须向上级或机构交代）；正式主管的（被指定照管某项事务）；对环境负责的（行为顾及生态与他人）；有责任心的（肯担当、不推诿）","definition_en":"having a duty to deal with something or being the person who must answer for it, and by extension being the cause of it, or being reliable enough to be trusted with it","core_image":"一把挂着名牌的钥匙，牌子上写着一个人的名字，那扇门出问题时大家找的就是这个人","scene":"实验室的冰柜报警了一整夜，第二天早上，导师把三个人叫到办公室，只问了一句谁最后离开。The student responsible for locking the freezer had signed the log at midnight and then gone home.","sceneCN":"这里 responsible 指「被指定照管某件事、对该事负有专责的」（第 6 个义项：正式主管某事务的）；句意为负责锁冰柜的那名学生签了午夜的值班记录，然后就回家了。可辨识物件：报警的冰柜、签字笔、值班日志、办公室门牌。","pos":[{"tag":"adj.","zh":"有责任的；应负责的；可靠的；责任重大的；对环境负责的"}],"collocations":[{"phrase":"be responsible for","zh":"对……负责；是……的原因"},{"phrase":"hold someone responsible","zh":"追究某人的责任"},{"phrase":"responsible for the delay","zh":"对延误负有责任"},{"phrase":"a responsible position","zh":"责任重大的职位"},{"phrase":"environmentally responsible","zh":"对环境负责的"},{"phrase":"responsible to the board","zh":"向董事会负责"}],"forms":[{"label":"比较级","form":"more responsible"},{"label":"最高级","form":"most responsible"},{"label":"副词","form":"responsibly"},{"label":"名词","form":"responsibility"},{"label":"否定形容词","form":"irresponsible"},{"label":"否定名词","form":"irresponsibility"}],"derivatives":[{"word":"responsibly","pos":"adv.","zh":"负责任地；稳妥地"},{"word":"responsibility","pos":"n.","zh":"责任；职责；责任心"},{"word":"irresponsible","pos":"adj.","zh":"不负责任的"},{"word":"irresponsibility","pos":"n.","zh":"不负责任"},{"word":"responsibleness","pos":"n.","zh":"负责可靠的性质（少用）"}],"senses":[{"no":"01","title":"Accountable for a duty or fault","titleCN":"对职责或过失负有责任","definition":"having the duty to deal with something, or being the person who must answer for a fault","definitionCN":"负有处理某事的职责，或因某项过失而必须作出交代","example":"The driver was responsible for the crash and lost his licence.","exampleCN":"那名司机对这次撞车负有责任，被吊销了驾照。","why":"The adjective points at a person and takes for, naming the thing that person must answer for.","whyCN":"这个形容词指向人，并靠一个表示对象的介词指出这个人必须为之作答的那件事。"},{"no":"02","title":"The cause of an event","titleCN":"是某件事的原因","definition":"being the thing or person that caused a particular event or result","definitionCN":"指某事物或某人造成了某一事件或结果","example":"A loose wire was responsible for the power cut.","exampleCN":"是一根松动的电线造成了这次停电。","why":"English stretches the accountable frame to causes: what produced the result is said to answer for it.","whyCN":"英语把「负责」的框架延伸到原因上：造成结果的东西，也被说成要对结果作答。"},{"no":"03","title":"Reliable and sensible","titleCN":"为人可靠、做事稳妥","definition":"describing a person whose behaviour is sensible and can be trusted","definitionCN":"形容一个人行事稳妥、可以信赖","example":"She is a responsible employee who never leaves a task half done.","exampleCN":"她是个可靠的员工，从不把任务做到一半就丢下。","why":"Someone who answers for things tends to be careful, so the adjective came to describe character rather than a single duty.","whyCN":"一个肯为事情作答的人往往谨慎，于是这个形容词也用来描述品格，而不只是一项职责。"},{"no":"04","title":"Carrying serious duties","titleCN":"责任重大的","definition":"describing a job or position that involves important decisions and serious consequences","definitionCN":"形容一份工作或职位涉及重要决定与严重后果","example":"Editing the medical journal is a responsible position.","exampleCN":"编辑这份医学期刊是一个责任重大的职位。","why":"Here the adjective moves from the person to the post, describing the weight of the duties attached to it.","whyCN":"这里形容词从人移到职位上，描述附着在这个职位上的职责分量。"},{"no":"05","title":"Answerable to an authority","titleCN":"须向某机构或上级交代","definition":"having to report to a person or body with authority and to justify one's actions before them","definitionCN":"必须向有职权的个人或机构汇报，并在其面前解释自己的行为","example":"The committee is responsible to the full board, not to the chair alone.","exampleCN":"该委员会向整个董事会负责，而不是只向主席负责。","why":"The preposition to marks the direction of the answer, which here runs upward rather than outward.","whyCN":"介词 to 标出回答的方向，在这里是朝上的，而不是朝外的。"},{"no":"06","title":"Officially in charge of a matter","titleCN":"正式主管某项事务","definition":"describing the person or unit officially appointed to look after a particular matter","definitionCN":"形容被正式指定照管某一具体事务的人或单位","example":"The officer responsible for port security reports every incident.","exampleCN":"负责港口安全的官员会报告每一起事件。","why":"The attributive use places the word after the noun and simply marks who holds the task.","whyCN":"定语用法把这个词放在名词之后，只标出这项任务由谁持有。"},{"no":"07","title":"Careful towards the environment","titleCN":"对环境负责的","definition":"describing behaviour or business practice that weighs the harm it does to the environment and to other people","definitionCN":"形容顾及自身对环境与他人造成的损害的行为或商业做法","example":"The chain publishes an annual report on responsible sourcing.","exampleCN":"这家连锁企业每年公布关于负责任采购的报告。","why":"The object of answerability widened from a single task to the world that the task affects.","whyCN":"作答的对象从一项任务扩大到这项任务所影响的世界。"},{"no":"08","title":"Showing a sense of duty","titleCN":"有责任心、肯担当","definition":"describing someone who takes their share of the work seriously instead of leaving it to others","definitionCN":"形容一个人认真承担自己那份工作，而不是推给别人","example":"It was responsible of him to report the error himself.","exampleCN":"他主动报告了这个错误，很有担当。","why":"The trait sense turns the relation into a virtue, and the pattern with of him shows that judgement.","whyCN":"品格义把这种关系变成一种美德，而以人作宾语的句式正显出这种评价。"}],"etymology":{"intro":{"en":"Responsible comes from Latin respondere 'to answer, promise in return', built on re- 'back' and spondere 'to promise solemnly'. Its past participle responsus took the ending -abilis, which became the English -able, and the abstract noun later added -ity.","cn":"responsible 来自拉丁 respondere「回答、回诺」，由 re-「回」与 spondere「郑重许诺」构成。其过去分词 responsus 接上拉丁词尾 -abilis，后者在英语中变成表示「能被……」的形容词词尾；抽象名词则再加表示状态的词尾。"},"items":[{"era":"LATIN SPONDERE","en":"Spondere meant 'to promise solemnly, to pledge'; it also produced sponsor and spouse, so those words are relatives by root, not by meaning.","cn":"spondere 意为「郑重许诺、立誓」，它还生出 sponsor 与 spouse，因此那两个词只是同根，并不同义。"},{"era":"LATIN RESPONDERE","en":"Re- 'back' plus spondere gave respondere, 'to answer, to promise in return'; its family includes response and correspond, where com- 'together' adds the idea of answering each other.","cn":"re-「回」加 spondere 构成 respondere「回答、回诺」；其词族还有 response 与 correspond，后者以 com-「共同」添上彼此作答之意。"},{"era":"LATIN RESPONSUS + ABILIS","en":"The participle responsus 'answered' took -abilis, an ending meaning 'able to be, fit to be', and produced responsabilis 'answerable'. French shortened the ending to -able, and English borrowed that form.","cn":"分词 responsus「已作答的」接上意为「能被……的、适合被……」的拉丁词尾 -abilis，构成 responsabilis「可被要求作答的」。法语把这个词尾简化之后，英语借入的就是简化后的形式。"},{"era":"OLD FRENCH RESPONSABLE","en":"Old French responsable meant 'answerable, accountable', and English adopted it in the sixteenth century with the legal flavour of a person who must answer in court.","cn":"古法语 responsable 意为「应负责的、可被追究的」，英语在十六世纪末借入，起初仍带「须在法庭上作答」的法律意味。"},{"era":"ENGLISH 16TH CENTURY","en":"The earlier sense was answering for a fault; reliable and holding an important post came later. A different form built on the same participle went another way and came to mean reacting quickly rather than bearing responsibility.","cn":"较早的义项是为过失作答；「可靠」与「担任要职」都后起。另一个同出该分词的形式另走一路，表示反应迅速，而不是承担责任。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (dates and the abstract noun): no year is fixed for the first English use of the adjective or for the reliable sense; -ity is the Latin state ending seen in ability and possibility, and the French origin of the abstract noun is generally put in the eighteenth century without being settled.","cn":"来源不确定（年代与抽象名词）：这个形容词最早的英语用例以及「可靠」义的出现都没有确切年份；表示状态的词尾是拉丁语中常见的构词成分；抽象名词源于法语的说法一般定在十八世纪，但并非定论。"}]},"similar":{"note":{"en":"Group one holds words that share the answering root but have drifted apart in sense; group two holds adjectives of reliability and blame, where the confidence comes from a different source.","cn":"第一组是同出「作答」词根、却各自走偏的词；第二组是表示可靠与责备的形容词，其信心或依据来自别处。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"responsibility","ipa":"/rɪˌspɒnsəˈbɪləti/","tag":"same root","definition":"The noun formed from this adjective with -ity; it names the state, while the adjective describes the person who is in that state.","definitionCN":"这个形容词加表示状态的词尾构成的名词；它指状态，形容词则描述处于该状态的人。"},{"word":"response","ipa":"/rɪˈspɒns/","tag":"same root","definition":"The direct descendant of the Latin noun for an answer; it names the reply and carries no judgement about duty.","definitionCN":"拉丁语中表示「回答」的名词的直接后裔；它只指回答，不含关于责任的评判。"},{"word":"responsive","ipa":"/rɪˈspɒnsɪv/","tag":"same root, split sense","definition":"Built on the same Latin participle, yet it means reacting quickly or sympathetically; the two words divided the territory, one taking accountability and the other taking speed of reaction.","definitionCN":"同出那个拉丁分词，意思却是反应迅速或体贴回应；两词分了地盘，一个拿走责任，一个拿走反应速度。"},{"word":"correspond","ipa":"/kəˈrɪspɒnd/","tag":"same root","definition":"Com- 'together' plus respondere gives 'answer to each other'; it describes letters exchanged or things that match, not duties.","definitionCN":"com-「共同」加 respondere 得「彼此作答」；它描述往来书信或彼此相合的事物，与职责无关。"},{"word":"sponsor","ipa":"/ˈspɒnsə/","tag":"same root, other branch","definition":"From spondere alone, without the prefix of return; it names one who pledges money or support and never means answerable for a fault.","definitionCN":"只出自 spondere，没有那个表示「回」的前缀；它指承诺出资或支持的人，从不表示要为过失负责。"}]},{"heading":"NEAR MEANING","entries":[{"word":"accountable","ipa":"/əˈkaʊntəbl/","tag":"must give an account","definition":"Required to explain and justify one's actions to someone; it stresses the reporting side, where responsible can simply mean holding a duty.","definitionCN":"有义务向某人解释并论证自己的行为；它强调汇报的一面，而 responsible 可以只表示持有职责。"},{"word":"answerable","ipa":"/ˈɑːnsərəbl/","tag":"formal twin","definition":"The closest formal synonym, usually followed by for or to; it is common in legal and official writing and rare in speech.","definitionCN":"最接近的正式同义词，通常后接表示对象或方向的介词；多见于法律与公文，口语中罕见。"},{"word":"liable","ipa":"/ˈlaɪəbl/","tag":"legal exposure","definition":"Legally bound to pay or to suffer a penalty; it is the narrow legal branch, while responsible also covers moral and practical duties.","definitionCN":"在法律上有付款或受罚的义务；它是窄的法律分支，而 responsible 还涵盖道德与实际职责。"},{"word":"reliable","ipa":"/rɪˈlaɪəbl/","tag":"can be counted on","definition":"Able to be depended on to do what is expected; it matches the third sense of responsible but says nothing about duties or causes.","definitionCN":"可以指望它做到该做的事；它对应 responsible 的第三个义项，却不涉及职责或原因。"},{"word":"dependable","ipa":"/dɪˈpendəbl/","tag":"steady over time","definition":"Consistently reliable over a long period; it describes steadiness of performance, not the holding of an office.","definitionCN":"在较长时期里始终可靠；它描述表现的稳定性，而不是担任某个职位。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Latin verb, the two endings that built the adjective and the noun, the real word family, and the prepositions that decide which sense appears.","cn":"正常联想：真实的拉丁动词、构成形容词与名词的两个词尾、真实的同族词，以及决定出现哪个义项的介词。"},"normal":[{"en":"The Latin verb means to answer back, so responsible describes someone who owes an answer.","cn":"那个拉丁动词意为「回话」，所以 responsible 描述一个欠着回答的人。"},{"en":"The family runs respond, response, responsible, responsibly, responsibility, irresponsible and irresponsibility.","cn":"同族词包括 respond、response、responsible、responsibly、responsibility、irresponsible 与 irresponsibility。"},{"en":"The ending -able means able to be, and -ity means state, so responsibility is the state of being able to be called to answer.","cn":"表示「能被……」的词尾加上表示状态的词尾，所以 responsibility 就是「能被叫来作答的状态」。"},{"en":"Sponsor and spouse share the promise root but not the duty, which is why they look related and behave differently.","cn":"sponsor 与 spouse 共享「许诺」词根，却不含责任，所以它们看着像亲戚，用法却不同。"},{"en":"Prepositions select the sense: responsible for a task, responsible for a delay, responsible to a board, a responsible post.","cn":"介词决定义项：对任务负责、对延误负责、向董事会负责、一个责任重大的职位。"}],"abstract":[{"en":"Picture a key tag with a name on it, so that a broken door already has an owner before anyone asks.","cn":"想象钥匙牌上写着一个名字，门坏了的时候，还没等人问就已经有了主人。"},{"en":"Picture a note on the kitchen wall that says who feeds the dog, changed every week without argument.","cn":"想象厨房墙上贴着一张纸条，写明这周谁喂狗，每周更换，从不需要争吵。"},{"en":"Picture two chairs at a night desk, one pushed back, because the person who sat there promised to return.","cn":"想象夜班桌前有两把椅子，其中一把往后推开，因为坐在那里的人答应过会回来。"}]},"examples":[{"en":"The pilot is responsible for the safety of everyone on board.","cn":"机长对机上每个人的安全负责。"},{"en":"Poor drainage was responsible for the flooded cellar.","cn":"排水不畅是地下室被淹的原因。"},{"en":"The company now buys only responsible palm oil.","cn":"这家公司现在只采购对环境负责的棕榈油。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「回诺 + 能够」——能被叫回来答话的人，就是有责任的；把回诺做得稳，就是可靠与担当","word":"responsible"},"root":"拉丁 respondere「回答、回诺」= re-（回）+ spondere「郑重许诺」；过去分词 responsus 加拉丁词尾 -abilis（能被……的）成晚期拉丁 responsabilis，经古法语 responsable 进入英语；名词再加表示状态的词尾。同根词有 response、responsive、correspond、sponsor、spouse。","sensesIntro":{"en":"Eight senses follow one adjective through its grammar: for marks the duty and then the cause, the bare adjective marks character, the post brings weight, to marks the authority, the attributive slot picks out the officer in charge, and the last two widen the duty to the environment and to the person.","cn":"八个义项让同一个形容词走遍它的句法位置：表示对象的介词先标出职责、再标出原因；不带介词时标出品格；修饰职位时带来分量；表示方向的介词标出上级；定语位置挑出主管者；最后两个把责任扩展到环境与人本身。"},"semanticMap":{"core":{"en":"CORE IMAGE: a key tag with a name on it, so that a broken door already has an owner.","cn":"核心意象：钥匙牌上写着一个名字，门一坏就已经有了负责的人。"},"chain":["ANSWER FOR IT","CAUSE IT","BE COUNTED ON","HOLD THE POST","REPORT UPWARD","TAKE THE WIDER WORLD"],"branches":[{"senses":"01 · 02","en":"DUTY AND CAUSE: the frame with for covers both what a person must answer for and what merely produced a result.","cn":"职责与原因：带对象介词的框架既指人必须为之作答的事，也指仅仅造成结果的东西。"},{"senses":"03 · 08","en":"CHARACTER: a reliable worker and a person who owns up are two views of the same virtue.","cn":"品格：可靠的员工与肯认错的人，是同一种美德的两个侧面。"},{"senses":"04 · 05","en":"WEIGHT AND DIRECTION: a post carries serious duties and points the answer upward to an authority.","cn":"分量与方向：要职带来沉重职责，并把回答朝上指向某个上级。"},{"senses":"06","en":"THE NAMED OFFICER: attributive position picks out the one officially in charge.","cn":"被点名的负责人：定语位置挑出正式主管此事的那一个。"},{"senses":"07","en":"BEYOND THE TASK: the duty extends to the environment and to people affected by the work.","cn":"越过任务：责任延伸到环境，以及受这项工作影响的人。"}]},"affixes":{"intro":{"en":"Responsible divides into a prefix of return, a root of solemn promise, and the ending -able meaning able to be; the noun adds -ity, which names a state.","cn":"responsible 可分成表示「回」的前缀、表示郑重许诺的词根，以及意为「能被……的」词尾；名词再加表示状态的词尾。"},"latinIntro":{"en":"Latin -abilis passed through French as -able, and -ity is the Latin state ending also seen in ability. The root spondere recurs in sponsor and spouse, while respondere recurs in response and correspond.","cn":"拉丁词尾 -abilis 经法语进入英语；表示状态的词尾则是拉丁语常见的构词成分。词根 spondere 还见于 sponsor 与 spouse，respondere 还见于 response 与 correspond。"},"items":[{"word":"re-","structure":"re- (Latin prefix, 'back')","meaning":"back; in return","meaningCN":"回；作为回报","example":"The prefix turns a promise into an answer given back.","exampleCN":"这个前缀把许诺变成回给对方的回答。"},{"word":"spondere","structure":"spondere (Latin verb, 'to promise solemnly')","meaning":"to pledge; to promise solemnly","meaningCN":"郑重许诺；立誓担保","example":"The root supplies the weight of a formal pledge.","exampleCN":"这个词根提供正式许诺的分量。"},{"word":"respondere","structure":"re- + spondere","meaning":"to answer; to promise in return","meaningCN":"回答；回诺","example":"The verb is the source of the whole English family.","exampleCN":"这个动词是整个英语词族的源头。"},{"word":"responsus","structure":"responsus (past participle of respondere)","meaning":"answered","meaningCN":"已作答的","example":"The participle forms the stem to which the suffix was attached.","exampleCN":"这个分词构成接后缀的词干。"},{"word":"-abilis","structure":"-abilis (Latin adjective ending, 'able to be')","meaning":"able to be; fit to be","meaningCN":"能被……的；适于被……的","example":"The ending makes the answered person one who can be called to answer.","exampleCN":"这个词尾使「被作答的人」成为「可以被叫来作答的人」。"},{"word":"responsible","structure":"responsus + -abilis, through French -able","meaning":"answerable; reliable","meaningCN":"应负责的；可靠的","example":"The officer responsible for port security reports every incident.","exampleCN":"负责港口安全的官员会报告每一起事件。"},{"word":"responsibility","structure":"responsible + -ity (state)","meaning":"the state of being answerable","meaningCN":"应负责的状态","example":"The report placed responsibility on the contractor.","exampleCN":"这份报告把责任归于承包商。"},{"word":"irresponsible","structure":"ir- (not) + responsible","meaning":"not answerable; careless","meaningCN":"不负责任的；不顾后果的","example":"It was irresponsible to leave the samples uncovered.","exampleCN":"把样品敞着不盖是不负责任的。"}],"latinEntries":[{"word":"spondere","structure":"spondere, spopondi, sponsum (verb, second conjugation)","meaning":"to promise solemnly, pledge","meaningCN":"郑重许诺；立誓担保"},{"word":"respondere","structure":"respondere, respondi, responsum (verb, third conjugation)","meaning":"to answer, reply","meaningCN":"回答；回复"},{"word":"responsabilis","structure":"responsabilis, -e (adjective, late Latin)","meaning":"answerable, accountable","meaningCN":"应负责的；可被追究的"}],"derivatives":[{"word":"responsibly","pos":"adv.","zh":"负责任地"},{"word":"responsibility","pos":"n.","zh":"责任；职责"},{"word":"irresponsible","pos":"adj.","zh":"不负责任的"},{"word":"irresponsibility","pos":"n.","zh":"不负责任"},{"word":"responsibleness","pos":"n.","zh":"负责可靠的性质（少用）"}]}},{"word":"obligation","ipa_uk":"/ˌɒblɪˈɡeɪʃn/","ipa_us":"/ˌɑːblɪˈɡeɪʃn/","definition_zh":"义务（良心或道德上必须履行的事）；法律义务（法令、合同或规章所规定的作为或不作为）；债务（必须偿付的款项或必须提供的给付）；人情债（受恩之后觉得应当回报的亏欠感）；约束力（誓约、承诺或规则对人的拘束力量）；受托职责（因担任职务而必须尽到的义务）；契据债券（以文书形式承认的付款义务）；被迫感（觉得别无选择、只能去做的心理压力）","definition_en":"a binding requirement, whether moral, legal or contractual, that a person is bound to carry out or to pay","core_image":"一根绳子一头系在人的手腕上，另一头系在一张写满条款的纸上，风吹得纸响，绳子始终不松","scene":"公证处的窗口前，一位老人把一份发黄的借据摊在桌上，说当年借钱的人已经去世，他的儿子仍然每年送来利息。The obligation had outlived the man who signed it.","sceneCN":"这里 obligation 指「按字据必须偿付的债务」（第 3 个义项：必须偿付的款项）；句意为这笔债比签字的人活得更久。可辨识物件：发黄的借据、窗口玻璃、红色印章、利息收条。","pos":[{"tag":"n.","zh":"义务；法律责任；债务；人情债；约束力；受托职责"}],"collocations":[{"phrase":"a legal obligation","zh":"法律义务"},{"phrase":"be under an obligation to","zh":"有义务去做"},{"phrase":"fulfil an obligation","zh":"履行义务"},{"phrase":"a moral obligation","zh":"道德义务"},{"phrase":"without obligation","zh":"不附带任何义务"},{"phrase":"meet one's obligations","zh":"偿还债务；履行承诺"}],"forms":[{"label":"复数","form":"obligations"},{"label":"形容词（有约束力的）","form":"obligatory"},{"label":"副词","form":"obligatorily"},{"label":"动词","form":"oblige"},{"label":"形容词（受约束的；承蒙的）","form":"obliged"},{"label":"名词（权利人）","form":"obligee"}],"derivatives":[{"word":"obligatory","pos":"adj.","zh":"强制性的；义务的"},{"word":"obligatorily","pos":"adv.","zh":"强制性地"},{"word":"oblige","pos":"v.","zh":"使负有义务；施恩于"},{"word":"obliged","pos":"adj.","zh":"有义务的；感激的"},{"word":"obliging","pos":"adj.","zh":"乐于助人的；殷勤的"},{"word":"obligee","pos":"n.","zh":"债权人；权利人"}],"senses":[{"no":"01","title":"A duty felt in conscience","titleCN":"良心上的义务","definition":"a duty that a person feels bound in conscience to perform, even when no one can compel it","definitionCN":"一个人在良心上觉得必须履行、即使无人能强制也必须做的义务","example":"She felt an obligation to tell the family what she had seen.","exampleCN":"她觉得有义务把自己看到的事告诉这家人。","why":"The Latin verb means to bind, so the word pictures a person tied to a task before any law appears.","whyCN":"那个拉丁动词意为「捆绑」，所以这个词描绘的是在法律出现之前，一个人就已经被系在一件事上。"},{"no":"02","title":"A duty imposed by law or contract","titleCN":"法律或合同规定的义务","definition":"a requirement that a statute, contract or official rule lays on a person and that can be enforced","definitionCN":"由法令、合同或正式规章加于某人、并且可以被强制执行的作为或不作为要求","example":"The lease imposes an obligation to repair the roof by June.","exampleCN":"租约规定了一项在六月前修好屋顶的义务。","why":"Once a court can enforce the bond, the image of a rope becomes a legal relation with a remedy.","whyCN":"一旦法院可以强制执行这根绳子，捆绑的图景就变成带有救济手段的法律关系。"},{"no":"03","title":"A debt that must be paid","titleCN":"必须偿还的债务","definition":"a sum of money or a service that one is bound to pay or provide to another","definitionCN":"必须向他人偿付的款项，或必须向他人提供的给付","example":"The obligation had outlived the man who signed it.","exampleCN":"这笔债比签字的人活得更久。","why":"Bonds are most often counted in money, so the general binding became a figure on a ledger.","whyCN":"捆绑最常见于金钱，于是这种一般的约束就变成账本上的一个数字。"},{"no":"04","title":"A debt of gratitude","titleCN":"受恩后的人情债","definition":"the sense of owing something back after receiving help or kindness that cannot be repaid in full","definitionCN":"得到帮助或恩惠之后，觉得应当回报、却又无法完全还清的那种亏欠感","example":"He stayed to look after the old teacher out of a sense of obligation.","exampleCN":"他留下来照顾那位老教师，是出于一份人情上的亏欠感。","why":"Kindness can bind as firmly as a contract, and English uses the same word for both ties.","whyCN":"恩惠能像合同一样把人系住，英语对这两种束缚用了同一个词。"},{"no":"05","title":"The binding force of a promise","titleCN":"誓约与规则具有的约束力","definition":"the force that a promise, oath or rule has in holding a person to a stated course of action","definitionCN":"誓约、承诺或规则把一个人固定在既定做法上的那股力量","example":"The oath carried an obligation that he could not easily set aside.","exampleCN":"那个誓约带着一种约束力，他无法轻易搁下。","why":"Here the noun names not the task but the pull that keeps a person from walking away.","whyCN":"这里名词指的不是任务，而是不让一个人走开的那股拉力。"},{"no":"06","title":"Duties attached to a trust or office","titleCN":"受托或任职所带来的职责","definition":"the specific duties that a person must perform because of a post or a trust accepted","definitionCN":"因担任某个职位或接受某项托付而必须履行的具体职责","example":"A trustee's obligations include keeping accounts open to inspection.","exampleCN":"受托人的职责包括保存可供查阅的账目。","why":"A post adds its own set, so the general bond becomes a list that other people can check.","whyCN":"一个职位自带一整套要求，于是笼统的捆绑变成别人可以核对的清单。"},{"no":"07","title":"A sealed bond or written undertaking","titleCN":"契据形式的债券与承诺书","definition":"in law, a written document under seal by which a person binds himself to pay a sum or to perform an act","definitionCN":"在法律上指加盖印章的文书，当事人在其中承诺付款或履行某项行为","example":"The estate settled the obligation recorded in the bond.","exampleCN":"遗产管理人清偿了债券上记载的那笔债务。","why":"The word once named the paper itself, because the paper was the thing that did the binding.","whyCN":"这个词曾经直接指那张纸，因为起捆绑作用的就是那张纸。"},{"no":"08","title":"The felt pressure of having no choice","titleCN":"别无选择的被迫感","definition":"the state of feeling compelled to act, whether or not one agrees with the act","definitionCN":"觉得不得不做某事的状态，不论自己是否认同这件事","example":"He signed the form under obligation, not out of any belief in the scheme.","exampleCN":"他在被迫的情况下签了表格，并不是因为相信这个方案。","why":"When the tie is felt from the inside, the noun describes a pressure rather than a duty owed.","whyCN":"当这根绳子从内部被感受到时，这个名词描述的是压力，而不是欠下的义务。"}],"etymology":{"intro":{"en":"Obligation comes from Latin obligare 'to bind, tie up', built on ob- 'towards, against' and ligare 'to bind'. The noun obligatio passed through Old French into English, keeping both the moral and the legal sense.","cn":"obligation 来自拉丁 obligare「捆绑、约束」，由 ob-「朝向、对着」与 ligare「绑」构成。名词 obligatio 经古法语进入英语，同时保留了道德与法律两层意思。"},"items":[{"era":"LATIN LIGARE","en":"Ligare meant 'to bind, tie'. It also gives ligament and ligature, where the same root names things that fasten; its deeper origin is not established, so any earlier form offered for it is a reconstruction.","cn":"ligare 意为「绑、系」。它同样给出 ligament 与 ligature，同一个词根在两词中指起固定作用的东西；其更深的来源未获证明，凡为其提出的更早形式都属重构形式。"},{"era":"LATIN OBLIGARE","en":"Ob- 'towards, against' plus ligare formed obligare, 'to bind towards someone', hence to put a person under a duty. The prefix marks the direction of the tie, not its strength.","cn":"ob-「朝向、对着」加 ligare 构成 obligare，意为「朝某人绑过去」，引申为使某人负上义务。前缀标的是捆绑的方向，而不是力度。"},{"era":"LATIN OBLIGATIO","en":"The noun obligatio named both the act of binding and the bond itself; Roman law used it for a tie that could be enforced by an action.","cn":"名词 obligatio 既指捆绑的动作，也指束缚本身；罗马法用它指可以通过诉讼强制执行的约束关系。"},{"era":"OLD FRENCH OBLIGATION","en":"Old French obligation carried the moral sense of a duty and the legal sense of a bond, and English adopted it in the fourteenth century.","cn":"古法语 obligation 兼有道德义务与法律债券两层意思，英语在十四世纪借入。"},{"era":"ENGLISH LEGAL USE","en":"English law kept the written-bond sense, and the everyday moral sense grew beside it; obligation to and under an obligation are the modern frames that separate them.","cn":"英国法保留了文书债券的义项，日常的道德义在旁边生长；后接表示对象的介词，与「负有义务」这一固定说法，正是今天区分两者的框架。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin of ligare and the English date): the link with religion is real but semantic only, since religio is generally explained as re- plus ligare in the sense of binding fast, while ally and alliance come from ad- plus ligare with a different prefix and a different sense, and obligation shares the root with religion without sharing any meaning.","cn":"来源不确定（ligare 的更深来源与英语首见年代）：与 religion 的联系确实存在，但只在词根层面，因为 religio 一般被解释为 re- 加 ligare、取「紧紧绑住」之意，而 ally 与 alliance 则出自 ad- 加 ligare，前缀不同、语义也不同；obligation 与 religion 共享词根，却没有任何义项上的关系。"}]},"similar":{"note":{"en":"Group one holds words from the same binding root, each with a different prefix or ending, so the meanings diverge sharply; group two holds nouns that also put a person under a demand, with a different source for that demand.","cn":"第一组同出「绑」这个词根，但前缀或词尾各不相同，语义因此分得很开；第二组是同样把人置于某种要求之下的名词，只是要求的来源不同。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"oblige","ipa":"/əˈblaɪdʒ/","tag":"same root, verb","definition":"The verb behind the noun: to bind someone by law, by duty or by a favour done, and in polite use simply to do someone a kindness.","definitionCN":"这个名词背后的动词：以法律、义务或恩惠把人绑住；在客套用法中则只表示帮某人一个忙。"},{"word":"obligatory","ipa":"/əˈblɪɡətri/","tag":"same root, adjective","definition":"Made from the noun with the ending -ory, meaning required rather than optional; it describes the requirement, not the person under it.","definitionCN":"由这个名词加表示「具有……性质的」词尾构成，意为强制的而非可选的；它描述要求本身，而不是被要求的人。"},{"word":"ligament","ipa":"/ˈlɪɡəmənt/","tag":"same root, different prefix","definition":"Built on ligare with a different stem: it names the band that binds a joint, and the binding here is physical.","definitionCN":"以 ligare 加另一个词干构成：它指把关节绑住的韧带，这里的捆绑是身体上的。"},{"word":"religion","ipa":"/rɪˈlɪdʒən/","tag":"same root, unrelated sense","definition":"Generally explained as re- plus ligare, 'to bind fast'; it shares the root but has no sense relation to a duty or a debt.","definitionCN":"一般解释为 re- 加 ligare「紧紧绑住」；它与本词共享词根，却与义务、债务没有任何义项关系。"},{"word":"ally","ipa":"/ˈælaɪ/","tag":"same root, another prefix","definition":"From ad- 'to' plus ligare, 'to bind to one side'; it names a partner joined by agreement, and the prefix, not the root, does the work.","definitionCN":"出自 ad-「向」加 ligare「绑到一边」；它指因约定而结合的伙伴，起作用的是前缀而不是词根。"}]},{"heading":"NEAR MEANING","entries":[{"word":"duty","ipa":"/ˈdjuːti/","tag":"what is owed","definition":"What a person owes by law, by office or by conscience; duty is the content, while obligation stresses the tie that holds the person to it.","definitionCN":"一个人依法、依职或依良知所欠之事；义务是内容，而 obligation 强调把人系在这件事上的那根绳子。"},{"word":"commitment","ipa":"/kəˈmɪtmənt/","tag":"freely undertaken","definition":"A promise or engagement a person has taken on, usually by choice; obligation can be imposed without consent.","definitionCN":"一个人通常自愿承担下来的承诺或投入；obligation 则可以在未经同意时被加于身上。"},{"word":"liability","ipa":"/ˌlaɪəˈbɪləti/","tag":"priced exposure","definition":"Legal responsibility for a debt or damage, measured in money; it is the narrow financial end of obligation.","definitionCN":"对债务或损害承担的法律责任，以金钱衡量；它是 obligation 最窄的财务一端。"},{"word":"requirement","ipa":"/rɪˈkwaɪəmənt/","tag":"stated condition","definition":"A condition that must be met, often written into a rule or a contract; it names the condition, not the bond that makes it binding.","definitionCN":"必须满足的条件，常写入规则或合同；它指条件本身，而不是使其具有约束力的那根绳子。"},{"word":"responsibility","ipa":"/rɪˌspɒnsəˈbɪləti/","tag":"accountability","definition":"The state of having to answer for something; it looks at who must explain, while obligation looks at what binds them to act.","definitionCN":"必须为某事作出交代的状态；它着眼的是该由谁解释，而 obligation 着眼的是把人绑向行动的东西。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Latin verb of binding, its prefix, the real family, the real phrases, and the relatives that share the root but carry different prefixes.","cn":"正常联想：真实的拉丁「捆绑」动词、它的前缀、真实的词族、真实的搭配，以及共享词根却带不同前缀的亲戚。"},"normal":[{"en":"Ob- means towards and ligare means to bind, so an obligation is a rope tied towards a task.","cn":"ob- 意为「朝向」，ligare 意为「绑」，所以义务就是一根朝某件事绑过去的绳子。"},{"en":"The family runs oblige, obliged, obliging, obligatory, obligatorily and obligee.","cn":"同族词包括 oblige、obliged、obliging、obligatory、obligatorily 与 obligee。"},{"en":"Fixed phrases show the frames: a legal obligation, under an obligation to, fulfil an obligation, without obligation.","cn":"固定搭配显出常用框架：法律义务、有义务去做、履行义务、不附带义务。"},{"en":"The same root appears with other prefixes: a ligament binds a joint, religion binds fast, and an ally is bound to one side.","cn":"同一个词根配上别的前缀：ligament 绑住关节，religion 取「紧紧绑住」之意，ally 则是被绑到一边的伙伴。"},{"en":"Obligation is what ties a person to act; responsibility is what a person must answer for afterwards.","cn":"obligation 是把人绑向行动的东西，responsibility 则是事后必须为之作答的东西。"}],"abstract":[{"en":"Picture a rope running from a wrist to a sheet of clauses, slack enough to move but never loose enough to slip off.","cn":"想象一根绳子从手腕连到一页条款上，松到可以活动，却绝不会松脱。"},{"en":"Picture a signed card in a coat pocket that grows heavier with every year it is carried.","cn":"想象外套口袋里一张签过字的卡片，带得越久就越沉。"},{"en":"Picture two posts with a rope stretched between them, so that walking past means ducking under it.","cn":"想象两根柱子之间拉着一根绳，走过那里就得低头钻过去。"}]},"examples":[{"en":"Members are under an obligation to declare any outside income.","cn":"成员有义务申报任何外部收入。"},{"en":"He helped her move, and she now feels an obligation to return the favour.","cn":"他帮她搬了家，她现在觉得欠着一份应当回报的人情。"},{"en":"The bond is an obligation enforceable in court.","cn":"这张债券是一项可以在法院强制执行的义务。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「朝向 + 绑」——把你朝某件事绑过去的那根绳子，就是义务；绳子换成钱，就是债务","word":"obligation"},"root":"拉丁 obligare「捆绑、约束」= ob-（朝向、对着）+ ligare「绑」；名词 obligatio 经古法语 obligation 进入英语。同根词有 ligament、ligature、religion（re- 加 ligare，紧紧绑住）、ally 与 alliance（ad- 加 ligare）；前缀不同，语义各异。ligare 的更深来源不确定。","sensesIntro":{"en":"Eight senses follow one rope: conscience ties it, law tightens it, money counts it, gratitude feels it, the noun then names the force itself, lists the duties of a post, records it as a sealed bond, and finally describes the pressure of being pulled from inside.","cn":"八个义项沿着同一根绳子展开：良心先把它系上，法律把它收紧，金钱把它算成数目，感恩从内部感到它；随后名词指这股力量本身、列出职位的职责、把它记成盖章的债券，最后描述被从内部拉扯的压力。"},"semanticMap":{"core":{"en":"CORE IMAGE: a rope from a wrist to a page of clauses, slack enough to move but never loose enough to slip off.","cn":"核心意象：一根从手腕连到条款纸页的绳子，松到可以活动，却绝不会松脱。"},"chain":["TIE THE PERSON","LAW TIGHTENS IT","COUNT IT IN MONEY","OWE A FAVOUR","NAME THE FORCE","FEEL THE PULL"],"branches":[{"senses":"01 · 05","en":"INNER TIE AND ITS FORCE: the duty felt and the binding power that holds a person are one rope seen as content and as strength.","cn":"内在的系与它的力：被感受到的义务与把人固定的力量，是同一根绳子作为内容与作为力度的一面。"},{"senses":"02 · 07","en":"PAPER AND LAW: a statute and a sealed bond are two ways of writing the tie down.","cn":"纸与法：法令与盖章债券，是把这根绳子写下来的两种方式。"},{"senses":"03 · 04","en":"TWO KINDS OF DEBT: money can be counted and repaid, while gratitude cannot.","cn":"两种债：钱可以算清也可以还清，恩情却不行。"},{"senses":"06","en":"THE POST: an office supplies its own list of duties, which other people can inspect.","cn":"职位：一个岗位自带一份职责清单，别人可以逐项核对。"},{"senses":"08","en":"PULLED FROM INSIDE: when the rope is felt rather than owed, the word names compulsion.","cn":"从内部被拉：当绳子是被感受到而不是被欠下时，这个词指的就是被迫。"}]},"affixes":{"intro":{"en":"Obligation reads as a prefix of direction, a root meaning to bind, and a noun ending that names the resulting state or instrument.","cn":"obligation 可以读成表示方向的前缀、意为「绑」的词根，以及指称由此形成的状态或文书的名称词尾。"},"latinIntro":{"en":"The root ligare also gives ligament, ligature, religion, ally and alliance; ob- marks direction towards, while re- and ad- give those other words their different senses.","cn":"词根 ligare 还给出 ligament、ligature、religion、ally 与 alliance；ob- 标出「朝向」，re- 与 ad- 则让其余各词各有不同语义。"},"items":[{"word":"ob-","structure":"ob- (Latin prefix, 'towards, against')","meaning":"towards; against","meaningCN":"朝向；对着","example":"The prefix shows the direction in which the binding is done.","exampleCN":"这个前缀指出捆绑是朝哪个方向做的。"},{"word":"ligare","structure":"ligare (Latin verb, 'to bind, tie')","meaning":"to bind; to tie","meaningCN":"绑；系","example":"The root supplies the physical picture of a rope.","exampleCN":"这个词根提供绳子的具体形象。"},{"word":"obligare","structure":"ob- + ligare","meaning":"to bind towards; to put under a duty","meaningCN":"朝……绑去；使负有义务","example":"The verb turns a literal rope into a duty owed to a person.","exampleCN":"这个动词把字面的绳子变成对某人的义务。"},{"word":"obligatio","structure":"obligare + -tio (action or result)","meaning":"a binding; a bond","meaningCN":"捆绑；约束关系","example":"The Latin noun names both the act and the tie it creates.","exampleCN":"这个拉丁名词既指动作，也指动作造成的束缚。"},{"word":"obligation","structure":"obligatio through Old French","meaning":"a duty; a debt; a bond","meaningCN":"义务；债务；债券","example":"The obligation had outlived the man who signed it.","exampleCN":"这笔债比签字的人活得更久。"},{"word":"obligatory","structure":"obligation + -ory (serving to, required)","meaning":"required rather than optional","meaningCN":"强制的；必须履行的","example":"Attendance at the safety briefing is obligatory.","exampleCN":"参加安全说明会是强制性的。"},{"word":"oblige","structure":"obligare through Old French obliger","meaning":"to bind by duty; to do a kindness","meaningCN":"使负有义务；施恩于","example":"The rules oblige the carrier to inspect every crate.","exampleCN":"规则要求承运方检查每一个板条箱。"},{"word":"obligee","structure":"oblige + -ee (one who receives)","meaning":"the person to whom a bond is owed","meaningCN":"债权人；权利人","example":"The obligee may demand payment on the stated date.","exampleCN":"债权人可以在约定日期要求付款。"}],"latinEntries":[{"word":"ligare","structure":"ligare, ligavi, ligatum (verb, first conjugation)","meaning":"to bind, tie","meaningCN":"绑；系"},{"word":"obligare","structure":"obligare, obligavi, obligatum (verb, first conjugation)","meaning":"to bind, put under obligation","meaningCN":"捆绑；使负有义务"},{"word":"obligatio","structure":"obligatio, obligationis (f., third declension)","meaning":"a binding, obligation, bond","meaningCN":"约束；义务；债券"}],"derivatives":[{"word":"obligatory","pos":"adj.","zh":"强制性的"},{"word":"obligatorily","pos":"adv.","zh":"强制性地"},{"word":"oblige","pos":"v.","zh":"使负有义务"},{"word":"obliged","pos":"adj.","zh":"有义务的；感激的"},{"word":"obliging","pos":"adj.","zh":"乐于助人的"},{"word":"obligee","pos":"n.","zh":"债权人"}]}},{"word":"obligatory","ipa_uk":"/əˈblɪɡətəri/","ipa_us":"/əˈblɪɡətɔːri/","definition_zh":"强制的；义务性的；（法律）规定必须做的；（语法）不可或缺的成分；（仪式）不可省略的；（课程）必修的；（惯例上）必须做的","definition_en":"required by law, rule, office or custom, so that omitting it counts as a breach rather than as a free choice","core_image":"一扇只朝一个方向开的门，门楣上钉着「必须由此入」的木牌，旁边那扇更省事的侧门已经被砖封死","scene":"年会入口处，工作人员把签到簿摊开放在桌上，旁边立着一块写着全体委员必须出席的牌子。The charter makes attendance obligatory for every member of the committee.","sceneCN":"这里 obligatory 指「由明文规则强制、不做即算违规的」（第 1 个义项：规则强制而不可自选）；句意为章程规定委员会每位成员都必须出席。可辨识物件：签到簿、立在入口的牌子、胸牌、会议室门。","pos":[{"tag":"adj.","zh":"强制的；义务性的；必修的"}],"collocations":[{"phrase":"be obligatory for","zh":"对……是必须的"},{"phrase":"make something obligatory","zh":"把某事规定为必须做的"},{"phrase":"obligatory course","zh":"必修课"},{"phrase":"obligatory element","zh":"必有成分"},{"phrase":"legally obligatory","zh":"法律上强制规定的"},{"phrase":"obligatory upon","zh":"对……构成义务的（正式）"}],"forms":[{"label":"原级（形容词）","form":"obligatory"},{"label":"副词","form":"obligatorily"},{"label":"名词（必定义务这一性质）","form":"obligatoriness"},{"label":"名词（义务、责任）","form":"obligation"},{"label":"动词（使承担义务）","form":"obligate"},{"label":"形容词（语言学：义务情态的）","form":"obligative"}],"derivatives":[{"word":"obligatorily","pos":"adv.","zh":"强制性地；作为义务地"},{"word":"obligatoriness","pos":"n.","zh":"强制性；必定义务的性质"},{"word":"obligation","pos":"n.","zh":"义务；责任；约束力"},{"word":"obligate","pos":"v.","zh":"使承担义务；强制"},{"word":"obligative","pos":"adj.","zh":"义务情态的（语法术语）"},{"word":"non-obligatory","pos":"adj.","zh":"非强制的；可做可不做的"}],"senses":[{"no":"01","title":"Enforced by a binding rule","titleCN":"由规则强制、违则受罚","definition":"required by an explicit rule whose breach carries a penalty, so the act is not left to personal preference","definitionCN":"由明文规则要求，违反会带来处罚，因此该行为不由个人喜好决定","example":"The charter makes attendance obligatory for every member of the committee.","exampleCN":"章程规定委员会每位成员都必须出席。","why":"The Latin source means bound, and a rule that binds removes the option of simply not doing the thing.","whyCN":"这个词的拉丁来源意为「被捆绑」，而把人绑住的规则，就取消了「不做」这个选项。"},{"no":"02","title":"Required by statute","titleCN":"法律明文规定的","definition":"imposed by legislation, so that failure to comply is an offence rather than a matter of taste","definitionCN":"由立法施加，不遵守即构成违法，而不是品味问题","example":"Helmets are obligatory for riders under sixteen in this province.","exampleCN":"在本省，十六岁以下的骑行者必须戴头盔。","why":"When a parliament binds everyone at once, the word stops describing a private duty and starts describing a legal floor.","whyCN":"当议会一次性约束所有人，这个词就不再描述私人义务，而开始描述法律底线。"},{"no":"03","title":"Fixed by a professional code","titleCN":"规程与守则规定的","definition":"laid down in a written procedure or code of practice, so that every qualified person must follow the same step","definitionCN":"写进书面规程或执业守则，使每一位合格者都必须走同一步骤","example":"A second signature is obligatory before any sample leaves the freezer.","exampleCN":"任何样本离开冷柜之前，第二个签名是必须的。","why":"Codes of practice borrow the word because a step that may be skipped is not a safeguard at all.","whyCN":"执业守则借用这个词，因为可以被跳过的步骤根本算不上保障。"},{"no":"04","title":"Binding as a moral duty","titleCN":"道义上不容推卸的","definition":"felt or declared to be owed as a duty, even where no penalty is attached and no one can compel it","definitionCN":"被感受或被宣告为应尽之责，即使没有处罚、也无人能够强迫","example":"He regarded a reply to every letter as obligatory, however late it came.","exampleCN":"他认为每封信都该回，无论回得多晚。","why":"The sense of being bound does not need an external enforcer; a duty can bind a person from the inside.","whyCN":"「被绑住」的感觉不必有外在执行者；义务也可以从内部把人绑住。"},{"no":"05","title":"A grammatical element that cannot be dropped","titleCN":"语法上不可缺的成分","definition":"in linguistics, describing a word or category that a construction requires, such as an object with certain verbs","definitionCN":"在语言学中指某一结构必须出现的词或范畴，例如某些动词必须带的宾语","example":"In this dialect the subject pronoun is obligatory even in short answers.","exampleCN":"在这一方言里，即使简短回答也必须带主语代词。","why":"Grammar uses the word for what a sentence cannot do without, which is binding at the level of form.","whyCN":"语法用这个词指句子离不开的成分，这是在形式层面的「捆绑」。"},{"no":"06","title":"A step a rite cannot omit","titleCN":"仪式中不可省的一步","definition":"prescribed by a ceremony or institution as a step without which the act would not count as valid","definitionCN":"由仪式或机构规定，缺少这一步，该行为便不成立","example":"The reading of the names is obligatory at the memorial service.","exampleCN":"追思礼上宣读名字是不可省略的一环。","why":"A rite is a sequence in which each required step carries meaning, so omission is not economy but a broken form.","whyCN":"仪式是一串每一步都有意义的程序，省略不是省事，而是把形式弄坏了。"},{"no":"07","title":"A course one must take","titleCN":"课程表上的必修","definition":"in education, describing a subject that every student in a programme has to complete before graduating","definitionCN":"在教育中指某专业的学生在毕业前都必须完成的科目","example":"Statistics is obligatory for first-year students in every department.","exampleCN":"统计课对每个系的一年级学生都是必修。","why":"Schools bind a whole cohort at once, so the word marks the line between what is required and what is merely offered.","whyCN":"学校一次性约束整届学生，于是这个词标出「必修」与「只是开设」之间的界线。"},{"no":"08","title":"Expected by standing custom","titleCN":"惯例上非做不可的","definition":"required by convention rather than by written rule, so that skipping it draws disapproval instead of a penalty","definitionCN":"由惯例而非成文规则要求，省略会招来非议而不是处罚","example":"A gift for the host is obligatory in that circle, though nobody writes it down.","exampleCN":"在他们那个圈子里，给主人带礼物是必须的，尽管没有人写下来。","why":"Custom binds as tightly as law, and the word covers it because the pressure is felt as a requirement all the same.","whyCN":"惯例绑人的力度不亚于法律，这个词也覆盖它，因为那种压力同样被感受为一项要求。"}],"etymology":{"intro":{"en":"Obligatory comes from Latin obligatorius 'binding, that which binds', a derivative of obligare 'to bind, to put under obligation', which joins ob- 'towards, against' to ligare 'to bind, tie'. The -ory ending marks 'having the nature of'. English took the adjective from Latin legal writing.","cn":"obligatory 来自拉丁 obligatorius「有约束力的、把人绑住的」，由 obligare「捆绑、使承担义务」派生，后者由 ob-「对着、朝向」加 ligare「绑、系」构成。词尾 -ory 表示「具有……性质的」。英语从拉丁法律文献中借入这个形容词。"},"items":[{"era":"LATIN LIGARE","en":"Ligare meant 'to bind, tie, fasten'. It is the root of ligament, of religion and of ally, though each of those reaches it by a different prefix or path, so the family resemblance is real while the words are not interchangeable.","cn":"ligare 意为「绑、系、捆紧」。它是 ligament、religion 与 ally 的词根，但这几个词各自经由不同的前缀或路径抵达它，因此同源属真，词义却不可互换。"},{"era":"LATIN OBLIGARE","en":"Ob- 'towards, against' plus ligare produced obligare, 'to bind someone to something', literally to fasten a person to a duty or a promise.","cn":"ob-「对着、朝向」加 ligare 构成 obligare，意为「把某人绑到某事上」，字面上就是把一个人捆在一项义务或承诺上。"},{"era":"LATIN OBLIGATORIUS","en":"The adjective obligatorius described what has binding force, and Late Latin legal writing used it of promises and duties that the law would enforce.","cn":"形容词 obligatorius 描述具有约束力的东西，晚期拉丁法律文献用它指法律会强制执行的那些承诺与义务。"},{"era":"SUFFIX -ORY","en":"The ending -ory forms adjectives meaning 'having the nature of, serving to', so obligatorius names something that possesses binding force rather than the act of binding.","cn":"词尾 -ory 构成形容词，表示「具有……性质的、用以……的」，因此 obligatorius 指某物带有约束力，而不是指捆绑这个动作。"},{"era":"LATIN INTO ENGLISH","en":"The adjective entered English in legal and ecclesiastical contexts; the school sense of a required course and the grammatical sense are later extensions.","cn":"这个形容词进入英语后最早见于法律与教会语境；学校里的必修义与语法义都是后来的延伸。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin of ligare): the pre-Latin shape of the root is reconstructed rather than recorded, and the exact path by which obligatorius entered English cannot be dated to a single year.","cn":"来源不确定（ligare 的更深来源）：这个词根在拉丁语之前的形式属重构而非有记录的形式；obligatorius 进入英语的确切路径也无法系于某一年份。"}]},"similar":{"note":{"en":"Group one holds words built on the same Latin binding root, and each one must be told apart by its prefix; two of them, religion and ally, look remote from the root but are genuine relatives reached by other prefixes. Group two holds adjectives of requirement that differ in who imposes the demand.","cn":"第一组是同出拉丁「绑」词根的词，须按前缀逐一分辨；其中 religion 与 ally 看上去离词根很远，却确是经其他前缀抵达的同源词。第二组是同样表示「必须」的形容词，区别在于由谁来施加要求。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"oblige","ipa":"/əˈblaɪdʒ/","tag":"same root, verb form","definition":"The verb from the same Latin source: it means to bind someone by a promise or to do them a favour, and the favour sense has drifted far from obligation.","definitionCN":"同出这一拉丁来源的动词：指以承诺约束某人，或帮某人一个忙，而「帮忙」这一义已离义务很远。"},{"word":"obligation","ipa":"/ˌɒblɪˈɡeɪʃn/","tag":"same root, noun","definition":"The noun names the tie itself, whether legal, financial or moral; obligatory describes whatever imposes such a tie.","definitionCN":"这个名词指约束本身，无论法律的、金钱的还是道义的；obligatory 则形容施加这种约束的事物。"},{"word":"ligament","ipa":"/ˈlɪɡəmənt/","tag":"same root, no prefix","definition":"From ligare with a noun ending, naming the tissue that binds bones together; it keeps the physical sense of tying with no prefix added.","definitionCN":"由 ligare 加名词词尾构成，指把骨头绑在一起的韧带；它保留了「系」的本义，且未加前缀。"},{"word":"religion","ipa":"/rɪˈlɪdʒən/","tag":"same root, different prefix","definition":"Usually traced to re- 'back, again' plus ligare, a binding back; the prefix and the sense of a bond to the divine are wholly different from ob-.","definitionCN":"通常追溯到 re-「回、再」加 ligare，意为「绑回去」；其前缀与「与神相连」之义都和 ob- 完全不同。"},{"word":"ally","ipa":"/əˈlaɪ/","tag":"same root, different prefix","definition":"From ad- 'to' plus ligare, to bind to oneself; it names a partner bound by agreement, not a duty imposed on a person.","definitionCN":"由 ad-「向」加 ligare 构成，意为「绑到自己这边」；它指以协定绑定的伙伴，而不是加于人的义务。"}]},{"heading":"NEAR MEANING","entries":[{"word":"compulsory","ipa":"/kəmˈpʌlsəri/","tag":"enforced by power","definition":"Required and backed by compulsion, often with a penalty; it stresses the force applied, where obligatory stresses the binding nature of the requirement.","definitionCN":"被要求且有强制力支撑，常附带处罚；它强调施加的力量，而 obligatory 强调要求本身的约束性质。"},{"word":"mandatory","ipa":"/ˈmændətəri/","tag":"ordered by authority","definition":"Required by an authority's order, typically in law or official regulation; it is the closest neighbour but narrower in register.","definitionCN":"由权威命令要求，多见于法律或官方规章；它是最接近的近义词，但语域更窄。"},{"word":"binding","ipa":"/ˈbaɪndɪŋ/","tag":"creates a legal tie","definition":"Describing an agreement or promise that legally holds the parties; it speaks of the tie created, not of a step everyone must perform.","definitionCN":"形容在法律上约束各方的协议或承诺；它说的是所产生的约束关系，而不是人人必须执行的一步。"},{"word":"requisite","ipa":"/ˈrekwɪzɪt/","tag":"needed for a purpose","definition":"Necessary for a particular end, often of qualifications or supplies; necessity here serves a goal, not a rule.","definitionCN":"为某一目的所必需，多指资格或用品；这里的必要是服务于目标，而不是服从规则。"},{"word":"imperative","ipa":"/ɪmˈperətɪv/","tag":"urgently necessary","definition":"Urgent and impossible to postpone; it describes practical urgency, while obligatory describes a formal requirement that may be resented.","definitionCN":"紧急而无法推迟；它描述实务上的迫切，而 obligatory 描述可能招人反感的正式要求。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Latin morphemes, the genuine relatives reached by other prefixes, the real phrases, and the school and grammar uses that grew out of the legal core.","cn":"正常联想：真实的拉丁语素、经其他前缀抵达的真正同源词、真实的固定搭配，以及从法律核心生长出来的学校义与语法义。"},"normal":[{"en":"The root means to bind and the prefix means towards, so obligatory describes something that has been fastened onto a person as a duty.","cn":"词根意为「绑」，前缀意为「朝向」，所以 obligatory 描述被当作义务捆到一个人身上的东西。"},{"en":"The -ory ending means having the nature of, so the adjective names a quality of binding rather than the act of binding.","cn":"词尾 -ory 意为「具有……性质的」，因此这个形容词指「有约束力」这一性质，而不是捆绑的动作。"},{"en":"The family runs oblige, obligation, obligatorily, obligatoriness, obligate and obligative.","cn":"同族词包括 oblige、obligation、obligatorily、obligatoriness、obligate 与 obligative。"},{"en":"Fixed phrases mark the frame: obligatory for, make something obligatory, obligatory course, obligatory element.","cn":"固定搭配标出框架：对……是必须的、把某事规定为必须、必修课、必有成分。"},{"en":"Ligament, religion and ally all reach the same binding root by other prefixes, so they resemble this family without sharing its prefix or its sense.","cn":"ligament、religion 与 ally 都经其他前缀抵达同一个「绑」词根，因此它们像这一词族，却不共享其前缀与词义。"}],"abstract":[{"en":"Picture a door with only one handle, on the outside, so it can be opened for you but not by you.","cn":"想象一扇只有外侧把手的门，别人能为你打开，你自己却打不开。"},{"en":"Picture a signature line that is already printed, with no blank space beside it for a refusal.","cn":"想象一条已经印好的签名线，旁边没有留给出「不」的空白。"},{"en":"Picture a rope tied from a duty to a wrist, long enough to work with and too short to walk away.","cn":"想象一根绳把一项义务系在手腕上，长度够干活，却不够走开。"}]},"examples":[{"en":"Reporting every accident is obligatory under the new safety code.","cn":"根据新的安全规程，每起事故都必须上报。"},{"en":"For most visitors a guided tour is optional, but for school groups it is obligatory.","cn":"对多数参观者而言导览是可选项目，但对学校团体则是必须的。"},{"en":"The grammar marks an obligatory object on every transitive verb in the list.","cn":"这份清单把每个及物动词的必有宾语都标了出来。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「对着 + 绑」——规则把人绑住不许松手，就是强制；被绑上的那件事，就是义务","word":"obligatory"},"root":"拉丁 obligatorius「有约束力的」← obligare「捆绑」= ob-（对着、朝向）+ ligare「绑、系」；词尾 -ory 表示「具有……性质的」。同根的 ligament 无前缀，religion 走 re-，ally 走 ad-，前缀不同故词义不同；ligare 的更深来源不确定。","sensesIntro":{"en":"Eight senses follow one movement: something is tied to a person and cannot be dropped. The tie may be a rule with a penalty, a statute, a professional code, an inner duty, a slot a sentence requires, a step a rite requires, a course a degree requires, or a custom no one has written down.","cn":"八个义项沿同一个动作展开：有件事被绑在一个人身上，放不下。这条绑绳可以是带处罚的规则、成文法律、执业规程、内心义务、句子必需的成分、仪式必需的一步、学位必需的课程，或无人写下却人人遵守的惯例。"},"semanticMap":{"core":{"en":"CORE IMAGE: a duty fastened to a person like a rope that cannot be untied.","cn":"核心意象：一项义务像解不开的绳子一样系在人身上。"},"chain":["TIE THE PERSON","RULE WITH A PENALTY","WRITE IT INTO LAW","FIX IT IN A CODE","FEEL THE INNER DUTY","REQUIRE THE SLOT"],"branches":[{"senses":"01 · 02","en":"ENFORCED FROM OUTSIDE: a rule and a statute both bind with a penalty behind them.","cn":"外力执行：规则与法律都在背后带着处罚把人绑住。"},{"senses":"03 · 04","en":"WRITTEN AND FELT: the same tie appears in a professional code and in a duty no one can enforce.","cn":"写下的与感到的：同一条绑绳，既出现在执业规程里，也出现在无人能执行的义务里。"},{"senses":"05","en":"THE SLOT A SENTENCE NEEDS: grammar binds form, where omission makes the sentence simply wrong.","cn":"句子必需的槽位：语法绑住形式，省略之后句子就直接错了。"},{"senses":"06 · 07","en":"RITE AND CURRICULUM: a ceremony and a degree each name steps that cannot be skipped.","cn":"仪式与课程：典礼与学位都点出不可跳过的那几步。"},{"senses":"08","en":"UNWRITTEN PRESSURE: custom binds without a penalty, and disapproval does the work of enforcement.","cn":"不成文的压力：惯例没有处罚也照样绑人，非议承担了执行的角色。"}]},"affixes":{"intro":{"en":"Obligatory is a Latin adjective built from a prefix, a verb root and an adjective ending, and all three parts recur in English legal and everyday vocabulary.","cn":"obligatory 是一个拉丁形容词，由前缀、动词词根与形容词词尾构成，这三部分都在英语的法律与日常词汇中反复出现。"},"latinIntro":{"en":"Latin ligare supplies the binding, ob- supplies the direction towards a person, and -ory turns the act into a quality; obligare and obligatio are the verb and noun behind the adjective.","cn":"拉丁 ligare 提供「绑」，ob- 提供「朝某人而去」的方向，-ory 把动作变成性质；obligare 与 obligatio 是这个形容词背后的动词与名词。"},"items":[{"word":"ob-","structure":"ob- (Latin prefix, 'towards, against, before')","meaning":"towards; against","meaningCN":"朝向；对着","example":"The prefix shows that the binding is aimed at a particular person.","exampleCN":"这个前缀表明，这种捆绑是针对某一个具体的人的。"},{"word":"ligare","structure":"ligare (Latin verb, 'to bind, tie')","meaning":"to bind; to tie","meaningCN":"绑；系","example":"The root supplies the rope in the image behind the word.","exampleCN":"这个词根提供了这个词背后图景中的那根绳子。"},{"word":"obligare","structure":"ob- + ligare","meaning":"to bind someone to something","meaningCN":"把某人绑到某事上；使承担义务","example":"The verb names the act of fastening a duty to a person.","exampleCN":"这个动词指把一项义务系到一个人身上的动作。"},{"word":"obligatorius","structure":"obligare + -orius (having the nature of)","meaning":"having binding force","meaningCN":"具有约束力的","example":"Roman lawyers used the adjective of promises the courts would enforce.","exampleCN":"罗马法学家用这个形容词指法院会强制执行的承诺。"},{"word":"obligatory","structure":"obligatorius through French","meaning":"required; binding","meaningCN":"强制的；有约束力的","example":"The charter makes attendance obligatory for every member.","exampleCN":"章程规定每位成员都必须出席。"},{"word":"obligation","structure":"obligare + -io (noun of action)","meaning":"a duty or tie","meaningCN":"义务；约束关系","example":"The lease creates an obligation to repair the roof.","exampleCN":"这份租约产生了一项修缮屋顶的义务。"},{"word":"obligatorily","structure":"obligatory + -ly (in that manner)","meaning":"in a binding manner","meaningCN":"强制性地","example":"The form is obligatorily filed within seven days.","exampleCN":"这张表格必须在七天内提交。"},{"word":"obligatoriness","structure":"obligatory + -ness (state)","meaning":"the state of being required","meaningCN":"强制性这一性质","example":"The obligatoriness of the step is what makes the safeguard work.","exampleCN":"正是这一步的强制性，才让这项保障真正生效。"}],"latinEntries":[{"word":"ligare","structure":"ligare, ligavi, ligatum (verb, first conjugation)","meaning":"to bind, tie, fasten","meaningCN":"绑；系；捆紧"},{"word":"obligare","structure":"obligare, obligavi, obligatum (verb, first conjugation)","meaning":"to bind, put under obligation","meaningCN":"捆绑；使承担义务"},{"word":"obligatio","structure":"obligatio, obligationis (f., third declension)","meaning":"a binding; a legal obligation","meaningCN":"约束；法律上的义务"}],"derivatives":[{"word":"obligatorily","pos":"adv.","zh":"强制性地"},{"word":"obligatoriness","pos":"n.","zh":"强制性"},{"word":"obligation","pos":"n.","zh":"义务；责任"},{"word":"obligate","pos":"v.","zh":"使承担义务"},{"word":"obligative","pos":"adj.","zh":"义务情态的"}]}},{"word":"expected","ipa_uk":"/ɪkˈspektɪd/","ipa_us":"/ɪkˈspektɪd/","definition_zh":"预料之中的；（人、车、货）预期到达的；按理应当的；符合预期的；（数学）期望的；（分娩）预产期将至的；预计的（收入、结果）；（角色）被指望接任的","definition_en":"regarded as likely to happen or to arrive, and therefore counted on in advance","core_image":"站台上的人反复看表，又抬头望向隧道口，眼睛盯着那列还没出现的车，仿佛已经先看见了它","scene":"果园边的空地上，农户把防霜布一层层铺开，说今年大概又要提前降温。The first frost came later than anyone had expected.","sceneCN":"这里 expected 指「事先认定会发生、因而据此等待的」（第 1 个义项：预料之中会发生）；句意为初霜来得比任何人预料的都晚。可辨识物件：防霜布、果树、百叶箱、结霜的草叶。","pos":[{"tag":"adj.","zh":"预料之中的；预期到达的；按理应当的"},{"tag":"v.","zh":"expect 的过去式与过去分词"}],"collocations":[{"phrase":"as expected","zh":"正如预料"},{"phrase":"than expected","zh":"比预想的……"},{"phrase":"be expected to do","zh":"预计会做；按理应当做"},{"phrase":"expected value","zh":"期望值"},{"phrase":"expected date of delivery","zh":"预产期"},{"phrase":"meet expectations","zh":"达到预期"}],"forms":[{"label":"原形动词","form":"expect"},{"label":"第三人称单数","form":"expects"},{"label":"过去式","form":"expected"},{"label":"过去分词","form":"expected"},{"label":"现在分词","form":"expecting"},{"label":"名词（预期、期望）","form":"expectation"},{"label":"名词复数","form":"expectations"},{"label":"副词（如所预期地）","form":"expectedly"}],"derivatives":[{"word":"expectation","pos":"n.","zh":"预期；期望；期待"},{"word":"expect","pos":"v.","zh":"预料；期待；要求"},{"word":"expectedly","pos":"adv.","zh":"如所预期地"},{"word":"expectancy","pos":"n.","zh":"期待；预期（尤指期待中的状态）"},{"word":"unexpected","pos":"adj.","zh":"出乎意料的"}],"senses":[{"no":"01","title":"Regarded as likely to happen","titleCN":"预料之中会发生","definition":"believed in advance to be likely, so that people plan and prepare on the strength of that belief","definitionCN":"事先相信某事很可能发生，人们据此安排与准备","example":"The first frost came later than anyone had expected.","exampleCN":"初霜来得比任何人预料的都晚。","why":"The Latin verb behind the word means to look out for something, so what is expected is what one has been watching the horizon for.","whyCN":"这个词背后的拉丁动词意为「向外张望某物」，所以被预料的事，就是一直盯着地平线在等的那件事。"},{"no":"02","title":"Due to arrive at a known time","titleCN":"预期到达","definition":"described of a person, train, parcel or message that is scheduled or reckoned to arrive at a particular time","definitionCN":"形容人、列车、包裹或消息按时刻或估算应于某时到达","example":"The morning train is expected at platform four within ten minutes.","exampleCN":"早班列车预计十分钟内到达四号站台。","why":"Travel and trade needed a word for the thing already on its way, and the looking-out sense turned into a timetable sense.","whyCN":"出行与贸易需要一个词来指已经在路上的东西，于是「向外张望」义就变成了时刻表义。"},{"no":"03","title":"Supposed to, by rule or duty","titleCN":"按理应当","definition":"required or obliged by rule, role or politeness, so that not doing it is a fault rather than a surprise","definitionCN":"因规则、角色或礼节而应当做，不做即为过失，而不只是令人意外","example":"Visitors are expected to sign in at the front desk before entering.","exampleCN":"来访者进入前应当在前台登记。","why":"Once people reliably look for a behaviour, its absence becomes a breach, and expectation turns into obligation.","whyCN":"一旦人们稳定地期待某种行为，它的缺席就成了失礼，期待也就变成了义务。"},{"no":"04","title":"Matching what was forecast","titleCN":"符合预期","definition":"described of a result or figure that lands where the forecast said it would, neither above nor below","definitionCN":"形容结果或数字正落在预测的位置，不高也不低","example":"Sales were as expected, so the board kept the original plan.","exampleCN":"销售正如预期，因此董事会维持原计划。","why":"This sense compares two things at once: the forecast in the mind and the number in the report.","whyCN":"这个义项同时比较两样东西：心里的预测，与报告里的那个数字。"},{"no":"05","title":"The average outcome of a random trial","titleCN":"随机试验的期望值","definition":"in probability, the long-run average value of a variable, obtained by weighting each outcome by its chance","definitionCN":"在概率论中，指变量在大量重复试验下的平均值，按各结果发生的概率加权","example":"The expected number of defective parts per batch is two.","exampleCN":"每批零件中不合格件数的期望值是两个。","why":"Mathematics kept the forecast image but made it exact: what one expects over many trials is the weighted mean.","whyCN":"数学保留了这个「预先估计」的图景，却把它精确化：在大量试验里所预期的，就是加权平均。"},{"no":"06","title":"The date a baby is due","titleCN":"预产期","definition":"the estimated date on which a birth is calculated to occur, used in medicine for planning care","definitionCN":"按估算算出的分娩日期，医学上用于安排照护","example":"Her expected date of delivery falls in the first week of March.","exampleCN":"她的预产期在三月的第一周。","why":"Medicine borrowed the word because a due date is a forecast that a whole ward plans around.","whyCN":"医学借用这个词，因为预产期是整个病区都要据此安排的一个预测。"},{"no":"07","title":"Estimated income or result","titleCN":"预计的收入或结果","definition":"in finance and planning, describing earnings, costs or returns worked out in advance from current evidence","definitionCN":"在金融与规划中指依据现有证据事先算出的收益、成本或回报","example":"Expected revenue for the quarter was revised upward after the contract.","exampleCN":"合同签订后，本季的预计收入被上调。","why":"Budgets run on numbers that do not exist yet, and the word marks them as estimates rather than records.","whyCN":"预算靠的是尚不存在的数字，这个词把这些数字标为估算，而非既成记录。"},{"no":"08","title":"The role one is counted on to take","titleCN":"被指望接任的角色","definition":"described of a person marked out by others to succeed, inherit or represent them, whether or not they agree","definitionCN":"形容被他人指定去接任、继承或代表的人，无论本人是否同意","example":"He was the expected successor, and the whole office knew it before he did.","exampleCN":"他是众望所归的继任者，全办公室都比他自己更早知道。","why":"The word can shift from an event to a person: the one everyone looks towards is the one expected to step in.","whyCN":"这个词可以从事件转到人身上：所有人都在望向的那个人，就是被指望接手的那个。"}],"etymology":{"intro":{"en":"Expected is the past participle of expect, from Latin exspectare 'to look out for, await', which joins ex- 'out' to spectare 'to look at'. Spectare is itself a frequentative of specere 'to see', so the whole word pictures someone watching outward for what is coming.","cn":"expected 是 expect 的过去分词，源自拉丁 exspectare「向外张望、等待」，由 ex-「向外」加 spectare「看」构成。spectare 又是 specere「看见」的反复形式，因此整个词构出的图景是一个人朝外盯着即将到来的东西。"},"items":[{"era":"LATIN SPECERE","en":"Specere meant 'to see, look'. It supplies the looking in aspect, where ad- means towards, in inspect, where in- means into, in respect, where re- means back, and in suspect, where sub- means from below; spectacle and species take noun endings instead. Each word differs in prefix and in sense, so they are relatives and not synonyms.","cn":"specere 意为「看见、看」。aspect 用 ad-「朝向」，inspect 用 in-「向内」，respect 用 re-「回」，suspect 用 sub-「从下」；spectacle 与 species 则改用名词词尾。每个词的前缀与词义都不同，因此它们是同源词而非同义词。"},{"era":"LATIN SPECTARE","en":"Spectare was the frequentative of specere, meaning to look at again and again, to watch; the ending adds repeated or sustained action rather than a single glance.","cn":"spectare 是 specere 的反复形式，意为「一再地看、观看」；这个词尾添加的是反复或持续的动作，而不是看一眼。"},{"era":"LATIN EXSPECTARE","en":"Ex- 'out' plus spectare gave exspectare, to look out for, to watch for someone's coming, and so to await or anticipate.","cn":"ex-「向外」加 spectare 构成 exspectare，意为「向外张望、留意某人的到来」，由此引申为等待与预料。"},{"era":"LATIN EXSPECTATUS","en":"Its past participle exspectatus meant awaited or looked-for; that participle is the shape English later borrowed and turned into a standalone adjective.","cn":"它的过去分词意为「被等待的、被盼望的」；英语后来借入的正是这个分词形式，并把它变成独立的形容词。"},{"era":"ENGLISH 16TH CENTURY","en":"English used the participle inside the verb phrase first, then allowed it to stand before a noun as an adjective; the probability sense of expected value is a much later technical coinage.","cn":"英语最早把这个分词用在动词短语里，后来才允许它直接放在名词前作形容词；期望值这一概率义则是晚得多的技术性用法。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin): the pre-Latin shape of specere is a reconstruction, not a recorded form, and the first use of the participle as an attributive adjective cannot be dated to a single year.","cn":"来源不确定（更深词源）：specere 在拉丁语之前的形式属重构而非有记录的形式；这个分词首次用作定语形容词的年代也无法确定到某一年。"}]},"similar":{"note":{"en":"Group one holds words that all descend from the Latin verb for seeing, and every one of them must be told apart by its prefix; none is a false friend, but none can replace another. Group two holds words of foreknowledge that differ in whether they are based on evidence, schedule, duty or mere likelihood.","cn":"第一组都出自拉丁语中表示「看」的动词，每一个都要按前缀分辨；它们没有假同源词，但也都不能互相替换。第二组是表示「预先知道」的词，区别在于依据的是证据、时刻表、义务，还是仅仅可能。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"expect","ipa":"/ɪkˈspekt/","tag":"same root, verb","definition":"The verb from which the participle comes: to look out for something and so to think it likely; the adjective describes the result of that looking.","definitionCN":"这个分词所来自的动词：向外留意某事，因而认为它很可能；形容词描述的就是这番留意之后的状态。"},{"word":"expectation","ipa":"/ˌekspekˈteɪʃn/","tag":"same root, noun","definition":"The noun names the mental picture of what is coming, or the standard others hold you to; expected describes the thing that matches such a picture.","definitionCN":"这个名词指心中对将来之事的图景，或他人对你的标准；expected 则形容符合这幅图景的事物。"},{"word":"expectant","ipa":"/ɪkˈspektənt/","tag":"same root, active form","definition":"Describing the person who is waiting, often with hope, as in an expectant mother; it points at the watcher, not at the event.","definitionCN":"形容正在等待、常带盼望的人，如待产的孕妇；它指向的是等待者，而不是那个事件。"},{"word":"unexpected","ipa":"/ˌʌnɪkˈspektɪd/","tag":"same root, negated","definition":"The direct negation: what was not looked for and therefore has no plan attached to it.","definitionCN":"直接否定形式：指未曾被留意、因而也没有任何预案的东西。"},{"word":"inspect","ipa":"/ɪnˈspekt/","tag":"same root, different prefix","definition":"In- 'into' plus the seeing root: to look closely into something in order to judge it; the prefix turns outward waiting into inward examination.","definitionCN":"in-「向内」加「看」的词根：为了评判而仔细查看某物；这个前缀把向外的等待变成向内的检查。"},{"word":"spectacle","ipa":"/ˈspektəkl/","tag":"same root, noun of sight","definition":"From the same looking root, naming something put before the eyes; it needs no expectation and no future.","definitionCN":"同出这个「看」的词根，指摆在眼前供人观看之物；它既不需要预期，也不指向未来。"}]},{"heading":"NEAR MEANING","entries":[{"word":"anticipated","ipa":"/ˈæntɪsɪpeɪtɪd/","tag":"looked forward with action","definition":"Expected and usually acted upon in advance, as when supplies are ordered before the rush; it implies preparation, where expected may be passive.","definitionCN":"不仅预料，而且通常提前采取行动，如在高峰前订好货；它含准备之意，而 expected 可以只是被动地等着。"},{"word":"predicted","ipa":"/prɪˈdɪktɪd/","tag":"foretold from a model","definition":"Stated in advance on the strength of data, a model or a pattern; it claims a method behind the forecast, which expected does not.","definitionCN":"依据数据、模型或规律事先说出；它声称预测背后有方法，而 expected 不作此声称。"},{"word":"due","ipa":"/djuː/","tag":"owed at a fixed time","definition":"Owed or scheduled to happen at a set time, as a train or a payment; it fixes the time, while expected only fixes the likelihood.","definitionCN":"应在某一固定时刻发生或应付，如列车或款项；它锁定时间，而 expected 只锁定可能性。"},{"word":"supposed","ipa":"/səˈpəʊzd/","tag":"required by duty or rumour","definition":"Required by duty or accepted as true on hearsay; it carries a hint of doubt or reproach that expected usually lacks.","definitionCN":"因义务而应当，或因传闻而被认为如此；它带一点怀疑或责备，而 expected 通常没有这层意味。"},{"word":"prospective","ipa":"/prəˈspektɪv/","tag":"looking forward to a future role","definition":"Describing someone or something likely to become relevant in the future, as a prospective buyer; it points at a future state, not at a forecast.","definitionCN":"形容将来可能变得相关的人或物，如意向买家；它指向未来的状态，而不是一份预测。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Latin pieces, the real family of seeing words with their different prefixes, the real phrases, and the technical uses in probability and medicine.","cn":"正常联想：真实的拉丁语素、真实的「看」词族及其不同前缀、真实的固定搭配，以及概率与医学中的专业用法。"},"normal":[{"en":"The prefix means out and the root means look, so to expect is to keep looking out for what is coming.","cn":"前缀意为「向外」，词根意为「看」，所以预料就是一直朝外盯着将要到来的东西。"},{"en":"The root of seeing also gives aspect, inspect, respect, suspect, spectacle and species, each with a different prefix or ending.","cn":"这个「看」的词根还生出 aspect、inspect、respect、suspect、spectacle 与 species，各自带不同的前缀或词尾。"},{"en":"The participle became an adjective: expected arrival, expected result, expected value, expected date of delivery.","cn":"这个分词变成了形容词：预期到达、预期结果、期望值、预产期。"},{"en":"The family runs expect, expects, expecting, expectation, expectations, expectancy and unexpected.","cn":"同族词包括 expect、expects、expecting、expectation、expectations、expectancy 与 unexpected。"},{"en":"Fixed phrases mark the frame: as expected, than expected, be expected to, meet expectations.","cn":"固定搭配标出框架：正如预料、比预想的、预计会、达到预期。"}],"abstract":[{"en":"Picture a hand cupped above the eyes, shading them, though there is nothing on the road yet.","cn":"想象一只手搭在眼睛上方遮光，尽管路上还什么都没有。"},{"en":"Picture a chair already pulled out at a table for a guest who has not rung the bell.","cn":"想象餐桌旁已经为一位还没按门铃的客人拉出了一把椅子。"},{"en":"Picture a row of identical envelopes, and the one on top already opened.","cn":"想象一排一模一样的信封，最上面那封已经被拆开了。"}]},"examples":[{"en":"The storm was expected to reach the coast before dawn, so the ferries stopped running.","cn":"预计风暴会在天亮前抵达海岸，因此渡轮停航了。"},{"en":"Her results were better than expected, which changed the whole timetable.","cn":"她的成绩比预期好，这改变了整个时间安排。"},{"en":"In a fair die the expected value of a single roll is three and a half.","cn":"在公平的骰子上，单次投掷的期望值是三点五。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「向外 + 看」——一直朝外张望，就是在等那件认定会发生的事，也就是预料","word":"expected"},"root":"拉丁 exspectare「向外张望、等待」= ex-（向外）+ spectare「看」（specere「看见」的反复形式）；expected 是 expect 的过去分词作形容词。同根的 aspect、inspect、respect、suspect、spectacle、species 均出 specere，但前缀与语义不同；specere 的更深来源不确定。","sensesIntro":{"en":"Eight senses follow one movement: someone looks outward for what is coming. The looking may settle on an event, on an arrival, on a duty, on a forecast that comes true, on an average across many trials, on a birth date, on projected income, or on the person marked to take over.","cn":"八个义项沿同一个动作展开：一个人朝外张望将要到来的东西。这番张望可以落在一件事、一次到达、一项应尽之责、一个应验的预测、大量试验的平均值、一个分娩日期、一笔预计收入，或那个被指定接手的人身上。"},"semanticMap":{"core":{"en":"CORE IMAGE: eyes fixed on the road, waiting for something already believed to be on its way.","cn":"核心意象：眼睛盯着路，等一件已经相信正在路上的东西。"},"chain":["LOOK OUTWARD","WATCH THE ROAD","COUNT ON ARRIVAL","DEMAND THE STEP","HIT THE FORECAST","AVERAGE THE TRIALS"],"branches":[{"senses":"01 · 02","en":"WAITING AND ARRIVING: the same outward look covers a likely event and a vehicle already on its way.","cn":"等待与到达：同一次向外张望，既覆盖很可能发生的事，也覆盖已经在路上的车。"},{"senses":"03 · 04","en":"DUTY AND SCORE: expectation hardens into a required step, and softens into a number that merely matches the forecast.","cn":"义务与分数：期待硬化成必须执行的一步，也软化成仅仅吻合预测的数字。"},{"senses":"05","en":"THE LONG RUN: probability keeps the forecast image but makes it a weighted average over many trials.","cn":"长期重复：概率论保留预测的图景，却把它变成大量试验的加权平均。"},{"senses":"06","en":"THE DUE DATE: medicine turns the forecast into a date a whole ward plans around.","cn":"预产日期：医学把预测变成一个整个病区都要据此安排的日期。"},{"senses":"07 · 08","en":"PROJECTED AND ASSIGNED: what is expected can be a figure in a budget or a person marked for a role.","cn":"预计与被指定：被预期的可以是一份预算里的数字，也可以是一个被指定角色的人。"}]},"affixes":{"intro":{"en":"Expected is a Latin participle used as an English adjective; its prefix, its seeing root and its adjective ending all recur across a large family of English words.","cn":"expected 是一个用作英语形容词的拉丁分词；它的前缀、表示「看」的词根与形容词词尾，都在英语的一大词族中反复出现。"},"latinIntro":{"en":"Latin specere gives the act of seeing, spectare gives sustained watching, ex- sends the gaze outward, and the participle ending -tus makes the result into a description.","cn":"拉丁 specere 提供「看见」的动作，spectare 提供持续的观看，ex- 把目光送向外面，分词词尾 -tus 则把结果变成一种描述。"},"items":[{"word":"ex-","structure":"ex- (Latin prefix, 'out, out of')","meaning":"out; outward","meaningCN":"向外；出自","example":"The prefix sends the gaze away from the watcher and towards the horizon.","exampleCN":"这个前缀把目光从观看者身上送开，投向地平线。"},{"word":"specere","structure":"specere (Latin verb, 'to see, look')","meaning":"to see; to look","meaningCN":"看见；看","example":"The root supplies the eye in the image behind the word.","exampleCN":"这个词根提供了这个词背后图景中的那只眼睛。"},{"word":"spectare","structure":"specere + frequentative ending","meaning":"to watch, look at repeatedly","meaningCN":"观看；一再地看","example":"The frequentative form turns a glance into sustained watching.","exampleCN":"这个反复形式把一眼变成持续的观看。"},{"word":"exspectare","structure":"ex- + spectare","meaning":"to look out for; to await","meaningCN":"向外张望；等待","example":"The verb names the act of watching the road for someone.","exampleCN":"这个动词指守着路等某人的动作。"},{"word":"expected","structure":"exspectatus (past participle) used as adjective","meaning":"looked for; regarded as coming","meaningCN":"被等待的；被认为会来的","example":"The first frost came later than anyone had expected.","exampleCN":"初霜来得比任何人预料的都晚。"},{"word":"expectation","structure":"exspectare + -io (noun of action)","meaning":"the act or state of awaiting","meaningCN":"期待；预期","example":"The results exceeded every expectation.","exampleCN":"结果超出了所有人的预期。"},{"word":"expectant","structure":"exspectare + -ant (present participle ending)","meaning":"waiting; full of expectation","meaningCN":"等待着的；满怀期待的","example":"An expectant crowd gathered at the gate.","exampleCN":"一群满怀期待的人聚集在门口。"},{"word":"unexpected","structure":"un- (not) + expected","meaning":"not looked for","meaningCN":"未曾预料的","example":"An unexpected delay ruined the schedule.","exampleCN":"一次意外的延误毁了整个日程。"}],"latinEntries":[{"word":"specere","structure":"specere, spexi, spectum (verb, third conjugation)","meaning":"to see, look","meaningCN":"看见；看"},{"word":"spectare","structure":"spectare, spectavi, spectatum (verb, first conjugation, frequentative)","meaning":"to watch, look at","meaningCN":"观看；注视"},{"word":"exspectare","structure":"exspectare, exspectavi, exspectatum (verb, first conjugation)","meaning":"to look out for, await","meaningCN":"向外张望；等待"}],"derivatives":[{"word":"expectation","pos":"n.","zh":"预期；期望"},{"word":"expect","pos":"v.","zh":"预料；期待"},{"word":"expectedly","pos":"adv.","zh":"如所预期地"},{"word":"expectancy","pos":"n.","zh":"期待；预期状态"},{"word":"unexpected","pos":"adj.","zh":"出乎意料的"}]}},{"word":"reciprocity","ipa_uk":"/ˌresɪˈprɒsəti/","ipa_us":"/ˌresɪˈprɑːsəti/","definition_zh":"互惠；对等回应；国际间的对等；（社会）互惠规范；（数学）互易性；（法律）互惠待遇；情感上的对等；经济上的等价回报","definition_en":"the practice of giving back to another what has been given, or of answering an act with a matching act","core_image":"两只手隔着桌子同时推过去一样分量的东西，谁也没有多拿，谁也没有先松手","scene":"边境口岸的谈判室里，两边代表把各自的关税清单推到桌子中央，谁也不肯先签字。The treaty rests on reciprocity: each country lowers its tariff only if the other does the same.","sceneCN":"这里 reciprocity 指「你给什么、我也回什么的对等交换」（第 6 个义项：法律上的互惠待遇）；句意为条约以互惠为基础，一方降税以另一方同样降税为条件。可辨识物件：谈判长桌、两份关税清单、桌中央的文件夹、尚未落笔的签字页。","pos":[{"tag":"n.","zh":"互惠；对等；互易性（不可数，复数指多组对等关系）"}],"collocations":[{"phrase":"on the basis of reciprocity","zh":"在互惠的基础上"},{"phrase":"the principle of reciprocity","zh":"互惠原则"},{"phrase":"expect reciprocity","zh":"期待对等回报"},{"phrase":"reciprocity between","zh":"……之间的互惠关系"},{"phrase":"social reciprocity","zh":"社会互惠"},{"phrase":"lack of reciprocity","zh":"缺乏互惠"}],"forms":[{"label":"复数（多组对等关系）","form":"reciprocities"},{"label":"形容词（互惠的、对等的）","form":"reciprocal"},{"label":"副词（对等地）","form":"reciprocally"},{"label":"动词（回报、往复）","form":"reciprocate"},{"label":"名词（回报这一动作）","form":"reciprocation"},{"label":"形容词（倾向于回报的，少见）","form":"reciprocative"}],"derivatives":[{"word":"reciprocal","pos":"adj./n.","zh":"互惠的；对等的；（数学）倒数"},{"word":"reciprocally","pos":"adv.","zh":"对等地；相互地"},{"word":"reciprocate","pos":"v.","zh":"回报；往复运动"},{"word":"reciprocation","pos":"n.","zh":"回报；往复"},{"word":"reciprocative","pos":"adj.","zh":"有回报倾向的（少见）"}],"senses":[{"no":"01","title":"Giving back what was given","titleCN":"有来有往的互惠","definition":"the general pattern in which a gift, favour or concession is answered with something of similar worth","definitionCN":"泛指一方给出礼物、帮助或让步之后，另一方以价值相近之物回应的模式","example":"Long-distance trade among the villages depended on reciprocity rather than on money.","exampleCN":"这些村落之间的远途贸易靠的是互惠，而不是货币。","why":"The Latin adjective behind the word described movement back and forth, so the core of the noun is a going and a returning.","whyCN":"这个词背后的拉丁形容词描述来回移动，因此这个名词的核心就是「去」与「回」。"},{"no":"02","title":"Answering an act in kind","titleCN":"以同样的举动回应","definition":"responding to someone's gesture with a matching one, such as returning a smile, a greeting or a favour","definitionCN":"以相称的举动回应他人的举动，例如回以一个微笑、一声问候或一次帮忙","example":"She offered a seat, and reciprocity came at once in the form of a shared umbrella.","exampleCN":"她让出一个座位，对方立刻以共撑一把伞作为回应。","why":"At this scale reciprocity is not a contract but a reflex: the second gesture mirrors the first.","whyCN":"在这个尺度上，互惠不是契约而是一种反射：第二个举动照出第一个举动。"},{"no":"03","title":"Equal treatment between states","titleCN":"国与国之间的对等","definition":"the diplomatic rule that a state grants another the same treatment it receives, so that neither gains an advantage","definitionCN":"外交规则：一国给予另一国它所得到的同等对待，使任何一方都不占优势","example":"Visa waivers were granted on a basis of strict reciprocity.","exampleCN":"签证豁免是在严格对等的基础上给予的。","why":"Between sovereign states there is no higher authority, so equality has to be written into the exchange itself.","whyCN":"主权国家之上没有更高的权威，因此平等只能写进交换本身。"},{"no":"04","title":"The unwritten norm of return","titleCN":"社会互惠规范","definition":"in sociology, the shared expectation that a favour will be returned, which holds groups together without formal enforcement","definitionCN":"社会学中指「受助应当回报」的共同期待，它无需正式执行就能把群体维系起来","example":"The norm of reciprocity keeps neighbours shovelling each other's steps after a storm.","exampleCN":"互惠规范让邻居们在暴风雪后互相铲除对方门前的雪。","why":"A community cannot police every favour, so it runs on a shared expectation that returns will come.","whyCN":"社区无法对每一次帮忙都加以监督，于是靠一种共同期待运转：回报终会到来。"},{"no":"05","title":"A law that holds in both directions","titleCN":"数学中双向成立的互易定律","definition":"in mathematics, a theorem showing that a relation between two objects holds equally when the two are exchanged, as in the quadratic reciprocity law","definitionCN":"数学中指两个对象互换位置后关系仍同样成立的定理，如二次互反律","example":"The quadratic reciprocity law links pairs of primes in a way that works the same in either direction.","exampleCN":"二次互反律把成对的素数联系起来，无论从哪一方看，关系都同样成立。","why":"Mathematics kept the back-and-forth image but made it a statement about symmetry rather than about trading favours.","whyCN":"数学保留了「来回」的图景，却把它变成关于对称的命题，而不是关于互相帮忙。"},{"no":"06","title":"Reciprocal treatment under law","titleCN":"法律上的互惠待遇","definition":"the legal arrangement by which a right or benefit granted to foreigners is conditional on the same right being granted at home","definitionCN":"一种法律安排：给予外国人的权利或利益，以本国人在对方境内也获得同样权利为条件","example":"The treaty rests on reciprocity: each country lowers its tariff only if the other does the same.","exampleCN":"条约以互惠为基础：一方降税以另一方同样降税为条件。","why":"Law makes the return a condition rather than a courtesy, so non-reciprocity becomes a ground for withdrawal.","whyCN":"法律把回报设成条件而不是礼貌，因此不对等就成了撤回的理由。"},{"no":"07","title":"Feeling returned in equal measure","titleCN":"情感上的对等","definition":"the state in which affection, trust or regard is felt on both sides in comparable degree","definitionCN":"双方在相当程度上都怀有喜爱、信任或看重的情感状态","example":"What she valued was not reciprocity of gifts but reciprocity of regard.","exampleCN":"她看重的不是礼物的对等，而是彼此看重的对等。","why":"The same exchange image applies to feeling, where what returns cannot be weighed but can still be missed.","whyCN":"同一幅交换图景也适用于感情：回过来的东西无法称重，却仍能感到它的缺席。"},{"no":"08","title":"Equivalent return in economic exchange","titleCN":"经济上的等价回报","definition":"in economics, the requirement that what flows back be of comparable value, whether in trade, aid or investment","definitionCN":"经济学中指回流之物须具有相当价值的要求，无论涉及贸易、援助还是投资","example":"Aid without reciprocity can create lasting dependence rather than partnership.","exampleCN":"没有等价回报的援助，可能造成长期依赖而不是伙伴关系。","why":"Economics turns the moral idea of fairness into a measurable condition of comparable value.","whyCN":"经济学把公平这一道德观念，变成可衡量的「价值相当」条件。"}],"etymology":{"intro":{"en":"Reciprocity comes from French réciprocité, built on the adjective réciproque, which descends from Latin reciprocus 'moving back and forth, alternating'. The internal formation of reciprocus is not established: the common account joining re- 'back' to pro- 'forward' is a hypothesis, and no ancient source sets out the compound.","cn":"reciprocity 来自法语 réciprocité，由形容词 réciproque 构成，后者上溯到拉丁 reciprocus「往复的、交替的」。reciprocus 的内部构词并未得到确证：通常把它解释为 re-「回」加 pro-「向前」，但这只是一种假说，没有任何古代文献说明过这个词的构成。"},"items":[{"era":"LATIN RECIPROCUS","en":"Reciprocus described what moves back and forth or alternates between two points; it is the base of the whole English family.","cn":"reciprocus 描述在两个端点之间来回移动或交替的事物；它是整个英语词族的基础。"},{"era":"UNCERTAIN FORMATION","en":"Source uncertain: the familiar reading of the word as re- 'back' plus pro- 'forward' is a hypothesis, not a recorded derivation, and no other segmentation has been proven either.","cn":"来源不确定：把这个词读作 re-「回」加 pro-「向前」只是一种假说，并非有记录的派生过程，其他切分方式同样未获证明。"},{"era":"LATIN RECIPROCARE","en":"The verb reciprocare meant to move to and fro and also to give back in return; English reciprocate descends from it.","cn":"动词 reciprocare 意为「来回移动」，也指「回报」；英语的 reciprocate 由它而来。"},{"era":"FRENCH RÉCIPROCITÉ","en":"French passed réciprocité, built on the adjective réciproque, to English, where reciprocity first named a relation that runs both ways between two parties.","cn":"法语把由形容词 réciproque 构成的 réciprocité 传给英语，reciprocity 最初指两方之间可双向成立的关系。"},{"era":"MODERN LEGAL AND MATHEMATICAL USE","en":"Treaties of the nineteenth and twentieth centuries made reciprocity a term of art in international law, while mathematics fixed the reciprocal as a product of one.","cn":"十九与二十世纪的条约使 reciprocity 成为国际法上的专门术语，而数学则把「倒数」固定为乘积为一的关系。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date and deeper origin): the earliest English use cannot be assigned to an exact year, and the pre-Latin history of reciprocus is a reconstruction with no agreed form.","cn":"来源不确定（首见年代与更深词源）：最早的英语用例无法系于确切年份；reciprocus 在拉丁语之前的历史属重构，没有公认的形式。"}]},"similar":{"note":{"en":"Group one holds the true relatives built on the Latin adjective of going back and forth, plus two look-alikes that descend from a different verb meaning to receive, and those two must not be confused with this family. Group two holds words for exchange that differ in formality and in whether equality is required.","cn":"第一组是同出那个表示「来回」的拉丁形容词的真正同源词，另加两个形近词；后者出自另一个意为「接收」的动词，绝不可与这一词族混为一谈。第二组是表示交换的词，区别在于正式程度以及是否要求对等。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"reciprocal","ipa":"/rɪˈsɪprəkl/","tag":"same root, adjective","definition":"The adjective from the same Latin base: describing something given or felt in return, and in mathematics the inverse of a quantity.","definitionCN":"同出这一拉丁词基的形容词：形容回报或回应的东西，在数学中指一个量的倒数。"},{"word":"reciprocate","ipa":"/rɪˈsɪprəkeɪt/","tag":"same root, verb","definition":"The verb from the same base: to give or feel something in return, or of a machine, to move back and forth.","definitionCN":"同出这一词基的动词：回报或回应某种情感；用于机器时指往复运动。"},{"word":"reciprocation","ipa":"/ˌresɪprəˈkeɪʃn/","tag":"same root, noun of action","definition":"The noun for the act of returning something; it names one act, while reciprocity can name a standing relation between parties.","definitionCN":"指「回报」这一动作的名词；它指一次动作，而 reciprocity 可指双方之间长期存在的关系。"},{"word":"recipient","ipa":"/rɪˈsɪpiənt/","tag":"different root, look-alike","definition":"From Latin recipere 'to receive', built on re- plus capere 'to take'; it names the one who receives and has nothing to do with returning anything.","definitionCN":"来自拉丁 recipere「接收」，由 re- 加 capere「抓取」构成；它指接收者，与回报毫无关系。"},{"word":"recipe","ipa":"/rɪˈsiːpi/","tag":"different root, look-alike","definition":"Also from recipere, literally 'take this'; the shared opening syllables are misleading, since its root is the taking verb, not the back-and-forth adjective.","definitionCN":"同样来自 recipere，字面意为「取这些」；开头音节相同只是误导，它的词根是「抓取」动词，而不是那个表示来回的形容词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"mutual","ipa":"/ˈmjuːtʃuəl/","tag":"shared in both directions","definition":"Describing something held or felt by two parties at once, such as mutual respect; it states the sharing but not the rule of return.","definitionCN":"形容两方同时拥有或感受到的东西，如相互尊重；它陈述共享，却不含回报规则。"},{"word":"exchange","ipa":"/ɪksˈtʃeɪndʒ/","tag":"the transaction itself","definition":"The act of giving one thing and receiving another; it names the transaction, while reciprocity names the principle that the two sides balance.","definitionCN":"给出一样并得到另一样的行为；它指交易本身，而 reciprocity 指两边应当平衡的原则。"},{"word":"quid pro quo","ipa":"/ˌkwɪd prəʊ ˈkwəʊ/","tag":"this for that, often legal","definition":"A thing given in return for something specific, often with a legal or political flavour; it is the concrete instance, reciprocity the general rule.","definitionCN":"为换取某一具体之物而给出的东西，常带法律或政治色彩；它是具体的一例，而 reciprocity 是一般规则。"},{"word":"give-and-take","ipa":"/ˌɡɪv ən ˈteɪk/","tag":"informal compromise","definition":"An informal phrase for mutual concession in a relationship; it stresses willingness to bend, not exact equality.","definitionCN":"指关系中互相让步的口语说法；它强调愿意退让，而不是精确对等。"},{"word":"symmetry","ipa":"/ˈsɪmətri/","tag":"balance of form","definition":"A correspondence of parts on either side of a line or point; it describes shape and balance, not an obligation to return a favour.","definitionCN":"指一条线或一个点两侧部分的对应；它描述形状与均衡，而不是回报人情的义务。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Latin base with its uncertain internal story, the genuine family, the two look-alikes from the receiving verb, and the legal and mathematical uses that fixed the term.","cn":"正常联想：真实的拉丁词基及其未获确证的内部构成、真正的同族词、两个来自「接收」动词的形近词，以及让这个词定型的法律与数学用法。"},"normal":[{"en":"The Latin base describes movement back and forth, so reciprocity is a going out and a coming back, never a one-way gift.","cn":"这个拉丁词基描述来回移动，所以互惠是「去」与「回」，绝不是单向的赠予。"},{"en":"The internal division into back plus forward is only a hypothesis, so learn the whole base rather than a made-up root.","cn":"把它切成「回」加「向前」只是假说，因此要记整个词基，而不是一个人为拼出的词根。"},{"en":"The family runs reciprocal, reciprocally, reciprocate, reciprocation and reciprocative.","cn":"同族词包括 reciprocal、reciprocally、reciprocate、reciprocation 与 reciprocative。"},{"en":"Recipient and recipe look similar but come from the verb meaning to receive, so they are not relatives of this family.","cn":"recipient 与 recipe 看着相似，却出自意为「接收」的动词，因此不是这个词族的同源词。"},{"en":"Fixed phrases mark the frame: on the basis of reciprocity, the principle of reciprocity, social reciprocity, expect reciprocity.","cn":"固定搭配标出框架：在互惠基础上、互惠原则、社会互惠、期待对等回报。"}],"abstract":[{"en":"Picture two doors facing each other across a courtyard, opening at the same moment.","cn":"想象两扇隔着院子的门正对着，在同一刻同时打开。"},{"en":"Picture a scale with two identical pans, and neither side ever stays down for long.","cn":"想象一杆两边托盘一模一样的秤，没有哪一边能长久地压着。"},{"en":"Picture a ball thrown against a wall and coming back with the same force it was given.","cn":"想象一个球撞上墙，带着被扔出去时同样的力道弹回来。"}]},"examples":[{"en":"The scholarship scheme runs on reciprocity: graduates later fund a student of their own.","cn":"这项奖学金以互惠方式运转：受助者毕业后再资助一名学生。"},{"en":"Diplomats spoke of reciprocity rather than generosity, because each concession had to be matched.","cn":"外交官谈的是对等而非慷慨，因为每一项让步都必须得到对等回应。"},{"en":"In the algebra chapter, reciprocity simply means that a number and its inverse multiply to one.","cn":"在代数那一章里，互易性只是指一个数与它的逆相乘为一。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「来回 + 相应」——东西送出去还要回得来，一分对一分，就是互惠与对等","word":"reciprocity"},"root":"拉丁 reciprocus「往复的、交替的」，经法语 réciproque 进入英语。其内部构词来源不确定：一般认为与 re-（回）+ pro-（向前）有关，但这只是假说，并非有记录的派生，不得据此编造词根。同族的 reciprocal、reciprocate 出此词基；recipient、recipe 出 recipere = re- + capere「抓取」，与 reciprocus 不同源。","sensesIntro":{"en":"Eight senses follow one movement: something goes out and something comes back. The return may be a gift, a mirrored gesture, a matching tariff, an unwritten social norm, an inverse in algebra, a legal condition, an equal affection, or a comparable economic value.","cn":"八个义项沿同一个动作展开：有东西送出去，就有东西回来。回程之物可以是一份礼物、一个照做的举动、一项对等的关税、一条不成文的社会规范、代数里的逆、一项法律条件、一份对等的情感，或一种相当的经济价值。"},"semanticMap":{"core":{"en":"CORE IMAGE: two hands pushing equal things across a table at the same moment.","cn":"核心意象：两只手在同一刻把等分量的东西推过桌面。"},"chain":["GIVE SOMETHING OUT","ANSWER IN KIND","MATCH THE TARIFF","THE UNWRITTEN NORM","THE INVERSE PAIR","RETURN THE VALUE"],"branches":[{"senses":"01 · 02","en":"GIFT AND GESTURE: the everyday exchange, from a returned favour to a returned smile.","cn":"礼物与举动：从回赠一份人情，到回以一个微笑的日常交换。"},{"senses":"03 · 06","en":"BETWEEN POWERS: states and legal systems make the return a condition rather than a courtesy.","cn":"权力之间：国家与法律体系把回报设成条件，而不是礼貌。"},{"senses":"04","en":"THE SOCIAL NORM: no authority enforces it, yet the expectation of return holds the group together.","cn":"社会规范：没有权威执行，然而「终会回报」的期待把群体维系在一起。"},{"senses":"05","en":"THE EXACT INVERSE: algebra keeps the back-and-forth image and makes the return land on one.","cn":"精确的逆：代数保留来回的图景，让回程落在「一」上。"},{"senses":"07 · 08","en":"FEELING AND VALUE: what comes back can be regard that cannot be weighed, or money that must be.","cn":"情感与价值：回过来的可以是无法称重的看重，也可以是必须称重的钱。"}]},"affixes":{"intro":{"en":"Reciprocity is a Latin-derived noun whose base, verb and adjective endings are shared across a small but stable English family; its internal prefix story must be marked as uncertain.","cn":"reciprocity 是一个源自拉丁语的名词，其词基、动词与形容词词尾在一个小而稳定的英语词族中共享；其内部前缀的说法必须标为不确定。"},"latinIntro":{"en":"Latin reciprocus supplies the back-and-forth image, reciprocare adds the verbal action of returning, and the noun ending turns the relation into a named principle.","cn":"拉丁 reciprocus 提供「来回」的图景，reciprocare 添上「回报」这一动作，名词词尾则把这种关系变成一个被命名的原则。"},"items":[{"word":"re-","structure":"re- (Latin prefix, 'back, again')","meaning":"back; again","meaningCN":"回；再","example":"This prefix is part of the usual but unproven reading of the base.","exampleCN":"这个前缀属于对该词基通常却未获证明的读法。"},{"word":"pro-","structure":"pro- (Latin prefix, 'forward, before')","meaning":"forward","meaningCN":"向前","example":"The forward half of the image is proposed rather than recorded.","exampleCN":"图景中「向前」的那一半是推测出来的，而非有记录的。"},{"word":"reciprocus","structure":"reciprocus (Latin adjective, formation uncertain)","meaning":"moving back and forth; alternating","meaningCN":"往复的；交替的","example":"The adjective names a movement that returns to where it started.","exampleCN":"这个形容词指一种回到起点的移动。"},{"word":"reciprocare","structure":"reciprocus + verbal ending","meaning":"to move to and fro; to give in return","meaningCN":"来回移动；回报","example":"The verb turns the image into an action someone performs.","exampleCN":"这个动词把图景变成某人可以执行的动作。"},{"word":"reciprocity","structure":"reciprocus + -itas (noun of quality)","meaning":"the quality of mutual return","meaningCN":"互惠这一性质","example":"The treaty rests on reciprocity: each country lowers its tariff only if the other does the same.","exampleCN":"条约以互惠为基础：一方降税以另一方同样降税为条件。"},{"word":"reciprocal","structure":"reciprocus + -al (adjective ending)","meaning":"given or felt in return","meaningCN":"回报的；对等的","example":"The two universities signed a reciprocal agreement.","exampleCN":"两所大学签署了一份对等协议。"},{"word":"reciprocate","structure":"reciprocare through English","meaning":"to return a favour or feeling","meaningCN":"回报人情或情感","example":"She reciprocated the invitation the following spring.","exampleCN":"次年春天她回请了对方。"},{"word":"reciprocation","structure":"reciprocate + -ion (noun of action)","meaning":"the act of returning something","meaningCN":"回报这一动作","example":"His reciprocation was prompt and modest.","exampleCN":"他的回报既迅速又谦和。"}],"latinEntries":[{"word":"reciprocus","structure":"reciprocus, reciproca, reciprocum (adjective, first and second declension)","meaning":"moving back and forth, alternating","meaningCN":"往复的；交替的"},{"word":"reciprocare","structure":"reciprocare, reciprocavi, reciprocatum (verb, first conjugation)","meaning":"to move to and fro; to return","meaningCN":"来回移动；回报"},{"word":"reciprocatio","structure":"reciprocatio, reciprocationis (f., third declension)","meaning":"a returning; reciprocal movement","meaningCN":"回报；往复运动"}],"derivatives":[{"word":"reciprocal","pos":"adj./n.","zh":"互惠的；对等的；倒数"},{"word":"reciprocally","pos":"adv.","zh":"对等地"},{"word":"reciprocate","pos":"v.","zh":"回报；往复"},{"word":"reciprocation","pos":"n.","zh":"回报；往复"},{"word":"reciprocative","pos":"adj.","zh":"有回报倾向的"}]}}]);
